/**
 * READ-ONLY inspection of OVH's two per-IP upstream filters:
 *
 *  1. the GAME firewall   `/ip/{ip}/game/{ip}` (+ `/rule`)   — field `firewallModeEnabled`
 *  2. the NETWORK firewall `/ip/{ip}/firewall[/{ip}]`        — field `enabled`
 *
 * Why this exists (2026-10-04): node-4's game firewall was in STRICT mode with a
 * single stale rule (`other:20055-20055`). In strict mode OVH drops every UDP
 * port that no rule allows, at the provider edge, so every UDP game on the node
 * was unreachable from the internet while the primary's own probes still worked
 * and the servers looked healthy. Nothing in the platform looked at it.
 *
 * HARD RULE: this module only ever issues HTTP GET. There is no helper here (and
 * there must never be one) that changes a mode or a rule — turning strict mode
 * off is a production change that needs explicit owner approval.
 *
 * Layout: pure parsing + verdicts (no I/O, unit-tested with fixtures in
 * test/ovh-game-firewall.test.ts), a thin GET-only HTTP layer that takes an
 * injectable getter, and `listGameFirewallForNode` for the DB-backed IP list.
 */
import { ovh, OvhHttpError, ovhConfigured } from "./ovh";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type GameRule = {
  id: number | string;
  protocol: string | null;
  portFrom: number | null;
  portTo: number | null;
  /** OVH game rules carry no action (they are allow-rules); null unless OVH ever returns one. */
  action: string | null;
  state: string | null;
};

export type GameFirewall = {
  ip: string;
  /** false = OVH has no game object for this IP, i.e. no game firewall is enforced. */
  exists: boolean;
  firewallModeEnabled: boolean | null;
  /** OVH state: ok | firewallModeDisablePending | firewallModeEnablePending | ... */
  state: string | null;
  maxRules: number | null;
  rules: GameRule[];
};

export type NetworkFirewallRule = {
  id: number | string;
  sequence: number | null;
  action: string | null; // permit | deny
  protocol: string | null;
  source: string | null;
  destinationPort: string | null;
  state: string | null;
};

export type NetworkFirewall = {
  ip: string;
  /** false = the IP is not on OVH's network firewall at all. */
  exists: boolean;
  enabled: boolean | null;
  state: string | null;
  rules: NetworkFirewallRule[];
};

export type Level = "PASS" | "WARN" | "FAIL";
export type Verdict = { level: Level; summary: string; remediation?: string };

export type IpFirewallReport =
  | {
      ip: string;
      ok: true;
      game: GameFirewall;
      network: NetworkFirewall;
      gameVerdict: Verdict;
      networkVerdict: Verdict;
    }
  | { ip: string; ok: false; error: string };

// ---------------------------------------------------------------------------
// Pure parsing
// ---------------------------------------------------------------------------

const num = (v: unknown): number | null => (typeof v === "number" && Number.isFinite(v) ? v : null);
const str = (v: unknown): string | null => (typeof v === "string" ? v : null);

/**
 * `gameBody` = GET /ip/{ip}/game/{ip}; `ruleBodies` = GET .../rule/{id} for each id.
 * Pass `gameBody = null` for a 404 (no game object).
 */
export function parseGameFirewall(ip: string, gameBody: any | null, ruleBodies: readonly any[] = []): GameFirewall {
  if (!gameBody || typeof gameBody !== "object") {
    return { ip, exists: false, firewallModeEnabled: null, state: null, maxRules: null, rules: [] };
  }
  return {
    ip,
    exists: true,
    firewallModeEnabled: typeof gameBody.firewallModeEnabled === "boolean" ? gameBody.firewallModeEnabled : null,
    state: str(gameBody.state),
    maxRules: num(gameBody.maxRules),
    rules: ruleBodies
      .filter((r) => r && typeof r === "object")
      .map((r) => ({
        id: r.id ?? "?",
        protocol: str(r.protocol),
        portFrom: num(r.ports?.from),
        portTo: num(r.ports?.to),
        action: str(r.action),
        state: str(r.state),
      })),
  };
}

/** `listBody` = GET /ip/{ip}/firewall (array of IPs on the firewall); `detail` = GET /ip/{ip}/firewall/{ip}. */
export function parseNetworkFirewall(
  ip: string,
  listBody: unknown,
  detail: any | null,
  ruleBodies: readonly any[] = []
): NetworkFirewall {
  const onFirewall = Array.isArray(listBody) && listBody.includes(ip);
  if (!onFirewall || !detail || typeof detail !== "object") {
    return { ip, exists: false, enabled: null, state: null, rules: [] };
  }
  return {
    ip,
    exists: true,
    enabled: typeof detail.enabled === "boolean" ? detail.enabled : null,
    state: str(detail.state),
    rules: ruleBodies
      .filter((r) => r && typeof r === "object")
      .map((r) => ({
        id: r.sequence ?? r.id ?? "?",
        sequence: num(r.sequence),
        action: str(r.action),
        protocol: str(r.protocol),
        source: str(r.source),
        destinationPort: str(r.destinationPort),
        state: str(r.state),
      })),
  };
}

export function describeGameRule(r: GameRule): string {
  const ports = r.portFrom === null ? "?" : r.portTo === null || r.portTo === r.portFrom ? `${r.portFrom}` : `${r.portFrom}-${r.portTo}`;
  return `${r.protocol ?? "?"}:${ports}${r.action ? ` (${r.action})` : ""}`;
}

// ---------------------------------------------------------------------------
// Pure verdicts
// ---------------------------------------------------------------------------

/** Exact operator remediation for a strict-mode game firewall. Plain ASCII on purpose (goes to logs, mail, shell). */
export function strictModeRemediation(ip: string): string {
  const e = encodeURIComponent(ip);
  return (
    `OVH game firewall STRICT MODE is ON for ${ip}: OVH drops every UDP port not allowed by a rule, at the provider edge, ` +
    `so UDP game servers on this IP are unreachable from the internet while the host and its own probes look healthy. ` +
    `Look at: OVH manager > Bare Metal Cloud > IP > ${ip} > "..." > Game firewall (or read-only API: GET /ip/${e}/game/${e} and GET /ip/${e}/game/${e}/rule). ` +
    `Fix = either turn strict mode OFF (PUT /ip/${e}/game/${e} {"firewallModeEnabled":false}; OVH goes firewallModeDisablePending -> ok in ~1 minute) ` +
    `or add an allow-rule for every UDP port in use. Turning it off changes production traffic filtering and REQUIRES OWNER APPROVAL - do not change it unasked. ` +
    `Re-run scripts/verify-node.sh and probe a UDP game from two other nodes (scripts/udp-reach-probe.sh) afterwards.`
  );
}

export function gameFirewallVerdict(g: GameFirewall): Verdict {
  if (!g.exists) {
    return { level: "PASS", summary: `${g.ip}: no OVH game firewall object (not enforced)` };
  }
  const state = g.state ?? "unknown";
  const rules = g.rules.length ? `${g.rules.length} rule(s): ${g.rules.map(describeGameRule).join(", ")}` : "no rules";
  const stateLc = state.toLowerCase();
  if (g.firewallModeEnabled === true) {
    if (stateLc.includes("disablepending")) {
      return { level: "WARN", summary: `${g.ip}: strict mode still ON but a disable is pending (${state}; ${rules}) - re-check in ~1 minute` };
    }
    return {
      level: "FAIL",
      summary: `${g.ip}: OVH game firewall STRICT MODE is ON (state ${state}; ${rules}) - all other UDP is dropped upstream`,
      remediation: strictModeRemediation(g.ip),
    };
  }
  if (g.firewallModeEnabled === null) {
    return { level: "WARN", summary: `${g.ip}: OVH game firewall mode could not be determined (state ${state})` };
  }
  if (stateLc !== "ok") {
    return {
      level: "WARN",
      summary: `${g.ip}: strict mode is off but OVH reports state ${state} (${rules}) - pending change; re-check in ~1 minute` +
        (stateLc.includes("enablepending") ? " (it is about to turn STRICT ON)" : ""),
    };
  }
  return { level: "PASS", summary: `${g.ip}: OVH game firewall strict mode off (state ok; ${rules})` };
}

export function networkFirewallVerdict(n: NetworkFirewall): Verdict {
  if (!n.exists) return { level: "PASS", summary: `${n.ip}: not on the OVH network firewall` };
  const deny = n.rules.filter((r) => r.action === "deny").length;
  const permit = n.rules.filter((r) => r.action === "permit").length;
  const rules = `${n.rules.length} rule(s) (${permit} permit, ${deny} deny)`;
  const state = n.state ?? "unknown";
  if (n.enabled === true) {
    return {
      level: "WARN",
      summary: `${n.ip}: OVH NETWORK firewall is ENABLED (state ${state}; ${rules}) - it can drop customer traffic upstream`,
      remediation:
        `Review with read-only GET /ip/${encodeURIComponent(n.ip)}/firewall/${encodeURIComponent(n.ip)}/rule (or OVH manager > IP > ${n.ip} > Firewall). ` +
        `Make sure the rules permit the ports customers use (TCP+UDP game ports, SSH forwards, 80/443, ICMP). ` +
        `Disabling or editing it is a production change that REQUIRES OWNER APPROVAL.`,
    };
  }
  if (n.enabled === null) return { level: "WARN", summary: `${n.ip}: OVH network firewall state could not be determined (${state})` };
  if (state.toLowerCase() !== "ok") return { level: "WARN", summary: `${n.ip}: network firewall disabled but OVH reports state ${state} - pending change` };
  return { level: "PASS", summary: `${n.ip}: OVH network firewall present but disabled (${rules})` };
}

export function worstLevel(levels: readonly Level[]): Level {
  return levels.includes("FAIL") ? "FAIL" : levels.includes("WARN") ? "WARN" : "PASS";
}

// ---------------------------------------------------------------------------
// GET-only HTTP layer
// ---------------------------------------------------------------------------

/** The only OVH entry point in this file. Method is hard-wired to GET. */
export type OvhGet = (path: string) => Promise<any>;
export const defaultOvhGet: OvhGet = (path) => ovh("GET", path);

const enc = encodeURIComponent;
const MAX_RULE_READS = 40;

/** Run `fn`; a 404 yields `null`, anything else propagates. */
async function orNull<T>(fn: () => Promise<T>): Promise<T | null> {
  try {
    return await fn();
  } catch (e: any) {
    if (e instanceof OvhHttpError ? e.status === 404 : /-> 404:/.test(String(e?.message))) return null;
    throw e;
  }
}

/**
 * Read one IP's game firewall. 404 (no game object) => `exists:false`. Any other
 * OVH/network error propagates so the caller can treat "could not read" separately
 * from "not enforced" (absence of evidence is never a PASS in the sweep).
 */
export async function getGameFirewall(ip: string, get: OvhGet = defaultOvhGet): Promise<GameFirewall> {
  const e = enc(ip);
  const game = await orNull(() => get(`/ip/${e}/game/${e}`));
  if (!game) return parseGameFirewall(ip, null);
  const ids = (await orNull(() => get(`/ip/${e}/game/${e}/rule`))) ?? [];
  const bodies: any[] = [];
  for (const id of (Array.isArray(ids) ? ids : []).slice(0, MAX_RULE_READS)) {
    const b = await orNull(() => get(`/ip/${e}/game/${e}/rule/${enc(String(id))}`));
    if (b) bodies.push({ id, ...b });
  }
  return parseGameFirewall(ip, game, bodies);
}

export async function getNetworkFirewall(ip: string, get: OvhGet = defaultOvhGet): Promise<NetworkFirewall> {
  const e = enc(ip);
  const list = await orNull(() => get(`/ip/${e}/firewall`));
  if (!Array.isArray(list) || !list.includes(ip)) return parseNetworkFirewall(ip, list, null);
  const detail = await orNull(() => get(`/ip/${e}/firewall/${e}`));
  const bodies: any[] = [];
  // Rules are only worth reading when the firewall is actually enforcing.
  if (detail?.enabled === true) {
    const seqs = (await orNull(() => get(`/ip/${e}/firewall/${e}/rule`))) ?? [];
    for (const seq of (Array.isArray(seqs) ? seqs : []).slice(0, MAX_RULE_READS)) {
      const b = await orNull(() => get(`/ip/${e}/firewall/${e}/rule/${enc(String(seq))}`));
      if (b) bodies.push({ sequence: seq, ...b });
    }
  }
  return parseNetworkFirewall(ip, list, detail, bodies);
}

/** Read both filters for one IP. Never throws: failure becomes `{ok:false,error}`. */
export async function checkIpFirewalls(ip: string, get: OvhGet = defaultOvhGet): Promise<IpFirewallReport> {
  try {
    const game = await getGameFirewall(ip, get);
    const network = await getNetworkFirewall(ip, get);
    return { ip, ok: true, game, network, gameVerdict: gameFirewallVerdict(game), networkVerdict: networkFirewallVerdict(network) };
  } catch (e: any) {
    return { ip, ok: false, error: String(e?.message ?? e).slice(0, 300) };
  }
}

// ---------------------------------------------------------------------------
// Per-node listing (DB-backed)
// ---------------------------------------------------------------------------

export type NodeFirewallEntry = {
  ip: string;
  source: "node" | "pool";
  /** DedicatedIp.status / purpose for pool rows. */
  poolStatus?: string;
  purpose?: string;
  report: IpFirewallReport;
};

export type NodeFirewallResult =
  | { applicable: false; reason: string; entries: [] }
  | { applicable: true; entries: NodeFirewallEntry[] };

/** The deduplicated IP list for a node: its public IP first, then every DedicatedIp row (any status/purpose). */
export function nodeIpTargets(
  node: { publicIp: string },
  pool: readonly { address: string; status?: string; purpose?: string }[]
): { ip: string; source: "node" | "pool"; poolStatus?: string; purpose?: string }[] {
  const out: { ip: string; source: "node" | "pool"; poolStatus?: string; purpose?: string }[] = [];
  const seen = new Set<string>();
  const add = (ip: string, rest: { source: "node" | "pool"; poolStatus?: string; purpose?: string }) => {
    const v = ip.trim();
    if (!v || seen.has(v)) return;
    seen.add(v);
    out.push({ ip: v, ...rest });
  };
  add(node.publicIp, { source: "node" });
  for (const p of pool) add(p.address, { source: "pool", poolStatus: p.status, purpose: p.purpose });
  return out;
}

/**
 * Check a node's own public IP and every DedicatedIp row on it (FREE and ASSIGNED,
 * any purpose). Non-OVH nodes (Hetzner) are not applicable. READ-ONLY toward OVH.
 * `nodeRef` is a Node.id or Node.name.
 */
export async function listGameFirewallForNode(nodeRef: string, get: OvhGet = defaultOvhGet): Promise<NodeFirewallResult> {
  const { db } = await import("./db"); // lazy: keep the pure parts importable without Prisma
  const node = await db.node.findFirst({ where: { OR: [{ id: nodeRef }, { name: nodeRef }] }, select: { id: true, provider: true, publicIp: true } });
  if (!node) throw new Error(`no Node matching '${nodeRef}'`);
  if (node.provider !== "OVH") return { applicable: false, reason: `provider is ${node.provider}, not OVH`, entries: [] };
  const pool = await db.dedicatedIp.findMany({ where: { nodeId: node.id }, select: { address: true, status: true, purpose: true }, orderBy: { address: "asc" } });
  return { applicable: true, entries: await checkTargets(nodeIpTargets(node, pool), get) };
}

/** Sequential on purpose (a handful of IPs; keeps us far under OVH rate limits). */
export async function checkTargets(
  targets: ReturnType<typeof nodeIpTargets>,
  get: OvhGet = defaultOvhGet
): Promise<NodeFirewallEntry[]> {
  const out: NodeFirewallEntry[] = [];
  for (const t of targets) out.push({ ...t, report: await checkIpFirewalls(t.ip, get) });
  return out;
}

export { ovhConfigured };
/**
 * OVH upstream-firewall sweep (hourly). READ-ONLY toward OVH (GET only).
 *
 * For every enabled OVH node: read the node's public IP and every DedicatedIp row
 * on it, raise a debounced, auto-resolving admin alert (via lib/fleet-alert-plan.ts,
 * dimension prefixes OVH-GAME-FW: / OVH-NET-FW:) when
 *   - the game firewall is in STRICT mode (OVH drops all UDP not on a rule), or
 *   - the network firewall is enabled (WARN).
 * Incident: 2026-10-04, node-4 strict mode silently black-holed every UDP game.
 *
 * Default ON (it only reads); turn off with Setting `ovh_game_firewall_check_enabled` = false.
 * Failure-silent: an OVH outage / slow API logs and returns; it can never throw into
 * or stall the sweep runner (hard overall deadline below).
 */
import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { getSettingBool } from "../lib/settings";
import { ovhConfigured } from "../lib/ovh";
import { planFleetAlerts } from "../lib/fleet-alert-plan";
import { checkTargets, nodeIpTargets } from "../lib/ovh-game-firewall";
import { desiredOvhFirewallAlerts, type NodeFirewallReading } from "../lib/ovh-firewall-alert-plan";
import { applyFleetAlerts, openFleetAlerts } from "./fleet-alerts";

export const OVH_FW_SWEEP_DEADLINE_MS = 5 * 60_000;
export const OVH_FW_SETTING = "ovh_game_firewall_check_enabled";

export async function ovhGameFirewallSweep(): Promise<void> {
  if (SANDBOX || !ovhConfigured()) return;
  try {
    if (!(await getSettingBool(OVH_FW_SETTING, true))) return;
    const work = runSweep();
    // Hard deadline: if OVH hangs we stop waiting (the pending fetches have their own 30 s timeouts).
    let timer: NodeJS.Timeout | undefined;
    const deadline = new Promise<"timeout">((res) => { timer = setTimeout(() => res("timeout"), OVH_FW_SWEEP_DEADLINE_MS); });
    const r = await Promise.race([work.then(() => "done" as const), deadline]);
    if (timer) clearTimeout(timer);
    if (r === "timeout") console.error("[ovh-fw] sweep exceeded its deadline; skipped this round");
  } catch (e) {
    console.error("[ovh-fw] sweep failed (ignored)", e instanceof Error ? e.message : e);
  }
}

async function runSweep(): Promise<void> {
  const nodes = await db.node.findMany({
    where: { enabled: true, provider: "OVH" },
    select: { id: true, name: true, publicIp: true, dedicatedIps: { select: { address: true, status: true, purpose: true } } },
  });
  const readings: NodeFirewallReading[] = [];
  for (const n of nodes) {
    const entries = await checkTargets(nodeIpTargets(n, n.dedicatedIps.map((d) => ({ address: d.address, status: d.status, purpose: d.purpose }))));
    readings.push({ nodeId: n.id, nodeName: n.name, entries });
    for (const e of entries) {
      if (!e.report.ok) console.error(`[ovh-fw] ${n.name} ${e.ip}: could not read (${e.report.error})`);
      else if (e.report.gameVerdict.level === "FAIL") console.error(`[ovh-fw] ${n.name}: ${e.report.gameVerdict.summary}`);
    }
  }
  const { desired, readNodeIds } = desiredOvhFirewallAlerts(readings);
  const all = await openFleetAlerts();
  const ops = planFleetAlerts({
    desired,
    open: all,
    readNodeIds,
    nodeNames: new Map(nodes.map((n) => [n.id, n.name])),
    now: new Date(),
  });
  await applyFleetAlerts(ops);
}

# Nxeon — VPS hosting platform

Hostinger-style VPS hosting platform running on this Proxmox VE 9 dedicated server (OVH KS-GAME, i7-7700K, 64GB RAM, 2×450GB NVMe ZFS mirror + 4TB HDD backup pool).

## Architecture

- **Web panel**: Next.js 15 (App Router, server actions) + Tailwind v4, served by `nxeon-web.service` on port 3000, behind nginx on port 80. Public IP: 51.79.162.96.
- **Worker**: `worker/index.ts` run by `nxeon-worker.service` (as root — it manages iptables). Polls the `Job` table every 3s and executes provisioning/lifecycle jobs against the Proxmox API.
- **DB**: PostgreSQL 17, database `nxeon`, Prisma ORM ([prisma/schema.prisma](prisma/schema.prisma)). Use `npm run db:push` after schema changes.
- **Proxmox**: API token auth (`nxeon@pve!platform`, creds in `.env`). Templates: VMID 9000 (Ubuntu 24.04), 9001 (Debian 13), cloud-init based, cloned onto ZFS storage `vmdata`.
- **Networking**: VMs attach to NAT bridge `vmbr1` (10.20.0.0/24, gateway .1). IPs allocated from 10.20.0.100–250 ([lib/ipam.ts](lib/ipam.ts)). SSH exposed via DNAT port forwards 20000–29999 in iptables chain `NXEON_FWD`, rebuilt from DB by [worker/network.ts](worker/network.ts) — never edit that chain by hand.
- **Cloud-init**: vendor snippet at `/tank/backup/snippets/nxeon-vendor.yaml` (installs qemu-guest-agent, enables root password SSH).

## Portals & design system

**As of 2026-09-14, the customer portal is the "Nexion" redesign** — previously developed in isolation on a separate box (node-2, `/opt/nxeon-v2`, branch `design/v2`) and merged into `main` once it was fully audited and verified. Read this section before touching any shared styling — it is the difference between an edit that stays contained and one that silently reaches marketing, login, or admin.

- **Two portals, two shells, deliberately unmerged:**
  - `app/admin/**` (admin ops portal) still renders through `components/portal/Shell.tsx` — the ORIGINAL, pre-redesign chrome. Marketing (`app/(marketing)/**`), `/login`, `/register` and admin must stay pixel-identical to how they looked before the redesign. Never edit these expecting Nexion's visual language to apply, and never move Nexion-only styling into a place they can see it.
  - `app/dashboard/**` (customer portal) renders through `components/nx/Shell.tsx` — the Nexion redesign. This is where the new design system, its components (`components/nx/*`), and its color/animation language live.
  - **A component added to one shell must be added to the other if it's meant to exist on both.** This has silently broken things before: `ComposeProvider`, `TerminalDockProvider`, `MatrixProvider` were each added to `components/portal/Shell.tsx` first and forgotten on `components/nx/Shell.tsx`, taking a whole feature down invisibly (the crash only appeared on a route a smoke test didn't walk).

- **The scoping trick that keeps the two visually separate — `app/globals.css`, `:root:has(.nx-shell-root)`:**
  Nexion's own colors/tokens and its overrides of shared component classes (`.card`, `.btn-primary`, `.input`, etc.) are NOT bare rules — they're wrapped in `:root:has(.nx-shell-root) { ... }`, a selector that only matches when a `.nx-shell-root` element (rendered only by `components/nx/Shell.tsx`) exists anywhere on the page. That's the entire mechanism keeping marketing/login/admin rendering their original, pre-redesign styles: **do not write a new bare rule for a class both portals share** (e.g. a bare `.card { ... }` outside this scope) — it will apply everywhere, including where it was never meant to.
  - Light mode has its own nested scope for the same reason: `:root:has(.nx-shell-root)[data-theme="light"]`, NOT a bare `html[data-theme="light"]`. The bare form loses a CSS specificity fight to the dark `:has()` block regardless of which theme is active — this was a real, session-spanning bug (several "light mode doesn't work on page X" reports all had this one root cause) before it was scoped correctly.
  - `.nx-dark-island` is a third scope, deliberately staying dark inside the Nexion portal even when light mode is active (site headers, page hero banners) — it re-declares the relevant tokens back to dark values inside `html[data-theme="light"] .nx-dark-island { ... }`. Add a new always-dark token here too if you introduce one (see `--color-neon-bug` for the pattern: declared in the base `@theme` block, overridden lighter in the light-mode scope, re-declared back to its bright value inside `.nx-dark-island`).

- **CSS/JS landmines hit (and fixed) building this — avoid repeating them:**
  - **`@keyframes` and `@property` are not valid nested inside a plain style rule** — only inside `@layer`/`@media`/other at-rules. Nesting one inside `:root:has(...) { }` (or any class selector) silently drops it at build time — no error, the animation just never plays, forever, with every other signal (computed `animation-name`, `animation-play-state: running`) looking correct. This broke ~34 animations at once (a levitating icon, the page preloader, several status dots) when a broad `:has()` refactor accidentally wrapped them. If an animation looks "stuck on frame one," check whether its `@keyframes` block ended up nested inside a style rule.
  - **`backdrop-filter` on an ancestor creates a new containing block for `position: fixed` descendants.** A `.card` with `backdrop-blur-md` breaks any non-portaled modal/overlay nested inside it (it pins to the card instead of the viewport). Fix: cancel the inherited `backdrop-filter` on the offending class, or `createPortal` the fixed element to `document.body`.
  - **A positioned `fixed; z-0` decorative background (an aurora/globe effect) paints above ordinary static content** unless the real content wrapper gets `relative z-[1]`.
  - **Hydration-mismatch anti-pattern**: `useState(() => { if (typeof window === "undefined") return X; ...read window/URL...; return Y; })` — the server always takes the `X` branch, the client's first render always takes `Y`, guaranteed mismatch. Read the value server-side (a Server Component's `searchParams` prop) and pass it down as a real prop instead.
  - Percentage-based `transform: translateY(%)` inside a flex item whose container has no defined width/height resolves against 0 and silently does nothing — give the container a real dimension (e.g. `inset-0` instead of `inset-y-0 right-0` alone) before debugging the animation itself.
  - `git commit -m` with backticks in the message breaks — write the message to a file and use `git commit -F`.
  - Bash `cwd` does not persist between tool calls in an agent session — always `cd /opt/nxeon && ...` in the same command.

- Design system tokens/classes live in `app/globals.css` + `components/ui/primitives.tsx` (shared/production) and `components/nx/*` (Nexion-only). Charts are dependency-free SVG (`components/ui/charts.tsx`) — do not add a charting library.
- Admin impersonation: `impersonateUser()` sets a signed cookie; `currentUser()` returns the target, `realUser()` the actual admin; banner + exit handled in Shell. Admin pages call `realUser`/`requireAdmin` and refuse to render while impersonating.
- Metrics come from Proxmox RRD via `/api/metrics` (node for admins, per-server for owners). A server with no `vmid` yet is not "not found" — it's "not provisioned yet," and gets a `{data: [], unavailable: true}` 200 response, not a 404 (a 404 there caused a permanent client poll loop; same fix applied to `/api/servers/[id]/disk`).

## Working on this codebase — one tree, any session

`/opt/nxeon` (this directory, branch `main`) is the single source of truth. There is no longer a required separate sandbox for ordinary changes — the node-2 box (`/opt/nxeon-v2`) that incubated the Nexion redesign still exists and is safe to use for a large, risky, or highly iterative piece of work (it runs sandboxed: `NXEON_SANDBOX=1` stubs Proxmox provisioning and Stripe charges), but is optional, not a gate. Any session — this one or another — can edit `main` directly and ship through the pipeline below.

1. Edit, then `npx tsc --noEmit` before building anything.
2. `npm run build` locally only to catch build errors before pushing — do not restart production services from an ad hoc build in this directory (see Commands below); this is validation, not deployment.
3. Commit (small, real commits — the GitHub post-commit hook auto-pushes `origin`).
4. `scripts/deploy-staging.sh <ref>` — builds, migrates, and restarts staging (`:8080`) from that ref. **Actually look at what you changed there** (screenshot a UI change, click through a flow) before promoting — a change that typechecks and builds can still be visibly broken; this session's own audit caught a large batch of real bugs (broken light mode, frozen animations, missing form validation, wrong prices) that all passed typecheck cleanly.
5. `scripts/promote-production.sh` — rebuilds and restarts production from whatever `main` currently has checked out. It refuses to run if staging isn't healthy first.

If two sessions are likely to be editing at once, coordinate the ordinary way: pull before starting, small commits, push often (the auto-push hook does this for you on commit).

