import { createHash } from "node:crypto";

/**
 * Minimal OVH API client (signed requests). OVH uses AK/AS/CK triple auth with a
 * SHA1 request signature. Endpoints differ per region.
 */
const ENDPOINTS: Record<string, string> = {
  "ovh-eu": "https://eu.api.ovh.com/1.0",
  "ovh-ca": "https://ca.api.ovh.com/1.0",
  "ovh-us": "https://api.us.ovhcloud.com/1.0",
};

export function ovhConfigured(): boolean {
  return !!(
    process.env.OVH_APPLICATION_KEY &&
    process.env.OVH_APPLICATION_SECRET &&
    process.env.OVH_CONSUMER_KEY
  );
}

function base(): string {
  return ENDPOINTS[process.env.OVH_ENDPOINT ?? "ovh-ca"] ?? ENDPOINTS["ovh-ca"];
}

/** OVH server time (used to avoid clock-skew signature failures). */
async function ovhTime(): Promise<number> {
  const res = await fetch(`${base()}/auth/time`, { signal: AbortSignal.timeout(15_000) });
  return Number(await res.text());
}

/** Error from a non-2xx OVH response. The message is unchanged; `status` lets callers tell a 404 from an outage. */
export class OvhHttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
    this.name = "OvhHttpError";
  }
}

export async function ovh(
  method: "GET" | "POST" | "PUT" | "DELETE",
  path: string,
  body?: unknown
): Promise<any> {
  if (!ovhConfigured()) throw new Error("OVH API is not configured");
  const AK = process.env.OVH_APPLICATION_KEY!;
  const AS = process.env.OVH_APPLICATION_SECRET!;
  const CK = process.env.OVH_CONSUMER_KEY!;
  const url = `${base()}${path}`;
  const bodyStr = body !== undefined ? JSON.stringify(body) : "";
  const ts = await ovhTime();
  const toSign = `${AS}+${CK}+${method}+${url}+${bodyStr}+${ts}`;
  const sig = "$1$" + createHash("sha1").update(toSign).digest("hex");

  const res = await fetch(url, {
    method,
    headers: {
      "X-Ovh-Application": AK,
      "X-Ovh-Consumer": CK,
      "X-Ovh-Timestamp": String(ts),
      "X-Ovh-Signature": sig,
      "Content-Type": "application/json",
    },
    body: bodyStr || undefined,
    signal: AbortSignal.timeout(30_000),
  });
  const text = await res.text();
  let json: any = null;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = text;
  }
  if (!res.ok) {
    const msg = json?.message ?? text ?? `HTTP ${res.status}`;
    throw new OvhHttpError(`OVH ${method} ${path} -> ${res.status}: ${msg}`, res.status);
  }
  return json;
}

// ---- Convenience wrappers for dedicated IPs / Virtual MACs / reverse DNS ----

export const ovhApi = {
  me: () => ovh("GET", "/me"),
  servers: () => ovh("GET", "/dedicated/server") as Promise<string[]>,
  server: (name: string) => ovh("GET", `/dedicated/server/${name}`),
  ips: () => ovh("GET", "/ip") as Promise<string[]>,
  ipInfo: (ip: string) => ovh("GET", `/ip/${encodeURIComponent(ip)}`),
  /** Virtual MACs registered on a dedicated server. */
  virtualMacs: (server: string) => ovh("GET", `/dedicated/server/${server}/virtualMac`),
  /** Create a Virtual MAC for an additional IP so it can be routed to a VM. */
  createVirtualMac: (server: string, ipAddress: string, name: string) =>
    ovh("POST", `/dedicated/server/${server}/virtualMac`, {
      ipAddress,
      type: "ovh",
      virtualMachineName: name,
    }),
  /** Set reverse DNS (PTR) for an IP. */
  setReverse: (ipBlock: string, ip: string, reverse: string) =>
    ovh("POST", `/ip/${encodeURIComponent(ipBlock)}/reverse`, { ipReverse: ip, reverse }),
};

/**
 * Pure: turn per-node OVH firewall readings into DesiredAlerts for the shared
 * fleet-alert machinery (lib/fleet-alert-plan.ts -> worker/fleet-alerts.ts).
 * No I/O. Used by worker/ovh-game-firewall-sweep.ts.
 *
 *   OVH-GAME-FW:<ip>  strict mode ON            CRITICAL when the IP carries traffic now
 *                                               (the node's own IP or an ASSIGNED pool IP),
 *                                               WARN for a FREE/unused pool IP (it will bite the next customer)
 *   OVH-NET-FW:<ip>   network firewall ENABLED  WARN (it can drop customer traffic; legit if the owner set it up)
 *
 * Only a firm reading raises or keeps an alert. An unreadable node (OVH outage,
 * 5xx, timeout) is left out of `readNodeIds`, so its open alerts are neither
 * refreshed nor resolved: absent evidence is not recovery.
 */
import type { DesiredAlert } from "./fleet-alert-plan";
import type { NodeFirewallEntry } from "./ovh-game-firewall";

export const OVH_GAME_FW_PREFIX = "OVH-GAME-FW:";
export const OVH_NET_FW_PREFIX = "OVH-NET-FW:";

export type NodeFirewallReading = { nodeId: string; nodeName: string; entries: readonly NodeFirewallEntry[] };

export function desiredOvhFirewallAlerts(readings: readonly NodeFirewallReading[]): { desired: DesiredAlert[]; readNodeIds: Set<string> } {
  const desired: DesiredAlert[] = [];
  const readNodeIds = new Set<string>();
  for (const n of readings) {
    if (n.entries.every((e) => e.report.ok)) readNodeIds.add(n.nodeId);
    for (const e of n.entries) {
      const r = e.report;
      if (!r.ok) continue;
      if (r.game.exists && r.game.firewallModeEnabled === true) {
        const carries = e.source === "node" || e.poolStatus === "ASSIGNED";
        desired.push({
          nodeId: n.nodeId,
          nodeName: n.nodeName,
          dimension: `${OVH_GAME_FW_PREFIX}${e.ip}`,
          severity: carries ? "CRITICAL" : "WARN",
          title: `OVH game firewall strict mode on ${e.ip}`,
          detail: `${n.nodeName} (${e.source === "node" ? "node public IP" : `pooled IP, ${e.poolStatus ?? "?"}`}). ${r.gameVerdict.summary}. ${r.gameVerdict.remediation ?? ""}`.trim(),
        });
      }
      if (r.network.exists && r.network.enabled === true) {
        desired.push({
          nodeId: n.nodeId,
          nodeName: n.nodeName,
          dimension: `${OVH_NET_FW_PREFIX}${e.ip}`,
          severity: "WARN",
          title: `OVH network firewall enabled on ${e.ip}`,
          detail: `${n.nodeName}. ${r.networkVerdict.summary}. ${r.networkVerdict.remediation ?? ""}`.trim(),
        });
      }
    }
  }
  return { desired, readNodeIds };
}
/**
 * Pure planning for debounced, auto-resolving fleet alerts (see worker/fleet-alerts.ts). No I/O.
 */

export const FLEET_ALERT_PREFIXES = ["IP-CLASH:", "LEFTOVER-VM:", "UNKNOWN-VMID:", "OFFSITE-BACKUP:", "OVH-GAME-FW:", "OVH-NET-FW:"] as const;
export const FLEET_ALERT_COOLDOWN_HOURS = Number(process.env.NXEON_FLEET_ALERT_COOLDOWN_HOURS ?? 24);

export type DesiredAlert = { nodeId: string; nodeName: string; dimension: string; severity: "WARN" | "CRITICAL"; title: string; detail: string };
export type OpenAlert = { id: string; nodeId: string; dimension: string; severity: string; lastNotifiedAt: Date | null };
export type AlertOp =
  | { op: "create"; desired: DesiredAlert; notify: { title: string; body: string } }
  | { op: "update"; id: string; desired: DesiredAlert; notifyNow: boolean; notify?: { title: string; body: string } }
  | { op: "resolve"; id: string; nodeName: string; dimension: string; notify: { title: string; body: string } };

export function isFleetDimension(d: string): boolean {
  return FLEET_ALERT_PREFIXES.some((p) => d.startsWith(p));
}

export function planFleetAlerts(opts: {
  desired: readonly DesiredAlert[];
  open: readonly OpenAlert[];
  /** Nodes whose inventory was read successfully this sweep (only these may resolve). */
  readNodeIds: ReadonlySet<string>;
  nodeNames: ReadonlyMap<string, string>;
  now: Date;
  cooldownMs?: number;
}): AlertOp[] {
  const cooldownMs = opts.cooldownMs ?? FLEET_ALERT_COOLDOWN_HOURS * 3_600_000;
  const key = (nodeId: string, dim: string) => `${nodeId}|${dim}`;
  const openBy = new Map(opts.open.filter((a) => isFleetDimension(a.dimension)).map((a) => [key(a.nodeId, a.dimension), a]));
  const out: AlertOp[] = [];
  const seen = new Set<string>();
  for (const d of opts.desired) {
    const k = key(d.nodeId, d.dimension);
    seen.add(k);
    const ex = openBy.get(k);
    if (!ex) {
      out.push({ op: "create", desired: d, notify: { title: d.title, body: d.detail } });
    } else if (ex.severity !== d.severity && d.severity === "CRITICAL") {
      out.push({ op: "update", id: ex.id, desired: d, notifyNow: true, notify: { title: d.title, body: d.detail } });
    } else {
      // Keep the worse stored severity on a de-escalation; refresh text silently.
      const due = !ex.lastNotifiedAt || opts.now.getTime() - ex.lastNotifiedAt.getTime() > cooldownMs;
      const keepSev = ex.severity === "CRITICAL" ? "CRITICAL" : d.severity;
      const dd = { ...d, severity: keepSev as "WARN" | "CRITICAL" };
      out.push({ op: "update", id: ex.id, desired: dd, notifyNow: due, ...(due ? { notify: { title: dd.title, body: dd.detail } } : {}) });
    }
  }
  for (const [k, a] of openBy) {
    if (seen.has(k) || !opts.readNodeIds.has(a.nodeId)) continue;
    const nodeName = opts.nodeNames.get(a.nodeId) ?? a.nodeId;
    out.push({
      op: "resolve", id: a.id, nodeName, dimension: a.dimension,
      notify: { title: `Fleet alert cleared: ${nodeName} — ${a.dimension}`, body: `${a.dimension} on ${nodeName} is no longer present. Alert resolved.` },
    });
  }
  return out;
}

/**
 * Debounced, auto-resolving admin alerts for the fleet sweeps (IP clashes,
 * running/IP-sharing leftover VMs, unknown VM ids). Reuses the NodeAlert table
 * and the in-app admin notification path the node-capacity sweep uses
 * (worker/monitor.ts notifyAdmins) — no new alert machinery.
 *
 * One OPEN NodeAlert per condition, keyed (nodeKind=PROXMOX, nodeId, dimension)
 * where dimension is `IP-CLASH:<ip>`, `LEFTOVER-VM:<vmid>` or `UNKNOWN-VMID:<vmid>`.
 *   - new condition            -> create + notify
 *   - WARN -> CRITICAL         -> update + notify (escalation only)
 *   - persists, same severity  -> refresh detail silently; re-notify once per cooldown
 *   - gone, node read OK       -> RESOLVED + "cleared" notify
 *   - node not read this sweep -> left untouched (absent evidence is not recovery)
 * Pure planning in `planFleetAlerts` (tested); `applyFleetAlerts` does the I/O.
 */
import { db } from "../lib/db";
import { FLEET_ALERT_PREFIXES, type AlertOp, type OpenAlert } from "../lib/fleet-alert-plan";
import { notifyAdmins } from "./monitor";

export async function applyFleetAlerts(ops: readonly AlertOp[], now = new Date()): Promise<void> {
  for (const o of ops) {
    try {
      if (o.op === "create") {
        await db.nodeAlert.create({
          data: { nodeKind: "PROXMOX", nodeId: o.desired.nodeId, nodeName: o.desired.nodeName, dimension: o.desired.dimension, severity: o.desired.severity, pct: 0, detail: o.desired.detail, status: "OPEN", lastNotifiedAt: now },
        });
        await notifyAdmins(o.notify.title, o.notify.body, "/admin/nodes");
      } else if (o.op === "update") {
        await db.nodeAlert.update({
          where: { id: o.id },
          data: { severity: o.desired.severity, detail: o.desired.detail, ...(o.notifyNow ? { lastNotifiedAt: now } : {}) },
        });
        if (o.notifyNow && o.notify) await notifyAdmins(o.notify.title, o.notify.body, "/admin/nodes");
      } else {
        await db.nodeAlert.update({ where: { id: o.id }, data: { status: "RESOLVED", resolvedAt: now } });
        await notifyAdmins(o.notify.title, o.notify.body, "/admin/nodes");
      }
    } catch (e) {
      console.error("[fleet-alerts] apply failed", o.op, (o as any).id ?? (o as any).desired?.dimension, e);
    }
  }
}

export async function openFleetAlerts(): Promise<OpenAlert[]> {
  const rows = await db.nodeAlert.findMany({
    where: { status: "OPEN", nodeKind: "PROXMOX", OR: FLEET_ALERT_PREFIXES.map((p) => ({ dimension: { startsWith: p } })) },
    select: { id: true, nodeId: true, dimension: true, severity: true, lastNotifiedAt: true },
  });
  return rows;
}

import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { db } from "./db";
import { ovh, ovhApi, ovhConfigured } from "./ovh";
import { hetznerApi, hetznerConfigured } from "./hetzner";
import { SANDBOX, sandboxIp, sandboxMac } from "./sandbox";
import { getSettingInt } from "./settings";
import { agentHasLiveDnatRule } from "./node-agent";
import type { NodeProvider } from "@prisma/client";

const execFileP = promisify(execFile);

/**
 * Is this address already the target of a live DNAT rule on ITS OWN node?
 * Some infrastructure (the shared-hosting node, VM 200) reaches its dedicated
 * IP entirely through a whole-IP DNAT rule to an internal address — it has no
 * OVH Virtual MAC at all, so the MAC-based check above cannot see it. A real
 * incident: this exact IP was one query away from being handed to a game
 * server because "no Virtual MAC bound" was mistaken for "free" — it was
 * actively carrying production hosting traffic via `iptables -t nat`. Treat
 * any address with a live DNAT target as claimed, unconditionally.
 *
 * Dispatches by node: the primary's own local iptables (unchanged), or the
 * owning node's agent for anyone else — this used to always check the LOCAL
 * host regardless of which node `address` actually belongs to, which for a
 * non-primary node's pool checks the wrong machine's kernel entirely and
 * could double-allocate an address that's actually already claimed there.
 */
async function hasLiveDnatRule(node: NodeRow, address: string): Promise<boolean> {
  if (!node.isPrimary) {
    try {
      return await agentHasLiveDnatRule(node, address);
    } catch {
      // Agent unreachable/not configured — same fail-open reasoning as the
      // local case below: a false "not claimed" is recoverable (the Virtual
      // MAC check and the existing DB row are the other guards), a sync that
      // silently no-ops for an entire node's pool forever is not.
      return false;
    }
  }
  try {
    const { stdout } = await execFileP("iptables", ["-t", "nat", "-S", "PREROUTING"]);
    return stdout.split("\n").some((line) => line.includes(`-d ${address}/32`) && line.includes("-j DNAT"));
  } catch {
    // iptables unreadable (permissions, not present, sandboxed test env) — fail
    // closed is wrong here (it would make every sync a no-op); fail to "not
    // claimed by this specific check" and rely on the Virtual MAC check plus
    // the existing DB row remaining authoritative for anything already tracked.
    return false;
  }
}

/**
 * What OVH actually bills per additional/failover IPv4 in the pool, in cents.
 * Single source of truth for both the IP-pool page's "OVH cost" stat and the
 * admin Accounting dashboard's auto-pulled infrastructure expense line — before
 * this it existed only as a copy of the same number hardcoded on the IP page.
 */
export const OVH_IP_UNIT_COST_CENTS = 239;

/** Hetzner's "additional IP" rate, confirmed live in the Robot panel 2026-09-15. */
export const HETZNER_IP_UNIT_COST_CENTS = 200;

/**
 * Fallback monthly price for a dedicated IPv4. Defaults to 0 — a dedicated IP is
 * INCLUDED on every plan (its cost is folded into plan pricing, as the marketing
 * pages state). The admin `dedicated_ip_price_cents` setting is the source of
 * truth; use `dedicatedIpMonthlyCents()` in billing paths, not this constant.
 */
export const DEDICATED_IP_PRICE_CENTS = Number(process.env.DEDICATED_IP_PRICE_CENTS ?? 0);

/**
 * The monthly dedicated-IP surcharge actually charged, from the admin setting
 * (`dedicated_ip_price_cents`, default 0 = included). Single source of truth for
 * every order/renewal/display path so they can never disagree.
 *
 * NORMALISED to a non-negative whole number of cents, exactly as
 * `extraDiskPerGbCents` (lib/disk-expand.ts) already does for the other
 * admin-priced add-on. `getSettingInt` is a raw `Number()` of whatever string sits
 * in the `Setting` row, so it happily returns 2.5 or -500. This value is multiplied
 * by the term length straight into `chargeCents` (lib/order.ts orderQuote) and into
 * `renewalCharge`, and from there into `debitWallet`, `unit_amount` and an Invoice
 * row — every one of which is integer cents. A fractional setting produced a
 * fractional charge that failed at Stripe or Prisma AFTER the customer had agreed
 * to it; a negative one silently discounted the plan.
 */
export async function dedicatedIpMonthlyCents(): Promise<number> {
  const v = await getSettingInt("dedicated_ip_price_cents", DEDICATED_IP_PRICE_CENTS);
  return Math.max(0, Math.round(v));
}
/** Keep this many spare IPs in the pool; auto-order/release aims to stay near it. */
export const DEDICATED_IP_BUFFER = Number(process.env.DEDICATED_IP_BUFFER ?? 2);

/** OVH failover gateway = the host's /24 gateway (…​.254). OVH-specific — every
 *  additional/failover IP on an OVH dedicated server shares this one convention. */
function ovhGatewayFor(nodePublicIp: string): string {
  const parts = nodePublicIp.split(".");
  return `${parts[0]}.${parts[1]}.${parts[2]}.254`;
}

/** Back-compat wrapper for any caller still expecting the old single-node signature. */
export function ovhGateway(): string {
  return ovhGatewayFor(process.env.PUBLIC_IP ?? "51.79.162.96");
}

type NodeRow = {
  id: string;
  name: string;
  provider: NodeProvider;
  publicIp: string;
  providerServerId: string | null;
  isPrimary: boolean;
  agentPort: number;
  agentTokenEnc: string | null;
};

const NODE_ROW_SELECT = {
  id: true,
  name: true,
  provider: true,
  publicIp: true,
  providerServerId: true,
  isPrimary: true,
  agentPort: true,
  agentTokenEnc: true,
} as const;

/** Resolve the Node a dedicated-IP operation should act against: the id passed
 *  in explicitly, else the primary node — same fallback shape as
 *  worker/index.ts's nodeFor(), so single-node callers need no changes at all. */
async function resolveNode(nodeId?: string): Promise<NodeRow | null> {
  if (nodeId) {
    return db.node.findUnique({ where: { id: nodeId }, select: NODE_ROW_SELECT });
  }
  return db.node.findFirst({ where: { isPrimary: true }, select: NODE_ROW_SELECT });
}

/** Is the right provider API even configured for this node? Dispatches by
 *  provider so a Hetzner-hosted server never silently falls through to
 *  checking whether OVH happens to be configured (the real bug this fixes —
 *  worker/index.ts used to gate purely on ovhConfigured(), with no node
 *  awareness at all). */
export async function dedicatedIpProviderConfigured(nodeId?: string): Promise<boolean> {
  const node = await resolveNode(nodeId);
  if (!node) return false;
  return node.provider === "HETZNER" ? hetznerConfigured() : ovhConfigured();
}

/**
 * Pull additional/failover IPv4 addresses routed to a node's server from its
 * provider and upsert them into the pool. The host's own primary IP is never
 * poolable. Defaults to the primary (OVH) node when no `nodeId` is given —
 * identical behavior to before this file supported more than one node.
 */
export async function syncDedicatedIpPool(nodeId?: string): Promise<{ imported: number; total: number }> {
  if (SANDBOX) return { imported: 0, total: 0 };
  const node = await resolveNode(nodeId);
  if (!node || !node.providerServerId) return { imported: 0, total: 0 };

  if (node.provider === "HETZNER") return syncHetznerPool(node);
  return syncOvhPool(node);
}

async function syncOvhPool(node: NodeRow): Promise<{ imported: number; total: number }> {
  if (!ovhConfigured()) return { imported: 0, total: 0 };
  const SERVER = node.providerServerId!;
  const primary = node.publicIp;
  const blocks: string[] = await ovhApi.ips();
  let imported = 0;
  for (const block of blocks) {
    if (block.includes(":")) continue; // IPv6 handled separately
    let info: any;
    try {
      info = await ovhApi.ipInfo(block);
    } catch {
      continue;
    }
    if (info?.routedTo?.serviceName !== SERVER) continue;
    if (info?.type !== "failover" && info?.type !== "additional") continue; // exclude the primary "dedicated" host IP
    // A /32 block is a single usable IP == the block minus the mask.
    const address = block.split("/")[0];
    if (address === primary) continue;
    const existing = await db.dedicatedIp.findUnique({ where: { address } });
    if (!existing) {
      // An IP that already has a Virtual MAC bound to it on OVH's side is already
      // in active use by SOME VM — possibly one this app never created a Server
      // row for (e.g. internal infrastructure provisioned directly via the OVH
      // API, like the cold-email relay). A genuinely free IP has no bound MAC
      // yet. Importing it as FREE anyway let a real customer server collide with
      // an unrelated VM's network identity — never assign an IP that's already
      // claimed at the network layer, regardless of whether our DB knows about it.
      if (await findVirtualMacForIp(SERVER, address)) continue;
      if (await hasLiveDnatRule(node, address)) continue;
      // Every IP this function imports is, by construction, a spare address
      // OVH says is routed to us and not yet claimed at the network layer — the
      // pool customer orders draw from. Internal-use IPs (the cold-email relay,
      // an owner-operated site, the shared-hosting node) are rare, hand-provisioned
      // one-offs marked INTERNAL by an admin after the fact; this sync has no way
      // to tell them apart from a genuinely free customer IP and must not try —
      // it always imports as CUSTOMER (the schema default, stated here for clarity).
      await db.dedicatedIp.create({ data: { address, ovhBlock: block, nodeId: node.id, status: "FREE", purpose: "CUSTOMER" } });
      imported++;
    }
  }
  const total = await db.dedicatedIp.count({ where: { nodeId: node.id } });
  return { imported, total };
}

/**
 * Hetzner side of the sync. Hetzner's `/ip` listing already returns exactly
 * the single additional IPs on the account (no failover/additional type
 * distinction to filter like OVH's `/ip` does) — every entry not equal to the
 * node's own main `publicIp` is poolable.
 */
async function syncHetznerPool(node: NodeRow): Promise<{ imported: number; total: number }> {
  if (!hetznerConfigured()) return { imported: 0, total: 0 };
  let imported = 0;
  // The Robot API wraps each entry as `{ ip: { ip: "1.2.3.4", server_ip: ..., ... } }`,
  // not a flat `{ ip: "1.2.3.4" }` — confirmed live 2026-09-15, the first time this
  // ever ran against a real account (Hetzner credentials had never been configured
  // before). The old flat-shape read left `address` holding the nested object, which
  // Prisma's `where: { address }` rejects outright — the sync could never have
  // succeeded even once.
  const ips: Array<{ ip: { ip: string; server_ip: string } }> = await hetznerApi.ips().catch(() => []);
  for (const entry of ips) {
    const address = entry.ip?.ip;
    if (!address || address === node.publicIp) continue;
    const existing = await db.dedicatedIp.findUnique({ where: { address } });
    if (existing) continue;
    if (await hasLiveDnatRule(node, address)) continue;
    await db.dedicatedIp.create({
      data: { address, ovhBlock: "", nodeId: node.id, status: "FREE", purpose: "CUSTOMER" },
    });
    imported++;
  }
  const total = await db.dedicatedIp.count({ where: { nodeId: node.id } });
  return { imported, total };
}

/** Count of IPs actually available to hand to a customer — same eligibility as
 * allocateDedicatedIp's claim query; excludes admin-marked INTERNAL rows. */
export async function freeCount(): Promise<number> {
  return db.dedicatedIp.count({ where: { status: "FREE", purpose: "CUSTOMER" } });
}

/**
 * The real, live monthly bill for the whole dedicated-IP pool, in cents —
 * every pooled IP (free or assigned) costs its PROVIDER's per-IP rate
 * regardless of whether a customer is using it. Consumed by the Accounting
 * dashboard as an automatic recurring INFRASTRUCTURE expense line so this
 * cost is never hand-typed and can never drift from what /admin/ips itself
 * shows. Priced per-provider (not a single flat OVH rate) since 2026-09-15,
 * the day the first real Hetzner IP was pooled at its own, cheaper rate.
 */
export async function dedicatedIpPoolMonthlyCostCents(): Promise<number> {
  const counts = await db.dedicatedIp.groupBy({
    by: ["nodeId"],
    _count: true,
  });
  if (counts.length === 0) return 0;
  const nodes = await db.node.findMany({
    where: { id: { in: counts.map((c) => c.nodeId).filter((id): id is string => !!id) } },
    select: { id: true, provider: true },
  });
  const providerById = new Map(nodes.map((n) => [n.id, n.provider]));
  return counts.reduce((sum, c) => {
    const provider = c.nodeId ? providerById.get(c.nodeId) : undefined;
    const rate = provider === "HETZNER" ? HETZNER_IP_UNIT_COST_CENTS : OVH_IP_UNIT_COST_CENTS;
    return sum + c._count * rate;
  }, 0);
}

/** Find the OVH Virtual MAC currently bound to an IP, if any. */
async function findVirtualMacForIp(server: string, address: string): Promise<string | null> {
  const macs: string[] = await ovh("GET", `/dedicated/server/${server}/virtualMac`).catch(() => []);
  for (const m of macs) {
    const ips: string[] = await ovh("GET", `/dedicated/server/${server}/virtualMac/${m}/virtualAddress`).catch(() => []);
    if (ips.includes(address)) return m;
  }
  return null;
}

/**
 * Claim a free IP for a server and set it up so the VM can use it — an OVH
 * Virtual MAC for an OVH-node IP, or nothing extra for a Hetzner-node IP
 * (Hetzner additional IPs route straight to the server's real MAC, no
 * separate MAC object to create). Returns the address + a MAC (OVH only,
 * empty string for Hetzner) + gateway, or null if none available.
 *
 * `nodeId` should be the server's OWN node — pass it explicitly from a
 * caller that already resolved it (e.g. worker/index.ts's `nodeFor(server)`);
 * omitted, this falls back to the primary node, identical to this file's
 * pre-multi-node behavior.
 */
export async function allocateDedicatedIp(
  serverId: string,
  vmid: number,
  nodeId?: string,
  /** Admin Ops (lib/admin-ops, worker/admin-ops.ts): claim exactly this FREE
   *  address instead of the oldest free one. Omitted = unchanged behaviour. */
  opts?: { preferAddress?: string },
): Promise<{ address: string; virtualMac: string; gateway: string } | null> {
  if (SANDBOX) {
    // Hand out a synthetic dedicated IP without any provider call or pool mutation.
    return { address: sandboxIp(vmid), virtualMac: sandboxMac(vmid), gateway: "198.51.100.254" };
  }
  // Idempotent per server: PROVISION can retry (up to MAX_ATTEMPTS). If this
  // server already holds a fully-allocated dedicated IP, return it instead of
  // claiming a second pool IP — re-claiming would leak an IP and P2002 on the
  // unique DedicatedIp.serverId. An OVH row also needs a bound Virtual MAC to
  // count as "done"; a Hetzner row is done once ASSIGNED (no MAC step).
  const mine = await db.dedicatedIp.findUnique({ where: { serverId }, include: { node: true } });
  if (mine && mine.status === "ASSIGNED" && (mine.node.provider === "HETZNER" || mine.virtualMac)) {
    return { address: mine.address, virtualMac: mine.virtualMac ?? "", gateway: await gatewayFor(mine.node, mine.address) };
  }

  const node = await resolveNode(nodeId);
  if (!node) return null;
  if (!(await dedicatedIpProviderConfigured(node.id))) return null;

  // Atomically claim a FREE ip belonging to THIS node's pool. Excluding
  // purpose: INTERNAL here is a second, independent guard (alongside the
  // sync-time checks above) against ever handing an admin-marked internal IP
  // to a customer server.
  const claim = await db.$transaction(async (tx) => {
    const ip = await tx.dedicatedIp.findFirst({
      where: { status: "FREE", purpose: "CUSTOMER", nodeId: node.id, ...(opts?.preferAddress ? { address: opts.preferAddress } : {}) },
      orderBy: { createdAt: "asc" },
    });
    if (!ip) return null;
    await tx.dedicatedIp.update({ where: { id: ip.id }, data: { status: "PENDING", serverId } });
    return ip;
  });
  if (!claim) return null;

  try {
    if (node.provider === "HETZNER") {
      // Hetzner DOES require a registered virtual MAC per single additional
      // IP (corrected 2026-09-29 — see this file's header comment for the
      // real incident: any other MAC on the guest triggers Hetzner's own
      // network-abuse filtering). Robot's endpoint is rate-limited to 10
      // PUT/DELETE calls per hour, so ALWAYS check for an existing MAC via
      // GET first and only PUT when nothing is assigned yet — this must
      // never "refresh" a MAC that's already registered.
      let hetznerMac = "";
      try {
        // GET 404s ("mac not found") when nothing is registered yet — that's
        // the ordinary first-allocation case, not a failure; only create then.
        try {
          const info = await hetznerApi.macInfo(claim.address);
          hetznerMac = info?.mac?.mac ?? "";
        } catch (e) {
          if (!/-> 404/.test(String((e as Error)?.message))) throw e;
        }
        if (!hetznerMac) {
          const created = await hetznerApi.createMac(claim.address);
          hetznerMac = created?.mac?.mac ?? "";
        }
      } catch (e) {
        console.error(`[dedicated-ip] Hetzner virtual MAC lookup/create failed for ${claim.address} — provisioning will fall back to no explicit MAC (Hetzner may filter this as abuse)`, e);
      }
      await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: hetznerMac || null } });
      return { address: claim.address, virtualMac: hetznerMac, gateway: await gatewayFor(node, claim.address) };
    }
    // OVH branch — unchanged mechanics, just keyed off this node's own service name.
    const SERVER = node.providerServerId!;
    let mac = await findVirtualMacForIp(SERVER, claim.address);
    if (!mac) {
      // Creation is asynchronous (returns a task) — kick it off then poll.
      await ovhApi.createVirtualMac(SERVER, claim.address, `nxeon-${vmid}`);
      for (let i = 0; i < 40 && !mac; i++) {
        await new Promise((r) => setTimeout(r, 3000));
        mac = await findVirtualMacForIp(SERVER, claim.address);
      }
    }
    if (!mac) throw new Error("Virtual MAC not bound after creation (OVH task still pending)");
    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: mac } });
    return { address: claim.address, virtualMac: mac, gateway: ovhGatewayFor(node.publicIp) };
  } catch (e) {
    // Roll the claim back to FREE on failure
    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "FREE", serverId: null, virtualMac: null } });
    throw e;
  }
}

/**
 * The gateway a VM should use for this IP. OVH: the well-known "/24 -> .254"
 * convention, same for every additional IP on that node. Hetzner: NOT a
 * fixed formula — Hetzner assigns a distinct gateway per single additional
 * IP (confirmed against Hetzner's own docs this session: additional IP
 * SUBNETS route via the server's main IP with no separate gateway, but
 * single additional IPs each come with their own gateway address) — read it
 * from Hetzner's own `/ip/{ip}` response rather than guessing a formula.
 * NOTE: the exact response field name below (`gateway`) hasn't been verified
 * against a real Hetzner additional IP yet (none exist in the pool at the
 * time this was written) — confirm it the first time this path actually
 * runs, before trusting it for a real customer's network config.
 */
async function gatewayFor(node: NodeRow, address: string): Promise<string> {
  if (node.provider === "OVH") return ovhGatewayFor(node.publicIp);
  try {
    const info = await hetznerApi.ipInfo(address);
    if (info?.ip?.gateway) return info.ip.gateway as string;
  } catch {
    /* fall through */
  }
  return node.publicIp; // best-effort fallback; see doc comment above
}

/** Release a server's dedicated IP back to the pool (deletes the OVH Virtual
 *  MAC for an OVH-node IP). A Hetzner-node IP's registered MAC is
 *  DELIBERATELY left in place — it's registered per-IP, not per-customer, so
 *  the next allocation of this same address just finds it via `macInfo` and
 *  reuses it (allocateDedicatedIp already checks before creating). Hetzner
 *  rate-limits PUT/DELETE on this endpoint to 10/hour; there is no benefit
 *  to spending that budget tearing a MAC down just to recreate the same one
 *  again shortly after. */
export async function releaseDedicatedIp(serverId: string): Promise<void> {
  if (SANDBOX) return;
  const ip = await db.dedicatedIp.findUnique({ where: { serverId }, include: { node: true } });
  if (!ip) return;
  if (ip.node.provider === "OVH" && ovhConfigured() && ip.virtualMac && ip.node.providerServerId) {
    const SERVER = ip.node.providerServerId;
    try {
      // Remove the IP from the vMAC, then delete the vMAC.
      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}/virtualAddress/${ip.address}`).catch(() => {});
      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}`).catch(() => {});
    } catch {
      /* best-effort */
    }
  }
  await db.dedicatedIp.update({
    where: { id: ip.id },
    data: { status: "FREE", serverId: null, virtualMac: null },
  });
  // `Server.ipAddress` is UNIQUE and separate from this pool table — every
  // caller used to have to remember to clear it themselves, and one (the
  // admin "release IP" action) didn't, which left a FREE pool row while a
  // live server still held that exact address in `Server.ipAddress`. The next
  // server to claim the pool row then failed provisioning with a P2002 on
  // every retry, deterministically, since the failed-provision cleanup just
  // re-freed the same already-stuck row. Clearing it here — for every caller,
  // guarded to only touch the row that still holds THIS address, since the
  // column also holds ordinary NAT IPs for other servers — closes that class
  // of bug for good instead of relying on each call site to remember.
  await db.server.updateMany({
    where: { id: serverId, ipAddress: ip.address },
    data: { ipAddress: null, ipv6: null },
  });
}

/** Set reverse DNS (PTR) for a dedicated IP — dispatches to the owning node's provider. */
export async function setDedicatedReverse(address: string, reverse: string): Promise<void> {
  const ip = await db.dedicatedIp.findUnique({ where: { address }, include: { node: true } });
  if (!ip) return;
  if (ip.node.provider === "HETZNER") {
    if (!hetznerConfigured()) return;
    await hetznerApi.setReverse(address, reverse);
  } else {
    if (!ovhConfigured()) return;
    await ovhApi.setReverse(`${address}/32`, address, reverse);
  }
  await db.dedicatedIp.updateMany({ where: { address }, data: { reverse } });
}

