/**
 * Pure input validation for the OVH admin controls (lib/ovh-admin/actions.ts).
 * No I/O. Every server action validates with these BEFORE it reads or writes
 * anything at OVH — the client form is a convenience, never the control.
 *
 * Enumerations are copied from OVH's own published API schema
 * (https://ca.api.ovh.com/1.0/ip.json, fetched 2026-10-06): a value outside
 * them is refused locally instead of being sent to OVH to be refused there.
 */

export type Result<T> = { ok: true; value: T } | { ok: false; error: string };
const ok = <T>(value: T): Result<T> => ({ ok: true, value });
const bad = <T = never>(error: string): Result<T> => ({ ok: false, error });

// ---------------------------------------------------------------------------
// IPv4 / CIDR
// ---------------------------------------------------------------------------

const OCTET = "(25[0-5]|2[0-4]\\d|1\\d\\d|[1-9]?\\d)";
const IPV4_RE = new RegExp(`^${OCTET}(\\.${OCTET}){3}$`);

export function isIpv4(s: unknown): s is string {
  return typeof s === "string" && IPV4_RE.test(s);
}

function ipToInt(ip: string): number {
  return ip.split(".").reduce((acc, o) => acc * 256 + Number(o), 0);
}

/**
 * A network-firewall rule source: a bare IPv4 (treated as /32) or a proper CIDR
 * block whose host bits are zero (`10.0.0.1/8` is refused — it is almost always
 * a typo for something narrower, and OVH would silently widen it). Empty /
 * "any" means "any source" and returns null.
 */
export function parseSourceCidr(raw: unknown): Result<string | null> {
  const s = typeof raw === "string" ? raw.trim() : "";
  if (s === "" || s.toLowerCase() === "any") return ok(null);
  const [ip, prefixStr, extra] = s.split("/");
  if (extra !== undefined) return bad("Source must be an IPv4 address or CIDR block, e.g. 203.0.113.0/24.");
  if (!isIpv4(ip)) return bad("Source must be an IPv4 address or CIDR block, e.g. 203.0.113.0/24.");
  if (prefixStr === undefined) return ok(`${ip}/32`);
  if (!/^\d{1,2}$/.test(prefixStr)) return bad("CIDR prefix must be a number from 0 to 32.");
  const prefix = Number(prefixStr);
  if (prefix < 0 || prefix > 32) return bad("CIDR prefix must be a number from 0 to 32.");
  if (prefix === 0) return ok(null); // 0.0.0.0/0 == any
  const mask = prefix === 32 ? 0xffffffff : (0xffffffff << (32 - prefix)) >>> 0;
  if (((ipToInt(ip) & ~mask) >>> 0) !== 0) {
    return bad(`${s} has host bits set; did you mean ${intToIp((ipToInt(ip) & mask) >>> 0)}/${prefix}?`);
  }
  return ok(`${ip}/${prefix}`);
}

function intToIp(n: number): string {
  return [24, 16, 8, 0].map((b) => (n >>> b) & 255).join(".");
}

// ---------------------------------------------------------------------------
// Ports
// ---------------------------------------------------------------------------

export function parsePort(raw: unknown): Result<number> {
  const s = typeof raw === "number" ? String(raw) : typeof raw === "string" ? raw.trim() : "";
  if (!/^\d{1,5}$/.test(s)) return bad("Port must be a whole number from 1 to 65535.");
  const n = Number(s);
  if (n < 1 || n > 65535) return bad("Port must be a whole number from 1 to 65535.");
  return ok(n);
}

/** "25565" or "27015-27030" (inclusive). */
export function parsePortRange(raw: unknown): Result<{ from: number; to: number }> {
  const s = typeof raw === "string" ? raw.trim().replace(/\s+/g, "") : typeof raw === "number" ? String(raw) : "";
  if (!s) return bad("Enter a port or a port range like 27015-27030.");
  const parts = s.split("-");
  if (parts.length > 2) return bad("A port range is two ports joined by a single dash, e.g. 27015-27030.");
  const a = parsePort(parts[0]);
  if (!a.ok) return a;
  if (parts.length === 1) return ok({ from: a.value, to: a.value });
  const b = parsePort(parts[1]);
  if (!b.ok) return b;
  if (b.value < a.value) return bad("The end of a port range must not be lower than its start.");
  return ok({ from: a.value, to: b.value });
}

// ---------------------------------------------------------------------------
// Game firewall (ip.GameMitigationRuleProtocolEnum)
// ---------------------------------------------------------------------------

export const GAME_PROTOCOLS = [
  "arkSurvivalAscended", "arkSurvivalEvolved", "arkSurvivalEvolvedV311.78+", "arma", "counterStrike2", "fiveM",
  "gtaMultiTheftAutoSanAndreas", "gtaSanAndreasMultiplayerMod", "hl2Source", "minecraftBedrockWithRacknetCookie",
  "minecraftJava", "minecraftPocketEdition", "minecraftQuery", "mumble", "other", "rust", "teamspeak2", "teamspeak3",
  "trackmaniaShootmania", "valheim",
] as const;
export type GameProtocol = (typeof GAME_PROTOCOLS)[number];

/**
 * `supported` = the live object's `supportedProtocols` (an IP's list can be
 * narrower than the global enum — the recorded objects list 14 of the 20).
 */
export function parseGameProtocol(raw: unknown, supported?: readonly string[] | null): Result<GameProtocol> {
  const s = typeof raw === "string" ? raw.trim() : "";
  if (!(GAME_PROTOCOLS as readonly string[]).includes(s)) return bad("Unknown game protocol.");
  if (supported && supported.length && !supported.includes(s)) {
    return bad(`OVH does not support protocol "${s}" on this IP (supported: ${supported.join(", ")}).`);
  }
  return ok(s as GameProtocol);
}

// ---------------------------------------------------------------------------
// Network firewall (ip.FirewallProtocolEnum / FirewallActionEnum / FirewallSequenceRangeEnum)
// ---------------------------------------------------------------------------

export const FW_PROTOCOLS = ["ah", "esp", "gre", "icmp", "ipv4", "tcp", "udp"] as const;
export type FwProtocol = (typeof FW_PROTOCOLS)[number];
export const FW_ACTIONS = ["permit", "deny"] as const;
export type FwAction = (typeof FW_ACTIONS)[number];
export const FW_MAX_SEQUENCE = 19;

export type NetworkRuleInput = {
  sequence: number;
  action: FwAction;
  protocol: FwProtocol;
  /** Only for tcp/udp. */
  destinationPort: { from: number; to: number } | null;
  source: string | null;
};

export function parseNetworkRule(raw: {
  sequence?: unknown;
  action?: unknown;
  protocol?: unknown;
  ports?: unknown;
  source?: unknown;
}): Result<NetworkRuleInput> {
  const seqS = typeof raw.sequence === "number" ? String(raw.sequence) : typeof raw.sequence === "string" ? raw.sequence.trim() : "";
  if (!/^\d{1,2}$/.test(seqS) || Number(seqS) > FW_MAX_SEQUENCE) return bad(`Sequence must be 0 to ${FW_MAX_SEQUENCE}.`);
  const action = typeof raw.action === "string" ? raw.action.trim() : "";
  if (!(FW_ACTIONS as readonly string[]).includes(action)) return bad("Action must be permit or deny.");
  const protocol = typeof raw.protocol === "string" ? raw.protocol.trim() : "";
  if (!(FW_PROTOCOLS as readonly string[]).includes(protocol)) return bad("Unknown protocol.");
  const portsRaw = typeof raw.ports === "string" ? raw.ports.trim() : raw.ports;
  let destinationPort: { from: number; to: number } | null = null;
  if (portsRaw !== undefined && portsRaw !== null && portsRaw !== "") {
    if (protocol !== "tcp" && protocol !== "udp") return bad("Ports only apply to tcp or udp rules.");
    const r = parsePortRange(portsRaw);
    if (!r.ok) return r;
    destinationPort = r.value;
  }
  const src = parseSourceCidr(raw.source);
  if (!src.ok) return src;
  return ok({ sequence: Number(seqS), action: action as FwAction, protocol: protocol as FwProtocol, destinationPort, source: src.value });
}

/** The exact POST body OVH's /ip/{ip}/firewall/{ip}/rule expects. */
export function networkRuleBody(r: NetworkRuleInput): Record<string, unknown> {
  const body: Record<string, unknown> = { sequence: r.sequence, action: r.action, protocol: r.protocol };
  if (r.destinationPort) {
    if (r.destinationPort.from === r.destinationPort.to) body.destinationPort = r.destinationPort.from;
    else body.destinationPortRange = { from: r.destinationPort.from, to: r.destinationPort.to };
  }
  if (r.source) body.source = r.source;
  return body;
}

// ---------------------------------------------------------------------------
// Reverse DNS
// ---------------------------------------------------------------------------

/**
 * A PTR target: a fully-qualified hostname (at least two labels, alphabetic
 * TLD), LDH labels of 1-63 chars, total <= 253. Lower-cased, returned WITH the
 * trailing dot OVH stores.
 */
export function parseReverseHostname(raw: unknown): Result<string> {
  let s = typeof raw === "string" ? raw.trim().toLowerCase() : "";
  if (s.endsWith(".")) s = s.slice(0, -1);
  if (!s) return bad("Enter a hostname, e.g. mail.example.com.");
  if (s.length > 253) return bad("Hostname is longer than 253 characters.");
  const labels = s.split(".");
  if (labels.length < 2) return bad("Use a fully-qualified hostname (e.g. host.example.com), not a single label.");
  for (const l of labels) {
    if (!/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(l)) {
      return bad(`"${l || "(empty)"}" is not a valid hostname label (letters, digits and inner hyphens, 1-63 chars).`);
    }
  }
  if (!/^[a-z]{2,63}$/.test(labels[labels.length - 1])) return bad("The last label (TLD) must be letters only.");
  return ok(`${s}.`);
}

// ---------------------------------------------------------------------------
// Typed confirmations + misc
// ---------------------------------------------------------------------------

/**
 * Exact, case-sensitive match after trimming outer whitespace. Never a
 * prefix/contains/case-insensitive match: the point is that the operator
 * typed the specific thing they are about to hit.
 */
export function typedConfirmationMatches(expected: string, typed: unknown): boolean {
  return typeof typed === "string" && expected.length > 0 && typed.trim() === expected;
}

export const ID_RE = /^[a-z0-9]{8,40}$/i;
export function isCuid(s: unknown): s is string {
  return typeof s === "string" && ID_RE.test(s);
}

/** OVH virtual MAC as OVH prints it: lower-case colon hex. */
export function normMac(s: unknown): string | null {
  if (typeof s !== "string") return null;
  const v = s.trim().toLowerCase().replace(/-/g, ":");
  return /^([0-9a-f]{2}:){5}[0-9a-f]{2}$/.test(v) ? v : null;
}

/** OVH's virtualMachineName: we keep it to [A-Za-z0-9-], max 40. */
export function vmacName(raw: string): string {
  return raw.replace(/[^a-zA-Z0-9-]/g, "").slice(0, 40) || "nxeon-vm";
}

export function cleanReason(raw: unknown, max = 300): string {
  return typeof raw === "string" ? raw.replace(/[\r\n\t]+/g, " ").trim().slice(0, max) : "";
}

