  destinationPort: { from: number; to: number } | null;
  source: string | null;
};

export function parseNetworkRule(raw: {
  sequence?: unknown;
  action?: unknown;
  protocol?: unknown;
  ports?: unknown;
  source?: unknown;
}): Result<NetworkRuleInput> {
  const seqS = typeof raw.sequence === "number" ? String(raw.sequence) : typeof raw.sequence === "string" ? raw.sequence.trim() : "";
  if (!/^\d{1,2}$/.test(seqS) || Number(seqS) > FW_MAX_SEQUENCE) return bad(`Sequence must be 0 to ${FW_MAX_SEQUENCE}.`);
  const action = typeof raw.action === "string" ? raw.action.trim() : "";
  if (!(FW_ACTIONS as readonly string[]).includes(action)) return bad("Action must be permit or deny.");
  const protocol = typeof raw.protocol === "string" ? raw.protocol.trim() : "";
  if (!(FW_PROTOCOLS as readonly string[]).includes(protocol)) return bad("Unknown protocol.");
  const portsRaw = typeof raw.ports === "string" ? raw.ports.trim() : raw.ports;
  let destinationPort: { from: number; to: number } | null = null;
  if (portsRaw !== undefined && portsRaw !== null && portsRaw !== "") {
    if (protocol !== "tcp" && protocol !== "udp") return bad("Ports only apply to tcp or udp rules.");
    const r = parsePortRange(portsRaw);
    if (!r.ok) return r;
    destinationPort = r.value;
  }
  const src = parseSourceCidr(raw.source);
  if (!src.ok) return src;
  return ok({ sequence: Number(seqS), action: action as FwAction, protocol: protocol as FwProtocol, destinationPort, source: src.value });
}

/** The exact POST body OVH's /ip/{ip}/firewall/{ip}/rule expects. */
export function networkRuleBody(r: NetworkRuleInput): Record<string, unknown> {
  const body: Record<string, unknown> = { sequence: r.sequence, action: r.action, protocol: r.protocol };
  if (r.destinationPort) {
    if (r.destinationPort.from === r.destinationPort.to) body.destinationPort = r.destinationPort.from;
    else body.destinationPortRange = { from: r.destinationPort.from, to: r.destinationPort.to };
  }
  if (r.source) body.source = r.source;
  return body;
}

// ---------------------------------------------------------------------------
// Reverse DNS
// ---------------------------------------------------------------------------

/**
 * A PTR target: a fully-qualified hostname (at least two labels, alphabetic
 * TLD), LDH labels of 1-63 chars, total <= 253. Lower-cased, returned WITH the
 * trailing dot OVH stores.
 */
export function parseReverseHostname(raw: unknown): Result<string> {
  let s = typeof raw === "string" ? raw.trim().toLowerCase() : "";
  if (s.endsWith(".")) s = s.slice(0, -1);
  if (!s) return bad("Enter a hostname, e.g. mail.example.com.");
  if (s.length > 253) return bad("Hostname is longer than 253 characters.");
  const labels = s.split(".");
  if (labels.length < 2) return bad("Use a fully-qualified hostname (e.g. host.example.com), not a single label.");
  for (const l of labels) {
    if (!/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(l)) {
      return bad(`"${l || "(empty)"}" is not a valid hostname label (letters, digits and inner hyphens, 1-63 chars).`);
    }
  }
  if (!/^[a-z]{2,63}$/.test(labels[labels.length - 1])) return bad("The last label (TLD) must be letters only.");
  return ok(`${s}.`);
}

// ---------------------------------------------------------------------------
// Typed confirmations + misc
// ---------------------------------------------------------------------------

/**
 * Exact, case-sensitive match after trimming outer whitespace. Never a
 * prefix/contains/case-insensitive match: the point is that the operator
 * typed the specific thing they are about to hit.
 */
export function typedConfirmationMatches(expected: string, typed: unknown): boolean {
  return typeof typed === "string" && expected.length > 0 && typed.trim() === expected;
}

export const ID_RE = /^[a-z0-9]{8,40}$/i;
export function isCuid(s: unknown): s is string {
  return typeof s === "string" && ID_RE.test(s);
}

/** OVH virtual MAC as OVH prints it: lower-case colon hex. */
export function normMac(s: unknown): string | null {
  if (typeof s !== "string") return null;
  const v = s.trim().toLowerCase().replace(/-/g, ":");
  return /^([0-9a-f]{2}:){5}[0-9a-f]{2}$/.test(v) ? v : null;
}

/** OVH's virtualMachineName: we keep it to [A-Za-z0-9-], max 40. */
export function vmacName(raw: string): string {
  return raw.replace(/[^a-zA-Z0-9-]/g, "").slice(0, 40) || "nxeon-vm";
}

export function cleanReason(raw: unknown, max = 300): string {
  return typeof raw === "string" ? raw.replace(/[\r\n\t]+/g, " ").trim().slice(0, max) : "";
}

