/**
 * OVH API access rules ("rights") for the admin OVH controls.
 *
 * An OVH consumer key carries a list of `{method, path}` access rules where `*`
 * matches any run of characters (including `/`). The platform reads its own
 * key's rules with `GET /auth/currentCredential` and every control checks the
 * exact right it needs BEFORE it calls OVH, so an unauthorised control shows
 * "needs OVH API right PUT /ip/*\/game/*" instead of failing with a raw 403.
 * A 403 that still comes back (rules changed under us) is mapped to the same
 * message by `rightsErrorFor`.
 *
 * `FEATURE_RIGHTS` is the single source of truth for both the UI degradation
 * and /root/agent-notes/ovh-admin/RIGHTS.md (the list the owner grants on a new,
 * narrowly-scoped consumer key). Keep them in sync: test/ovh-admin.test.ts
 * checks every write path the actions module can send is covered here.
 */

export type HttpMethod = "GET" | "POST" | "PUT" | "DELETE";
export type AccessRule = { method: HttpMethod; path: string };

export type FeatureKey =
  | "read"
  | "gameFirewall"
  | "networkFirewall"
  | "reverseDns"
  | "virtualMac"
  | "mitigation"
  | "unblock"
  | "reboot"
  | "netboot"
  | "platformExisting";

/** What each feature needs. Read rights are shared by every panel. */
export const FEATURE_RIGHTS: Record<FeatureKey, { label: string; rules: AccessRule[] }> = {
  read: {
    label: "All OVH panels (read-only)",
    rules: [
      { method: "GET", path: "/auth/currentCredential" },
      { method: "GET", path: "/ip" },
      { method: "GET", path: "/ip/*" },
      { method: "GET", path: "/dedicated/server" },
      { method: "GET", path: "/dedicated/server/*" },
    ],
  },
  gameFirewall: {
    label: "1. Game firewall: strict mode + allow rules",
    rules: [
      { method: "PUT", path: "/ip/*/game/*" },
      { method: "POST", path: "/ip/*/game/*/rule" },
      { method: "DELETE", path: "/ip/*/game/*/rule/*" },
    ],
  },
  networkFirewall: {
    label: "2. Network firewall: add IP, enable/disable, rules",
    rules: [
      { method: "POST", path: "/ip/*/firewall" },
      { method: "PUT", path: "/ip/*/firewall/*" },
      { method: "POST", path: "/ip/*/firewall/*/rule" },
      { method: "DELETE", path: "/ip/*/firewall/*/rule/*" },
    ],
  },
  reverseDns: {
    label: "3. Reverse DNS",
    rules: [{ method: "POST", path: "/ip/*/reverse" }],
  },
  virtualMac: {
    label: "4. Virtual MAC repair",
    rules: [
      { method: "POST", path: "/dedicated/server/*/virtualMac" },
      { method: "POST", path: "/dedicated/server/*/virtualMac/*/virtualAddress" },
      { method: "DELETE", path: "/dedicated/server/*/virtualMac/*/virtualAddress/*" },
    ],
  },
  mitigation: {
    label: "5. Permanent DDoS mitigation on/off",
    rules: [
      { method: "POST", path: "/ip/*/mitigation" },
      { method: "DELETE", path: "/ip/*/mitigation/*" },
    ],
  },
  unblock: {
    label: "6. Unblock an antihack / spam / ARP-blocked IP",
    rules: [
      { method: "POST", path: "/ip/*/antihack/*/unblock" },
      { method: "POST", path: "/ip/*/spam/*/unblock" },
      { method: "POST", path: "/ip/*/arp/*/unblock" },
    ],
  },
  reboot: {
    label: "9. Hard reboot a node",
    rules: [{ method: "POST", path: "/dedicated/server/*/reboot" }],
  },
  netboot: {
    label: "9. Rescue mode (netboot to rescue / back to disk)",
    rules: [{ method: "PUT", path: "/dedicated/server/*" }],
  },
  /**
   * NOT used by the admin controls, but already used by the platform's worker
   * (provisioning, release, VM move, mail PTR). A replacement key without these
   * would break provisioning, so RIGHTS.md lists them too.
   */
  platformExisting: {
    label: "Existing platform paths (provisioning / IP release / VM move)",
    rules: [
      { method: "POST", path: "/dedicated/server/*/virtualMac" },
      { method: "DELETE", path: "/dedicated/server/*/virtualMac/*/virtualAddress/*" },
      { method: "DELETE", path: "/dedicated/server/*/virtualMac/*" },
      { method: "POST", path: "/ip/*/move" },
      { method: "POST", path: "/ip/*/reverse" },
    ],
  },
};

/** OVH-style glob: `*` matches anything, including `/`. Everything else literal. */
export function globToRegExp(glob: string): RegExp {
  const esc = glob.replace(/[.+?^${}()|[\]\\]/g, "\\$&").replace(/\*/g, ".*");
  return new RegExp(`^${esc}$`);
}

/**
 * Does `rules` allow `method path`? `path` is the URL path we send, with or
 * without percent-encoding (an IP block `1.2.3.4/32` is sent as `1.2.3.4%2F32`;
 * both forms are tested so a rule written either way matches). Query strings
 * are ignored.
 */
export function rulesAllow(rules: readonly AccessRule[] | null | undefined, method: HttpMethod, path: string): boolean {
  if (!rules) return false;
  const p = path.split("?")[0];
  let decoded = p;
  try {
    decoded = decodeURIComponent(p);
  } catch {
    /* keep raw */
  }
  return rules.some((r) => r.method === method && (globToRegExp(r.path).test(p) || globToRegExp(r.path).test(decoded)));
}

/** The concrete template rule a request needs, for "needs OVH API right X" messages. */
export function requiredRuleFor(method: HttpMethod, path: string): AccessRule | null {
  for (const f of Object.values(FEATURE_RIGHTS)) {
    for (const r of f.rules) if (rulesAllow([r], method, path) && r.method === method) return r;
  }
  return null;
}

export function needsRightMessage(method: HttpMethod, path: string): string {
  const r = requiredRuleFor(method, path);
  return `Needs OVH API right ${r ? `${r.method} ${r.path}` : `${method} ${path.split("?")[0]}`} on the platform's consumer key (see RIGHTS.md).`;
}

export type FeatureRights = Record<FeatureKey, { allowed: boolean; missing: AccessRule[] }>;

/** Per-feature authorisation summary from the key's rules. `rules=null` = could not read them. */
export function featureRights(rules: readonly AccessRule[] | null): FeatureRights {
  const out = {} as FeatureRights;
  for (const [k, f] of Object.entries(FEATURE_RIGHTS) as [FeatureKey, (typeof FEATURE_RIGHTS)[FeatureKey]][]) {
    // A rule template is "covered" when the key allows a concrete example of it.
    const missing = f.rules.filter((r) => !rulesAllow(rules, r.method, exampleFor(r.path)));
    out[k] = { allowed: missing.length === 0, missing };
  }
  return out;
}

/** Turn a template path into a concrete example path for coverage testing. */
export function exampleFor(template: string): string {
  return template.replace(/\*/g, "x1");
}

/** Wildcard-everything keys are flagged: the web process can then do anything on the OVH account. */
export function isOverBroad(rules: readonly AccessRule[] | null): boolean {
  if (!rules) return false;
  return (["POST", "PUT", "DELETE"] as HttpMethod[]).some((m) => rules.some((r) => r.method === m && (r.path === "/*" || r.path === "*")));
}

export function parseCredentialRules(body: unknown): AccessRule[] | null {
  const rules = (body as any)?.rules;
  if (!Array.isArray(rules)) return null;
  return rules
    .filter((r) => r && typeof r.path === "string" && ["GET", "POST", "PUT", "DELETE"].includes(r.method))
    .map((r) => ({ method: r.method as HttpMethod, path: r.path as string }));
}

/** A 403 from OVH, turned into the "needs right" message; anything else passes through. */
export function rightsErrorFor(e: unknown, method: HttpMethod, path: string): string {
  const status = (e as any)?.status;
  const msg = String((e as any)?.message ?? e);
  if (status === 403 || /-> 403:/.test(msg)) return needsRightMessage(method, path);
  return msg.slice(0, 300);
}

