/**
 * Pure parsers + verdicts for the OVH admin panels. No I/O; unit-tested with
 * sanitised recordings in test/fixtures/ovh-admin.json.
 *
 * Shapes were learned READ-ONLY from the live API on 2026-10-06 and from OVH's
 * published schema (https://ca.api.ovh.com/1.0/ip.json + dedicated/server.json).
 * Where nothing was live to record (no IP was blocked or under mitigation at
 * the time) the parser follows the schema model named in its comment.
 */

const str = (v: unknown): string | null => (typeof v === "string" && v !== "" ? v : null);
const num = (v: unknown): number | null => (typeof v === "number" && Number.isFinite(v) ? v : null);
const bool = (v: unknown): boolean | null => (typeof v === "boolean" ? v : null);

// ---------------------------------------------------------------------------
// 7. Per-IP facts (GET /ip/{block}, model ip.Ip)
// ---------------------------------------------------------------------------

export type IpFacts = {
  block: string;
  type: string | null; // dedicated | failover | additional | ...
  routedTo: string | null;
  campus: string | null;
  regions: string[];
  country: string | null;
  description: string | null;
  isAdditionalIp: boolean | null;
  canBeTerminated: boolean | null;
  rir: string | null;
};

export function parseIpFacts(body: any): IpFacts | null {
  if (!body || typeof body !== "object" || typeof body.ip !== "string") return null;
  return {
    block: body.ip,
    type: str(body.type),
    routedTo: str(body.routedTo?.serviceName),
    campus: str(body.campus),
    regions: Array.isArray(body.regions) ? body.regions.filter((r: unknown) => typeof r === "string") : [],
    country: str(body.country),
    description: str(body.description),
    isAdditionalIp: bool(body.isAdditionalIp),
    canBeTerminated: bool(body.canBeTerminated),
    rir: str(body.rir),
  };
}

/** Node.region (our datacenter code) -> the OVH campus + region codename an IP must carry to be usable there. */
export const OVH_REGION_ZONE: Record<string, { campus: string; region: string }> = {
  sgp1: { campus: "SGP", region: "ap-southeast-sgp" },
  bhs1: { campus: "BHS", region: "ca-east-bhs" },
  gra1: { campus: "GRA", region: "eu-west-gra" },
  rbx1: { campus: "RBX", region: "eu-west-rbx" },
  waw1: { campus: "WAW", region: "eu-central-waw" },
};

export type Verdict = { level: "PASS" | "WARN" | "FAIL"; summary: string };

/**
 * Wrong-zone check (2026-08-26 lesson: an ARIN failover IP silently delivered
 * in BHS was unusable on the SGP box and OVH refuses cross-zone moves). Also
 * flags an IP routed to a different OVH service than the node it is pooled on.
 */
export function zoneVerdict(node: { name: string; region: string; providerServerId: string | null }, f: IpFacts): Verdict {
  const want = OVH_REGION_ZONE[node.region];
  const problems: string[] = [];
  if (want) {
    const campusOk = f.campus ? f.campus.toUpperCase() === want.campus : null;
    const regionOk = f.regions.length ? f.regions.includes(want.region) : null;
    if (campusOk === false || regionOk === false) {
      problems.push(
        `IP is in ${f.campus ?? "?"} (${f.regions.join(", ") || "no region"}) but ${node.name} is ${node.region} (${want.campus} / ${want.region}) - ` +
          `it cannot be routed to this node; OVH refuses cross-zone moves, so it needs swapping via OVH support`,
      );
    }
    if (campusOk === null && regionOk === null) problems.push(`OVH returned no campus/region for this IP`);
  } else {
    problems.push(`no known OVH zone for node region "${node.region}"`);
  }
  if (node.providerServerId && f.routedTo && f.routedTo !== node.providerServerId) {
    problems.push(`OVH routes it to ${f.routedTo}, not this node's server ${node.providerServerId}`);
  }
  if (problems.length === 0) return { level: "PASS", summary: `zone ${f.campus} matches ${node.name} (${node.region})` };
  const fail = problems.some((p) => p.includes("cannot be routed") || p.includes("OVH routes it to"));
  return { level: fail ? "FAIL" : "WARN", summary: problems.join("; ") };
}

// ---------------------------------------------------------------------------
// 5. Mitigation (GET /ip/{block}/mitigation + /{ip}, model ip.MitigationIp)
// ---------------------------------------------------------------------------

export type Mitigation = {
  /** False = no mitigation object: OVH's always-on automatic detection only, permanent mitigation OFF. */
  exists: boolean;
  permanent: boolean | null;
  /** true = OVH put the IP into mitigation itself, i.e. an attack was detected and is being scrubbed now. */
  auto: boolean | null;
  state: string | null; // creationPending | ok | removalPending
};

export function parseMitigation(ip: string, list: unknown, detail: any | null): Mitigation {
  const listed = Array.isArray(list) && list.includes(ip);
  if (!listed || !detail || typeof detail !== "object") return { exists: false, permanent: false, auto: false, state: null };
  return { exists: true, permanent: bool(detail.permanent), auto: bool(detail.auto), state: str(detail.state) };
}

export function mitigationSummary(m: Mitigation): Verdict {
  if (!m.exists) return { level: "PASS", summary: "Automatic mitigation only (permanent mitigation off; no attack being scrubbed now)" };
  if (m.auto) return { level: "WARN", summary: `UNDER ATTACK: OVH auto-mitigation is active (state ${m.state ?? "?"})` };
  if (m.permanent) return { level: "PASS", summary: `Permanent mitigation ON (state ${m.state ?? "?"})` };
  return { level: "WARN", summary: `Mitigation object present (state ${m.state ?? "?"})` };
}

// ---------------------------------------------------------------------------
// 6. Blocks (antihack / spam / arp)
//   ip.BlockedIp    {blockedSince, ipBlocked, logs, state: blocked|unblocking, time}
//   ip.SpamIp       {date, ipSpamming, state: blockedForSpam|unblocked|unblocking, time}
//   ip.ArpBlockedIp {blockedSince, ipBlocked, logs, state: blocked|unblocking, time}
// ---------------------------------------------------------------------------

export type BlockKind = "antihack" | "spam" | "arp";
export const BLOCK_KINDS: BlockKind[] = ["antihack", "spam", "arp"];

export type IpBlock = {
  kind: BlockKind;
  ip: string;
  state: string | null;
  /** true while traffic is actually blocked (blocked / blockedForSpam). */
  blocked: boolean;
  since: string | null;
  /** OVH's `time`: seconds the block lasts / has left before an unblock is allowed. */
  timeSec: number | null;
  logs: string | null;
};

export function parseBlock(kind: BlockKind, body: any): IpBlock | null {
  if (!body || typeof body !== "object") return null;
  const ip = str(kind === "spam" ? body.ipSpamming : body.ipBlocked);
  if (!ip) return null;
  const state = str(body.state);
  return {
    kind,
    ip,
    state,
    blocked: state === "blocked" || state === "blockedForSpam",
    since: str(kind === "spam" ? body.date : body.blockedSince),
    timeSec: num(body.time),
    logs: typeof body.logs === "string" ? body.logs.slice(0, 2000) : null,
  };
}

export const BLOCK_REASON: Record<BlockKind, string> = {
  antihack: "OVH anti-hack: the IP was seen ATTACKING other hosts (scanning/brute force/DDoS outbound). Usually a compromised VM.",
  spam: "OVH anti-spam: the IP sent spam (outbound SMTP abuse). Usually a compromised VM or an open relay.",
  arp: "OVH ARP block: the IP was announced from the wrong MAC (ARP spoofing / bad vMAC config).",
};

// ---------------------------------------------------------------------------
// 8. Node facts: service info, traffic, tasks, interventions, boots
// ---------------------------------------------------------------------------

export type ServiceFacts = {
  expiration: string | null; // YYYY-MM-DD
  creation: string | null;
  status: string | null;
  autoRenew: boolean | null;
  deleteAtExpiration: boolean | null;
  manualPayment: boolean | null;
  renewPeriodMonths: number | null;
  engagedUpTo: string | null;
  renewalType: string | null;
};

export function parseServiceInfos(body: any): ServiceFacts | null {
  if (!body || typeof body !== "object") return null;
  return {
    expiration: str(body.expiration),
    creation: str(body.creation),
    status: str(body.status),
    autoRenew: bool(body.renew?.automatic),
    deleteAtExpiration: bool(body.renew?.deleteAtExpiration),
    manualPayment: bool(body.renew?.manualPayment),
    renewPeriodMonths: num(body.renew?.period),
    engagedUpTo: str(body.engagedUpTo),
    renewalType: str(body.renewalType),
  };
}

/** Whole days from `now` until a YYYY-MM-DD date (UTC). Negative = past. */
export function daysUntil(date: string, now: Date): number | null {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(date);
  if (!m) return null;
  const t = Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  const today = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
  return Math.round((t - today) / 86_400_000);
}

export type RenewalVerdict = Verdict & { daysLeft: number | null; alert: boolean };

/**
 * Raise an alert when auto-renew is OFF (or the service will be deleted at
 * expiration) and expiration is within `alertDays`. Auto-renew ON never alerts
 * (OVH charges the card on file) — but a past-due date always does.
 */
export function renewalVerdict(s: ServiceFacts, now: Date, alertDays: number): RenewalVerdict {
  const daysLeft = s.expiration ? daysUntil(s.expiration, now) : null;
  const risky = s.autoRenew === false || s.deleteAtExpiration === true;
  if (daysLeft === null) return { level: "WARN", summary: "OVH returned no expiration date", daysLeft, alert: false };
  if (daysLeft < 0) return { level: "FAIL", summary: `service expired ${-daysLeft} day(s) ago (${s.expiration})`, daysLeft, alert: true };
  if (risky && daysLeft <= alertDays) {
    return {
      level: daysLeft <= 3 ? "FAIL" : "WARN",
      summary: `expires ${s.expiration} (in ${daysLeft} day(s)) and ${s.deleteAtExpiration ? "is set to DELETE at expiration" : "auto-renew is OFF"}`,
      daysLeft,
      alert: true,
    };
  }
  return {
    level: risky ? "WARN" : "PASS",
    summary: `renews ${s.expiration} (in ${daysLeft} day(s)); auto-renew ${s.autoRenew ? "on" : s.autoRenew === false ? "OFF" : "unknown"}`,
    daysLeft,
    alert: false,
  };
}

export type TrafficFacts = {
  /** No quota at all (unmetered offer, e.g. the recorded BHS node). */
  unmetered: boolean;
  inUsed: number | null;
  inQuota: number | null;
  outUsed: number | null;
  outQuota: number | null;
  resetDate: string | null;
  throttled: boolean | null;
  bandwidthMbps: { internetToOvh: number | null; ovhToInternet: number | null; type: string | null };
  connectionMbps: number | null;
  vmacQuota: number | null;
};

const bytes = (q: any): number | null => {
  const v = num(q?.value);
  if (v === null) return null;
  const unit = String(q?.unit ?? "B");
  const mult: Record<string, number> = { B: 1, KB: 1e3, MB: 1e6, GB: 1e9, TB: 1e12, KiB: 1024, MiB: 1024 ** 2, GiB: 1024 ** 3, TiB: 1024 ** 4 };
  return v * (mult[unit] ?? 1);
};

export function parseNetworkSpec(body: any): TrafficFacts | null {
  if (!body || typeof body !== "object") return null;
  const t = body.traffic ?? {};
  const inQuota = bytes(t.inputQuotaSize);
  const outQuota = bytes(t.outputQuotaSize);
  return {
    unmetered: inQuota === null && outQuota === null,
    inUsed: bytes(t.inputQuotaUsed),
    inQuota,
    outUsed: bytes(t.outputQuotaUsed),
    outQuota,
    resetDate: str(t.resetQuotaDate),
    throttled: bool(t.isThrottled),
    bandwidthMbps: {
      internetToOvh: num(body.bandwidth?.InternetToOvh?.value),
      ovhToInternet: num(body.bandwidth?.OvhToInternet?.value),
      type: str(body.bandwidth?.type),
    },
    connectionMbps: num(body.connection?.value),
    vmacQuota: num(body.vmac?.quota),
  };
}

export function trafficVerdict(t: TrafficFacts): Verdict {
  if (t.throttled) return { level: "FAIL", summary: "OVH is THROTTLING this server (traffic quota exceeded)" };
  if (t.unmetered) return { level: "PASS", summary: "no traffic quota (unmetered)" };
  const ratios = [t.inQuota && t.inUsed !== null ? t.inUsed / t.inQuota : 0, t.outQuota && t.outUsed !== null ? t.outUsed / t.outQuota : 0];
  const worst = Math.max(...ratios);
  const pct = Math.round(worst * 100);
  if (worst >= 0.9) return { level: "FAIL", summary: `${pct}% of the monthly traffic quota used (resets ${t.resetDate ?? "?"})` };
  if (worst >= 0.75) return { level: "WARN", summary: `${pct}% of the monthly traffic quota used (resets ${t.resetDate ?? "?"})` };
  return { level: "PASS", summary: `${pct}% of the monthly traffic quota used (resets ${t.resetDate ?? "?"})` };
}

export type OvhTask = { id: number; fn: string | null; status: string | null; comment: string | null; start: string | null; done: string | null; lastUpdate: string | null };

export function parseTask(body: any): OvhTask | null {
  if (!body || typeof body !== "object" || num(body.taskId) === null) return null;
  return {
    id: body.taskId,
    fn: str(body.function),
    status: str(body.status),
    comment: str(body.comment),
    start: str(body.startDate),
    done: str(body.doneDate),
    lastUpdate: str(body.lastUpdate),
  };
}

/** A task still in flight (dedicated.TaskStatusEnum minus terminal states). */
export function taskInFlight(t: OvhTask): boolean {
  return t.status === "init" || t.status === "todo" || t.status === "doing";
}

export type Intervention = { id: number; date: string | null; type: string | null };
export function parseIntervention(body: any): Intervention | null {
  if (!body || typeof body !== "object" || num(body.interventionId) === null) return null;
  return { id: body.interventionId, date: str(body.date), type: str(body.type) };
}

export type BootOption = { id: number; type: string | null; kernel: string | null; description: string | null };
export function parseBoot(body: any): BootOption | null {
  if (!body || typeof body !== "object" || num(body.bootId) === null) return null;
  return { id: body.bootId, type: str(body.bootType), kernel: str(body.kernel), description: str(body.description) };
}

export type ServerFacts = {
  name: string | null;
  state: string | null;
  powerState: string | null;
  bootId: number | null;
  datacenter: string | null;
  region: string | null;
  commercialRange: string | null;
  monitoring: boolean | null;
  noIntervention: boolean | null;
  supportLevel: string | null;
  ip: string | null;
};

export function parseServer(body: any): ServerFacts | null {
  if (!body || typeof body !== "object") return null;
  return {
    name: str(body.name),
    state: str(body.state),
    powerState: str(body.powerState),
    bootId: num(body.bootId),
    datacenter: str(body.datacenter),
    region: str(body.region),
    commercialRange: str(body.commercialRange),
    monitoring: bool(body.monitoring),
    noIntervention: bool(body.noIntervention),
    supportLevel: str(body.supportLevel),
    ip: str(body.ip),
  };
}

/** Which boot is the server set to, in words. */
export function bootMode(server: ServerFacts | null, boots: readonly BootOption[]): "disk" | "rescue" | "other" | "unknown" {
  if (!server || server.bootId === null) return "unknown";
  const b = boots.find((x) => x.id === server.bootId);
  if (!b) return "unknown";
  if (b.type === "harddisk") return "disk";
  if (b.type === "rescue") return "rescue";
  return "other";
}

// ---------------------------------------------------------------------------
// 4. Virtual MAC repair (pure diagnosis)
// ---------------------------------------------------------------------------

export type VmacFix = "none" | "attach_to_vm_mac" | "recreate" | "detach_stale" | "fix_db";

export type VmacDiagnosis = {
  status: "ok" | "missing" | "mismatch" | "db_drift" | "unknown_vm" | "not_applicable";
  explanation: string;
  /** The OVH vMAC currently carrying this IP, if any. */
  ovhMac: string | null;
  vmMacs: string[];
  fixes: { fix: VmacFix; label: string; detail: string }[];
};

/**
 * `ovhMacs` = every vMAC on the node's OVH server -> the addresses it carries.
 * `vmMacs`  = every NIC MAC in the VM's Proxmox config (null = could not read).
 */
export function diagnoseVmac(input: {
  address: string;
  status: string;
  dbMac: string | null;
  ovhMacs: ReadonlyMap<string, readonly string[]>;
  vmMacs: readonly string[] | null;
  hasServer: boolean;
}): VmacDiagnosis {
  const norm = (m: string | null | undefined) => (m ? m.toLowerCase() : null);
  const dbMac = norm(input.dbMac);
  let ovhMac: string | null = null;
  for (const [m, addrs] of input.ovhMacs) if (addrs.includes(input.address)) ovhMac = norm(m);
  const vmMacs = (input.vmMacs ?? []).map((m) => m.toLowerCase());
  const base = { ovhMac, vmMacs };

  if (input.status !== "ASSIGNED") {
    if (ovhMac) {
      return {
        ...base,
        status: "mismatch",
        explanation: `The pool says this IP is ${input.status}, but OVH still binds it to vMAC ${ovhMac}. A leftover binding means the IP is not really free and the next customer would collide with it.`,
        fixes: [{ fix: "detach_stale", label: "Remove the stale OVH binding", detail: `DELETE ${input.address} from vMAC ${ovhMac} at OVH. Only do this if nothing uses the IP.` }],
      };
    }
    return { ...base, status: "not_applicable", explanation: `IP is ${input.status}; no vMAC expected and none bound.`, fixes: [] };
  }
  if (!input.hasServer) {
    return {
      ...base,
      status: ovhMac ? "ok" : "unknown_vm",
      explanation: ovhMac
        ? `Assigned to internal infrastructure (no Server row); OVH binds it to ${ovhMac}. Not checked against a VM.`
        : `Assigned to internal infrastructure (no Server row) and OVH has no vMAC for it. It may be reached by a DNAT rule instead (e.g. the shared-hosting node) - nothing to repair automatically.`,
      fixes: [],
    };
  }
  if (input.vmMacs === null) {
    return { ...base, status: "unknown_vm", explanation: "Could not read the VM's Proxmox config, so the NIC MAC is unknown. Nothing will be offered until it can be read.", fixes: [] };
  }

  const vmHasOvhMac = ovhMac !== null && vmMacs.includes(ovhMac);
  if (vmHasOvhMac) {
    if (dbMac !== ovhMac) {
      return {
        ...base,
        status: "db_drift",
        explanation: `OVH and the VM agree on ${ovhMac}, but the pool row says ${dbMac ?? "nothing"}. Only our database is wrong.`,
        fixes: [{ fix: "fix_db", label: "Update the pool row", detail: `Set DedicatedIp.virtualMac = ${ovhMac}. Database only; nothing is sent to OVH.` }],
      };
    }
    return { ...base, status: "ok", explanation: `OVH vMAC ${ovhMac} carries the IP and the VM's NIC uses it.`, fixes: [] };
  }

  // A VM NIC MAC that is already a vMAC on this OVH server (carrying other/no addresses).
  const vmMacKnownToOvh = vmMacs.find((m) => [...input.ovhMacs.keys()].some((k) => k.toLowerCase() === m)) ?? null;

  if (!ovhMac) {
    const fixes: VmacDiagnosis["fixes"] = [];
    if (vmMacKnownToOvh) {
      fixes.push({
        fix: "attach_to_vm_mac",
        label: `Attach the IP to the VM's vMAC ${vmMacKnownToOvh}`,
        detail: `POST virtualAddress ${input.address} on vMAC ${vmMacKnownToOvh}. The VM keeps its current MAC; no guest change needed.`,
      });
    }
    fixes.push({
      fix: "recreate",
      label: "Create a new OVH vMAC for the IP",
      detail:
        `POST a new vMAC for ${input.address}. OVH picks the MAC, so the VM's NIC must then be changed to it (Proxmox net config + guest restart) ` +
        `before traffic flows - the panel shows the exact command, it does not change the VM.`,
    });
    return {
      ...base,
      status: "missing",
      explanation: `OVH has NO vMAC for ${input.address}: OVH drops the VM's traffic on this IP at the switch (it only forwards frames from the registered MAC). The VM's NICs: ${vmMacs.join(", ") || "none"}.`,
      fixes,
    };
  }

  // OVH binds the IP to a MAC the VM does not use.
  const fixes: VmacDiagnosis["fixes"] = [];
  fixes.push({
    fix: "detach_stale",
    label: `Remove ${input.address} from vMAC ${ovhMac}`,
    detail: `DELETE the binding of ${input.address} from ${ovhMac} at OVH (step 1 of re-pointing it).`,
  });
  if (vmMacKnownToOvh) {
    fixes.push({
      fix: "attach_to_vm_mac",
      label: `Then attach it to the VM's vMAC ${vmMacKnownToOvh}`,
      detail: `POST virtualAddress ${input.address} on ${vmMacKnownToOvh} once the old binding is gone.`,
    });
  }
  return {
    ...base,
    status: "mismatch",
    explanation:
      `OVH binds ${input.address} to ${ovhMac}, but the VM's NICs are ${vmMacs.join(", ") || "none"}. ` +
      `Either the VM's NIC was regenerated (fix the VM to use ${ovhMac}, no OVH change) or the binding is stale (re-point it).`,
    fixes,
  };
}

/** NIC MACs from a Proxmox qemu config (netN = "virtio=AA:BB:..,bridge=..."). */
export function macsFromPveConfig(cfg: any): string[] {
  const out: string[] = [];
  if (!cfg || typeof cfg !== "object") return out;
  for (const [k, v] of Object.entries(cfg)) {
    if (!/^net\d+$/.test(k) || typeof v !== "string") continue;
    const m = /(?:^|,)(?:virtio|e1000|e1000e|rtl8139|vmxnet3|hwaddr)=([0-9A-Fa-f:]{17})/.exec(v);
    if (m) out.push(m[1].toLowerCase());
  }
  return out;
}

