/**
 * How the OVH admin controls reach OVH.
 *
 *  - READS go through `adminOvhGet` (GET only, hard-wired).
 *  - WRITES go through `ovhAdminWrite` in ./write.ts and NOWHERE else
 *    (test/ovh-admin.test.ts enforces this on the source tree).
 *
 * Screenshot/dev stub: with NXEON_OVH_ADMIN_STUB=1 on a non-production
 * process, both are served by an in-memory fake (./stub.ts) so the panels can
 * be rendered without touching the real account. The flag is ignored when
 * NODE_ENV=production, so a stray env var on prod cannot fake OVH state.
 */
import { ovh } from "../ovh";

export const OVH_ADMIN_STUB = process.env.NXEON_OVH_ADMIN_STUB === "1" && process.env.NODE_ENV !== "production";

export type OvhGetter = (path: string) => Promise<any>;
export type OvhSender = (method: "POST" | "PUT" | "DELETE", path: string, body?: unknown) => Promise<any>;

export async function adminOvhGet(path: string): Promise<any> {
  if (OVH_ADMIN_STUB) return (await import("./stub")).stubGet(path);
  return ovh("GET", path);
}

/** Only ./write.ts may import this. */
export async function rawOvhSend(method: "POST" | "PUT" | "DELETE", path: string, body?: unknown): Promise<any> {
  if (OVH_ADMIN_STUB) return (await import("./stub")).stubSend(method, path, body);
  return ovh(method, path, body);
}

export function ovhAdminConfigured(): boolean {
  if (OVH_ADMIN_STUB) return true;
  return !!(process.env.OVH_APPLICATION_KEY && process.env.OVH_APPLICATION_SECRET && process.env.OVH_CONSUMER_KEY);
}

