/**
 * THE single audited wrapper for every OVH write the admin controls make.
 *
 * Every POST/PUT/DELETE to OVH from lib/ovh-admin/** goes through
 * `ovhAdminWrite`, which, in order:
 *   1. refuses in sandbox (staging) unless the dev stub is on;
 *   2. checks the consumer key actually holds the right (graceful
 *      "needs OVH API right X" instead of a raw 403);
 *   3. rate-limits per actor (normal / dangerous classes) and per target;
 *   4. de-duplicates a double submit (same idempotency key within 30 s);
 *   5. reads the current state ("before") and returns a NO-OP if it already
 *      matches what was asked (idempotent: re-clicking "strict off" on an
 *      already-off IP sends nothing to OVH);
 *   6. writes an AuditLog row BEFORE sending (so a crash mid-call still leaves
 *      a trace) and another with the outcome;
 *   7. sends, then reads the state back ("after") and returns both, so the UI
 *      always shows what OVH really says, not what we hoped.
 *
 * Callers (lib/ovh-admin/actions.ts) are responsible for authentication,
 * input validation and typed confirmations BEFORE they get here.
 * test/ovh-admin.test.ts: "every OVH write goes through one audited wrapper".
 */
import { rawOvhSend, adminOvhGet, OVH_ADMIN_STUB } from "./transport";
import { parseCredentialRules, rulesAllow, needsRightMessage, rightsErrorFor, type AccessRule } from "./rights";

export type WriteMethod = "POST" | "PUT" | "DELETE";

export type WriteDeps = {
  send: (method: WriteMethod, path: string, body?: unknown) => Promise<any>;
  rules: () => Promise<AccessRule[] | null>;
  audit: (userId: string, action: string, detail: string) => Promise<void>;
  rateLimit: (key: string, opts: { max: number; windowMs: number }) => { ok: boolean; retryAfterSec: number };
  claimOnce: (key: string, ttlMs: number) => boolean;
  sandbox: boolean;
};

export type OvhWriteRequest<S> = {
  actor: { id: string };
  /** Audit action key, e.g. "ovh.game.strict". */
  action: string;
  /** Human target for the audit row, e.g. the IP or node name. */
  target: string;
  method: WriteMethod;
  path: string;
  body?: unknown;
  /** Reads the relevant OVH state; called before and after the write. */
  read: () => Promise<S>;
  /** True when `before` already equals the requested end state: nothing is sent. */
  isNoop?: (before: S) => boolean;
  idempotencyKey?: string;
  rateClass?: "normal" | "dangerous";
  /** Free text recorded in the audit row (reason, typed confirmation summary). */
  note?: string;
};

export type OvhWriteResult<S> =
  | { ok: true; noop: boolean; before: S; after: S; response: unknown }
  | { ok: false; error: string; before?: S; needsRight?: boolean };

export const RATE = {
  normal: { max: 30, windowMs: 10 * 60_000 },
  dangerous: { max: 3, windowMs: 60 * 60_000 },
  perTarget: { max: 12, windowMs: 10 * 60_000 },
} as const;

const RULES_TTL_MS = 5 * 60_000;
let rulesCache: { at: number; rules: AccessRule[] | null } | null = null;

/** The key's own access rules, cached 5 minutes. null = could not read them. */
export async function currentKeyRules(get: (p: string) => Promise<any> = adminOvhGet): Promise<AccessRule[] | null> {
  if (rulesCache && Date.now() - rulesCache.at < RULES_TTL_MS) return rulesCache.rules;
  let rules: AccessRule[] | null = null;
  try {
    rules = parseCredentialRules(await get("/auth/currentCredential"));
  } catch {
    rules = null;
  }
  rulesCache = { at: Date.now(), rules };
  return rules;
}

export function _resetRulesCacheForTests(): void {
  rulesCache = null;
}

async function defaultDeps(): Promise<WriteDeps> {
  const [{ recordAudit }, rl, { SANDBOX }] = await Promise.all([import("../audit"), import("../rate-limit"), import("../sandbox")]);
  return {
    send: rawOvhSend,
    rules: () => currentKeyRules(),
    audit: (u, a, d) => recordAudit(u, a, d),
    rateLimit: rl.checkRateLimit,
    claimOnce: rl.claimOnce,
    sandbox: SANDBOX && !OVH_ADMIN_STUB,
  };
}

function summarise(v: unknown, max = 900): string {
  let s: string;
  try {
    s = JSON.stringify(v);
  } catch {
    s = String(v);
  }
  return (s ?? "null").length > max ? `${s.slice(0, max)}...` : s ?? "null";
}

export async function ovhAdminWrite<S>(req: OvhWriteRequest<S>, depsIn?: Partial<WriteDeps>): Promise<OvhWriteResult<S>> {
  const deps: WriteDeps = { ...(depsIn && Object.keys(depsIn).length >= 6 ? ({} as WriteDeps) : await defaultDeps()), ...depsIn } as WriteDeps;
  const head = `${req.method} ${req.path} target=${req.target}`;

  if (deps.sandbox) return { ok: false, error: "OVH writes are disabled in sandbox/staging." };

  // 2. rights
  const rules = await deps.rules();
  if (rules && !rulesAllow(rules, req.method, req.path)) {
    return { ok: false, error: needsRightMessage(req.method, req.path), needsRight: true };
  }

  // 3. rate limits
  const cls = req.rateClass ?? "normal";
  const a = deps.rateLimit(`ovh-admin:${cls}:${req.actor.id}`, RATE[cls]);
  if (!a.ok) return { ok: false, error: `Too many OVH changes; try again in ${a.retryAfterSec}s.` };
  const t = deps.rateLimit(`ovh-admin:target:${req.target}`, RATE.perTarget);
  if (!t.ok) return { ok: false, error: `Too many changes to ${req.target}; try again in ${t.retryAfterSec}s.` };

  // 4. double-submit guard
  if (req.idempotencyKey && !deps.claimOnce(`ovh-admin:${req.actor.id}:${req.idempotencyKey}`, 30_000)) {
    return { ok: false, error: "That exact change was just submitted; refresh to see its result." };
  }

  // 5. before + no-op
  let before: S;
  try {
    before = await req.read();
  } catch (e) {
    return { ok: false, error: `Could not read the current OVH state, so nothing was changed: ${rightsErrorFor(e, "GET", req.path)}` };
  }
  if (req.isNoop?.(before)) {
    await deps.audit(req.actor.id, `${req.action}.noop`, `${head} already in the requested state ${req.note ? `note=${req.note} ` : ""}state=${summarise(before)}`);
    return { ok: true, noop: true, before, after: before, response: null };
  }

