  }

  // 7. read back
  let after: S;
  try {
    after = await req.read();
  } catch {
    after = before;
  }
  await deps.audit(req.actor.id, `${req.action}.ok`, `${head} response=${summarise(response, 300)} after=${summarise(after)}`);
  return { ok: true, noop: false, before, after, response };
}

