/**
 * GET-only readers that assemble the OVH admin panels. Every OVH call here is a
 * GET through an injectable getter (default: transport.adminOvhGet). Each
 * section fails independently: one 403/5xx shows "could not read X" in that
 * section, it never blanks the page.
 */
import { OvhHttpError } from "../ovh";
import { parseGameFirewall, parseNetworkFirewall, gameFirewallVerdict, networkFirewallVerdict, type GameFirewall, type NetworkFirewall, type Verdict as FwVerdict } from "../ovh-game-firewall";
import { adminOvhGet, type OvhGetter } from "./transport";
import { currentKeyRules } from "./write";
import { featureRights, isOverBroad, rightsErrorFor, type FeatureRights } from "./rights";
import {
  parseIpFacts, zoneVerdict, parseMitigation, mitigationSummary, parseBlock, BLOCK_KINDS, parseServiceInfos, renewalVerdict,
  parseNetworkSpec, trafficVerdict, parseTask, parseIntervention, parseBoot, parseServer, bootMode, diagnoseVmac, macsFromPveConfig,
  type IpFacts, type Verdict, type Mitigation, type IpBlock, type ServiceFacts, type RenewalVerdict, type TrafficFacts, type OvhTask,
  type Intervention, type BootOption, type ServerFacts, type VmacDiagnosis,
} from "./parse";

const enc = encodeURIComponent;
const MAX_LIST = 40;

async function orNull<T>(fn: () => Promise<T>): Promise<T | null> {
  try {
    return await fn();
  } catch (e: any) {
    if (e instanceof OvhHttpError ? e.status === 404 : /-> 404:/.test(String(e?.message))) return null;
    throw e;
  }
}

/** Run a section; capture its error as text (403 => "needs OVH API right GET ..."). */
async function section<T>(errors: Record<string, string>, name: string, path: string, fn: () => Promise<T>): Promise<T | null> {
  try {
    return await fn();
  } catch (e) {
    errors[name] = rightsErrorFor(e, "GET", path);
    return null;
  }
}

export type RightsView = { rights: FeatureRights; overBroad: boolean; rulesRead: boolean };

export async function readRights(get: OvhGetter = adminOvhGet): Promise<RightsView> {
  const rules = await currentKeyRules(get);
  return { rights: featureRights(rules), overBroad: isOverBroad(rules), rulesRead: rules !== null };
}

// ---------------------------------------------------------------------------
// Per-IP
// ---------------------------------------------------------------------------

export type GameView = GameFirewall & { supportedProtocols: string[]; verdict: FwVerdict };
export type NetView = NetworkFirewall & { verdict: FwVerdict };

export async function readGame(block: string, ip: string, get: OvhGetter = adminOvhGet): Promise<GameView> {
  const b = enc(block);
  const e = enc(ip);
  const body = await orNull(() => get(`/ip/${b}/game/${e}`));
  if (!body) {
    const g = parseGameFirewall(ip, null);
    return { ...g, supportedProtocols: [], verdict: gameFirewallVerdict(g) };
  }
  const ids = (await orNull(() => get(`/ip/${b}/game/${e}/rule`))) ?? [];
  const rules: any[] = [];
  for (const id of (Array.isArray(ids) ? ids : []).slice(0, MAX_LIST)) {
    const r = await orNull(() => get(`/ip/${b}/game/${e}/rule/${enc(String(id))}`));
    if (r) rules.push({ id, ...r });
  }
  const g = parseGameFirewall(ip, body, rules);
  return { ...g, supportedProtocols: Array.isArray(body.supportedProtocols) ? body.supportedProtocols : [], verdict: gameFirewallVerdict(g) };
}

/** Unlike the alert sweep, the panel reads rules even while the firewall is disabled (so they can be staged). */
export async function readNetwork(block: string, ip: string, get: OvhGetter = adminOvhGet): Promise<NetView> {
  const b = enc(block);
  const e = enc(ip);
  const list = await orNull(() => get(`/ip/${b}/firewall`));
  if (!Array.isArray(list) || !list.includes(ip)) {
    const n = parseNetworkFirewall(ip, list, null);
    return { ...n, verdict: networkFirewallVerdict(n) };
  }
  const detail = await orNull(() => get(`/ip/${b}/firewall/${e}`));
  const seqs = (await orNull(() => get(`/ip/${b}/firewall/${e}/rule`))) ?? [];
  const rules: any[] = [];
  for (const s of (Array.isArray(seqs) ? seqs : []).slice(0, MAX_LIST)) {
    const r = await orNull(() => get(`/ip/${b}/firewall/${e}/rule/${enc(String(s))}`));
    if (r) rules.push({ sequence: s, ...r });
  }
  const n = parseNetworkFirewall(ip, list, detail, rules);
  n.rules.sort((x, y) => (x.sequence ?? 99) - (y.sequence ?? 99));
  return { ...n, verdict: networkFirewallVerdict(n) };
}

export async function readReverse(block: string, ip: string, get: OvhGetter = adminOvhGet): Promise<string | null> {
  const r = await orNull(() => get(`/ip/${enc(block)}/reverse/${enc(ip)}`));
  return typeof r?.reverse === "string" ? r.reverse : null;
}

export async function readMitigation(block: string, ip: string, get: OvhGetter = adminOvhGet): Promise<Mitigation> {
  const list = await orNull(() => get(`/ip/${enc(block)}/mitigation`));
  const detail = Array.isArray(list) && list.includes(ip) ? await orNull(() => get(`/ip/${enc(block)}/mitigation/${enc(ip)}`)) : null;
  return parseMitigation(ip, list, detail);
}

/** Every antihack/spam/arp entry under the block (a /32 has at most one per kind). */
export async function readBlocks(block: string, get: OvhGetter = adminOvhGet): Promise<IpBlock[]> {
  const out: IpBlock[] = [];
  for (const kind of BLOCK_KINDS) {
    const ids = (await orNull(() => get(`/ip/${enc(block)}/${kind}`))) ?? [];
    for (const id of (Array.isArray(ids) ? ids : []).slice(0, 10)) {
      const b = parseBlock(kind, await orNull(() => get(`/ip/${enc(block)}/${kind}/${enc(String(id))}`)));
      if (b) out.push(b);
    }
  }
  return out;
}

export type IpTarget = {
  address: string;
  block: string;
  source: "node" | "pool";
  node: { id: string; name: string; region: string; providerServerId: string | null; pveNode: string; isPrimary: boolean };
  pool: {
    id: string;
    status: string;
    purpose: string;
    purposeLabel: string | null;
    virtualMac: string | null;
    reverse: string | null;
    server: { id: string; hostname: string; vmid: number | null; status: string; userEmail: string | null } | null;
  } | null;
};

export type IpPanel = {
  target: IpTarget;
  facts: IpFacts | null;
  zone: Verdict | null;
  game: GameView | null;
  network: NetView | null;
  reverse: string | null;
  mitigation: (Mitigation & { verdict: Verdict }) | null;
  blocks: IpBlock[] | null;
  errors: Record<string, string>;
  readAt: string;
};

export async function readIpPanel(target: IpTarget, get: OvhGetter = adminOvhGet): Promise<IpPanel> {
  const errors: Record<string, string> = {};
  const { block, address } = target;
  const facts = await section(errors, "facts", `/ip/${enc(block)}`, async () => parseIpFacts(await get(`/ip/${enc(block)}`)));
  const zone = facts ? zoneVerdict(target.node, facts) : null;
  const game = await section(errors, "game", `/ip/${enc(block)}/game`, () => readGame(block, address, get));
  const network = await section(errors, "network", `/ip/${enc(block)}/firewall`, () => readNetwork(block, address, get));
  const reverse = await section(errors, "reverse", `/ip/${enc(block)}/reverse`, () => readReverse(block, address, get));
  const m = await section(errors, "mitigation", `/ip/${enc(block)}/mitigation`, () => readMitigation(block, address, get));
  const blocks = await section(errors, "blocks", `/ip/${enc(block)}/antihack`, () => readBlocks(block, get));
  return {
    target,
    facts,
    zone,
    game,
    network,
    reverse,
    mitigation: m ? { ...m, verdict: mitigationSummary(m) } : null,
    blocks,
    errors,
    readAt: new Date().toISOString(),
  };
}

// ---------------------------------------------------------------------------
// Virtual MAC repair (OVH vMAC list + Proxmox VM NIC config)
// ---------------------------------------------------------------------------

/** vMAC -> addresses for one OVH dedicated server. */
export async function readVmacMap(serviceName: string, get: OvhGetter = adminOvhGet): Promise<Map<string, string[]>> {
  const s = enc(serviceName);
  const macs: unknown = (await orNull(() => get(`/dedicated/server/${s}/virtualMac`))) ?? [];
  const map = new Map<string, string[]>();
  for (const m of (Array.isArray(macs) ? macs : []).slice(0, 256)) {
    const addrs = (await orNull(() => get(`/dedicated/server/${s}/virtualMac/${enc(String(m))}/virtualAddress`))) ?? [];
    map.set(String(m).toLowerCase(), Array.isArray(addrs) ? addrs.map(String) : []);
  }
  return map;
}

export type VmacPanel = { diagnosis: VmacDiagnosis; error: string | null };

export async function readVmacPanel(
  target: IpTarget,
  readVmMacs: (() => Promise<string[] | null>) | null,
  get: OvhGetter = adminOvhGet,
): Promise<VmacPanel> {
  if (!target.pool || !target.node.providerServerId) {
    return { diagnosis: { status: "not_applicable", explanation: "Only pooled IPs on an OVH node have a vMAC.", ovhMac: null, vmMacs: [], fixes: [] }, error: null };
  }
  let map: Map<string, string[]>;
  try {
    map = await readVmacMap(target.node.providerServerId, get);
  } catch (e) {
    return {
      diagnosis: { status: "unknown_vm", explanation: "Could not read the node's OVH vMAC list.", ovhMac: null, vmMacs: [], fixes: [] },
      error: rightsErrorFor(e, "GET", `/dedicated/server/x/virtualMac`),
    };
  }
  let vmMacs: string[] | null = null;
  if (target.pool.server && readVmMacs) {
    try {
      vmMacs = await readVmMacs();
    } catch {
      vmMacs = null;
    }
  }
  return {
    diagnosis: diagnoseVmac({
      address: target.address,
      status: target.pool.status,
      dbMac: target.pool.virtualMac,
      ovhMacs: map,
      vmMacs,
      hasServer: !!target.pool.server,
    }),
    error: null,
  };
}

export { macsFromPveConfig };

// ---------------------------------------------------------------------------
// Per-node (dedicated server facts)
// ---------------------------------------------------------------------------

export type NodeIpRow = {
  address: string;
  block: string;
  source: "node" | "pool";
  poolStatus: string | null;
  label: string | null;
  facts: IpFacts | null;
  zone: Verdict | null;
  error: string | null;
};

export type NodePanel = {
  serviceName: string;
  server: ServerFacts | null;
  service: ServiceFacts | null;
  renewal: RenewalVerdict | null;
  traffic: TrafficFacts | null;
  trafficVerdict: Verdict | null;
  tasks: OvhTask[] | null;
  interventions: Intervention[] | null;
  boots: BootOption[] | null;
  bootMode: ReturnType<typeof bootMode>;
  rescueBootId: number | null;
  diskBootId: number | null;
  ips: NodeIpRow[];
  errors: Record<string, string>;
  readAt: string;
};

export async function readNodePanel(
  node: { name: string; region: string; providerServerId: string; publicIp: string },
  pool: readonly { address: string; ovhBlock: string; status: string; label: string | null }[],
  opts: { now?: Date; renewalAlertDays?: number } = {},
  get: OvhGetter = adminOvhGet,
): Promise<NodePanel> {
  const errors: Record<string, string> = {};
  const s = enc(node.providerServerId);
  const base = `/dedicated/server/${s}`;
  const server = await section(errors, "server", base, async () => parseServer(await get(base)));
  const service = await section(errors, "service", `${base}/serviceInfos`, async () => parseServiceInfos(await get(`${base}/serviceInfos`)));
  const traffic = await section(errors, "traffic", `${base}/specifications/network`, async () => parseNetworkSpec(await get(`${base}/specifications/network`)));
  const tasks = await section(errors, "tasks", `${base}/task`, async () => {
    const ids: unknown = (await get(`${base}/task`)) ?? [];
    const list = (Array.isArray(ids) ? ids : []).map(Number).filter(Number.isFinite).sort((a, b) => b - a).slice(0, 8);
    const out: OvhTask[] = [];
    for (const id of list) {
      const t = parseTask(await orNull(() => get(`${base}/task/${id}`)));
      if (t) out.push(t);
    }
    return out;
  });
  const interventions = await section(errors, "interventions", `${base}/intervention`, async () => {
    const ids: unknown = (await get(`${base}/intervention`)) ?? [];
    const list = (Array.isArray(ids) ? ids : []).map(Number).filter(Number.isFinite).sort((a, b) => b - a).slice(0, 5);
    const out: Intervention[] = [];
    for (const id of list) {
      const i = parseIntervention(await orNull(() => get(`${base}/intervention/${id}`)));
      if (i) out.push(i);
    }
    return out;
  });
  const boots = await section(errors, "boots", `${base}/boot`, async () => {
    const out: BootOption[] = [];
    for (const type of ["harddisk", "rescue"]) {
      const ids: unknown = (await get(`${base}/boot?bootType=${type}`)) ?? [];
      for (const id of (Array.isArray(ids) ? ids : []).slice(0, 6)) {
        const b = parseBoot(await orNull(() => get(`${base}/boot/${enc(String(id))}`)));
        if (b) out.push(b);
      }
    }
    return out;
  });

  const ips: NodeIpRow[] = [];
  const targets = [{ address: node.publicIp, block: `${node.publicIp}/32`, source: "node" as const, poolStatus: null, label: "node public IP" }].concat(
    pool.filter((p) => p.address !== node.publicIp).map((p) => ({ address: p.address, block: p.ovhBlock || `${p.address}/32`, source: "pool" as const, poolStatus: p.status as any, label: p.label as any })),
  );
  for (const t of targets) {
    try {
      const facts = parseIpFacts(await get(`/ip/${enc(t.block)}`));
      ips.push({ ...t, facts, zone: facts ? zoneVerdict({ name: node.name, region: node.region, providerServerId: node.providerServerId }, facts) : null, error: null });
    } catch (e) {
      ips.push({ ...t, facts: null, zone: null, error: rightsErrorFor(e, "GET", `/ip/${enc(t.block)}`) });
    }
  }

  const rescue = boots?.find((b) => b.type === "rescue") ?? null;
  const disk = boots?.find((b) => b.type === "harddisk") ?? null;
  return {
    serviceName: node.providerServerId,
    server,
    service,
    renewal: service ? renewalVerdict(service, opts.now ?? new Date(), opts.renewalAlertDays ?? 14) : null,
    traffic,
    trafficVerdict: traffic ? trafficVerdict(traffic) : null,
    tasks,
    interventions,
    boots,
    bootMode: bootMode(server, boots ?? []),
    rescueBootId: rescue?.id ?? null,
    diskBootId: disk?.id ?? null,
    ips,
    errors,
    readAt: new Date().toISOString(),
  };
}

