/**
 * In-memory fake of the OVH endpoints the admin panels use. Loaded ONLY when
 * NXEON_OVH_ADMIN_STUB=1 on a non-production process (see ./transport.ts), for
 * screenshots and local UI work. It never touches the network.
 *
 * All addresses are RFC 5737 documentation ranges. Writes mutate the fake and
 * go through a short "pending" state so the panels' settle-polling is visible.
 */

type Rule = { id: number; protocol: string; ports: { from: number; to: number }; state: string };
type NetRule = { sequence: number; action: string; protocol: string; destinationPort: string | null; source: string; state: string };
type IpState = {
  type: "dedicated" | "failover";
  routedTo: string;
  campus: string;
  regions: string[];
  game: { enabled: boolean; state: string; pendingUntil: number; target: boolean; rules: Rule[] } | null;
  fw: { enabled: boolean; state: string; rules: NetRule[] } | null;
  reverse: string | null;
  mitigation: { permanent: boolean; auto: boolean; state: string } | null;
  antihack: { blockedSince: string; state: string; time: number; logs: string } | null;
  spam: { date: string; state: string; time: number } | null;
};

const SVC_A = "ns000001.ip-203-0-113.net";
const SVC_B = "ns000002.ip-192-0-2.net";
const SUPPORTED = ["arkSurvivalEvolved", "arma", "hl2Source", "minecraftJava", "minecraftPocketEdition", "minecraftQuery", "mumble", "other", "rust", "teamspeak3"];

const g = globalThis as unknown as { __ovhStub?: { ips: Map<string, IpState>; bootId: Record<string, number>; nextId: number } };
function store() {
  if (g.__ovhStub) return g.__ovhStub;
  const ips = new Map<string, IpState>();
  const mk = (o: Partial<IpState>): IpState => ({
    type: "failover", routedTo: SVC_A, campus: "SGP", regions: ["ap-southeast-sgp"],
    game: { enabled: false, state: "ok", pendingUntil: 0, target: false, rules: [] }, fw: null, reverse: null, mitigation: null, antihack: null, spam: null, ...o,
  });
  ips.set("203.0.113.10", mk({ type: "dedicated", reverse: "ns000001.ip-203-0-113.net." }));
  ips.set("203.0.113.21", mk({
    game: { enabled: true, state: "ok", pendingUntil: 0, target: true, rules: [{ id: 442245, protocol: "other", ports: { from: 20055, to: 20055 }, state: "ok" }] },
    reverse: "game-21.example.net.",
  }));
  ips.set("203.0.113.22", mk({
    fw: { enabled: true, state: "ok", rules: [
      { sequence: 0, action: "permit", protocol: "tcp", destinationPort: "eq 22", source: "198.51.100.0/24", state: "ok" },
      { sequence: 1, action: "permit", protocol: "udp", destinationPort: "range 27015 27030", source: "any", state: "ok" },
      { sequence: 19, action: "deny", protocol: "ipv4", destinationPort: null, source: "any", state: "ok" },
    ] },
    antihack: { blockedSince: "2026-10-06T09:12:00+00:00", state: "blocked", time: 1800, logs: "Outbound SSH brute force to 198.51.100.77:22 (4213 attempts in 5 min)" },
  }));
  ips.set("203.0.113.23", mk({ mitigation: { permanent: false, auto: true, state: "ok" } }));
  ips.set("192.0.2.30", mk({ campus: "BHS", regions: ["ca-east-bhs"], routedTo: SVC_A }));
  ips.set("192.0.2.10", mk({ type: "dedicated", routedTo: SVC_B, campus: "BHS", regions: ["ca-east-bhs"] }));
  g.__ovhStub = { ips, bootId: { [SVC_A]: 1, [SVC_B]: 1 }, nextId: 500000 };
  return g.__ovhStub;
}

class StubError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
    this.name = "OvhHttpError";
  }
}
const nf = (p: string) => new StubError(`OVH GET ${p} -> 404: The requested object does not exist (stub)`, 404);

function settle(s: IpState) {
  if (s.game && s.game.pendingUntil && Date.now() > s.game.pendingUntil) {
    s.game.enabled = s.game.target;
    s.game.state = "ok";
    s.game.pendingUntil = 0;
  }
}

export async function stubGet(path: string): Promise<any> {
  const st = store();
  const [p, q] = path.split("?");
  const seg = p.split("/").filter(Boolean).map(decodeURIComponent);
  if (p === "/auth/currentCredential") {
    return { status: "validated", rules: ["GET", "POST", "PUT", "DELETE"].map((method) => ({ method, path: "/*" })) };
  }
  if (seg[0] === "ip") {
    if (seg.length === 1) return [...st.ips.keys()].map((i) => `${i}/32`);
    const ip = seg[1].split("/")[0];
    const s = st.ips.get(ip);
    if (!s) throw nf(p);
    settle(s);
    if (seg.length === 3 && seg[2] === "32") seg.splice(2, 1); // unencoded block form
    const rest = seg.slice(2);
    if (rest.length === 0) return { ip: `${ip}/32`, type: s.type, routedTo: { serviceName: s.routedTo }, campus: s.campus, regions: s.regions, country: s.campus === "SGP" ? "sg" : "ca", description: null, isAdditionalIp: s.type !== "dedicated", canBeTerminated: s.type !== "dedicated", rir: "ARIN" };
    const [kind, sub, x, y] = rest;
    if (kind === "game") {
      if (!sub) return s.game ? [ip] : [];
      if (!s.game) throw nf(p);
      if (!x) return { ipOnGame: ip, firewallModeEnabled: s.game.enabled, state: s.game.state, maxRules: 30, supportedProtocols: SUPPORTED };
      if (x === "rule" && !y) return s.game.rules.map((r) => r.id);
      const r = s.game.rules.find((rr) => String(rr.id) === y);
      if (!r) throw nf(p);
      return r;
    }
    if (kind === "firewall") {
      if (!sub) return s.fw ? [ip] : [];
      if (!s.fw) throw nf(p);
      if (!x) return { ipOnFirewall: ip, enabled: s.fw.enabled, state: s.fw.state };
      if (x === "rule" && !y) return s.fw.rules.map((r) => r.sequence);
      const r = s.fw.rules.find((rr) => String(rr.sequence) === y);
      if (!r) throw nf(p);
      return { ...r, rule: `${r.action} ${r.protocol}`, destination: `${ip}/32`, creationDate: "2026-10-01T00:00:00+00:00" };
    }
    if (kind === "reverse") {
      if (!sub) return s.reverse ? [ip] : [];
      if (!s.reverse) throw nf(p);
      return { ipReverse: ip, reverse: s.reverse };
    }
    if (kind === "mitigation") {
      if (!sub) return s.mitigation ? [ip] : [];
      if (!s.mitigation) throw nf(p);
      return { ipOnMitigation: ip, ...s.mitigation };
    }
    if (kind === "antihack" || kind === "arp") {
      const b = kind === "antihack" ? s.antihack : null;
      if (!sub) return b ? [ip] : [];
      if (!b) throw nf(p);
      return { ipBlocked: ip, ...b };
    }
