}

export type PowerAction = "reboot" | "rescue_on" | "rescue_off" | "rescue_on_reboot" | "rescue_off_reboot";
export const POWER_ACTIONS: PowerAction[] = ["reboot", "rescue_on", "rescue_off", "rescue_on_reboot", "rescue_off_reboot"];

export function powerActionLabel(a: PowerAction): string {
  return {
    reboot: "Hard reboot",
    rescue_on: "Set netboot to RESCUE (no reboot)",
    rescue_off: "Set netboot back to DISK (no reboot)",
    rescue_on_reboot: "Boot into RESCUE now (netboot rescue + hard reboot)",
    rescue_off_reboot: "Boot back to DISK now (netboot disk + hard reboot)",
  }[a];
}

export function powerActionReboots(a: PowerAction): boolean {
  return a === "reboot" || a.endsWith("_reboot");
}

/** Stable fingerprint of the VMs the warning listed (id + status), order-independent. */
export function vmFingerprint(vms: readonly { id: string; status: string }[]): string {
  const s = [...vms].map((v) => `${v.id}:${v.status}`).sort().join("|");
  return createHash("sha256").update(s).digest("hex").slice(0, 32);
}

export type Challenge = {
  nonce: string;
  userId: string;
  nodeId: string;
  nodeName: string;
  action: PowerAction;
  fingerprint: string;
  vmCount: number;
  expiresAt: number;
};

export const CHALLENGE_TTL_MS = 5 * 60_000;

export class ChallengeStore {
  private m = new Map<string, Challenge>();
  constructor(private now: () => number = Date.now) {}

  issue(c: Omit<Challenge, "nonce" | "expiresAt">): Challenge {
    this.gc();
    const nonce = randomBytes(24).toString("hex");
    const ch = { ...c, nonce, expiresAt: this.now() + CHALLENGE_TTL_MS };
    this.m.set(nonce, ch);
    return ch;
  }

  /**
   * Single-use: the nonce is consumed on ANY attempt (right or wrong), so a
   * mistyped confirmation means starting again from a freshly rendered warning.
   */
  redeem(input: {
    nonce: unknown;
    userId: string;
    typedName: unknown;
    ackVmCount: unknown;
    currentFingerprint: (nodeId: string) => Promise<string> | string;
  }): Promise<{ ok: true; challenge: Challenge } | { ok: false; error: string }> {
    return (async () => {
      if (typeof input.nonce !== "string" || !/^[0-9a-f]{48}$/.test(input.nonce)) return { ok: false as const, error: "Missing or malformed confirmation token. Start again." };
      const ch = this.m.get(input.nonce);
      this.m.delete(input.nonce);
      if (!ch) return { ok: false as const, error: "This confirmation was already used or never issued. Start again." };
      if (this.now() > ch.expiresAt) return { ok: false as const, error: "This confirmation expired (5 minutes). Start again." };
      if (ch.userId !== input.userId) return { ok: false as const, error: "This confirmation belongs to another admin session." };
      if (typeof input.typedName !== "string" || input.typedName.trim() !== ch.nodeName) {
        return { ok: false as const, error: `Typed name does not match the node name exactly. Start again.` };
      }
      const ack = typeof input.ackVmCount === "number" ? input.ackVmCount : Number(input.ackVmCount);
      if (!Number.isInteger(ack) || ack !== ch.vmCount) return { ok: false as const, error: `Confirm the number of affected customer VMs (${ch.vmCount}). Start again.` };
      const fp = await input.currentFingerprint(ch.nodeId);
      if (fp !== ch.fingerprint) return { ok: false as const, error: "The VMs on this node changed since the warning was shown (stale page). Review the new list and start again." };
      return { ok: true as const, challenge: ch };
    })();
  }

  private gc() {
    const t = this.now();
    for (const [k, v] of this.m) if (v.expiresAt < t) this.m.delete(k);
  }
}

