"use server";

/**
 * OVH admin controls — server actions. Every export is a network-reachable
 * endpoint, so every one of them:
 *   1. authenticates INSIDE the function (requireOvhAdmin / requireOvhOwner:
 *      real ADMIN session, fleet area, not impersonating; owner-only for
 *      reboot/rescue);
 *   2. validates every argument server-side (lib/ovh-admin/validate.ts) and
 *      only acts on an address/node the platform owns (lib/ovh-admin/targets.ts);
 *   3. sends every OVH write through the ONE audited wrapper
 *      (lib/ovh-admin/write.ts: rights check, rate limit, double-submit guard,
 *      before/after read-back, no-op when already in the requested state,
 *      AuditLog before + after);
 *   4. requires a typed confirmation for anything that changes production
 *      traffic filtering, unblocks an IP, or touches a node's power/boot.
 */
import { revalidatePath } from "next/cache";
import { realUser } from "../auth";
import { canAccess } from "../rbac";
import { db } from "../db";
import { recordAudit } from "../audit";
import { checkRateLimit } from "../rate-limit";
import { ovhAdminWrite, type OvhWriteResult } from "./write";
import { readGame, readNetwork, readReverse, readMitigation, readBlocks, readVmacMap, readVmacPanel, readRights, type GameView, type NetView } from "./read";
import { resolveOvhIp, resolveOvhNode, vmsOnNode, internalOnNode, readServerVmMacs } from "./targets";
import { adminOvhGet, ovhAdminConfigured } from "./transport";
import {
  parseGameProtocol, parsePortRange, parseNetworkRule, networkRuleBody, parseReverseHostname, typedConfirmationMatches, cleanReason, normMac, vmacName,
} from "./validate";
import { parseServer, parseTask, taskInFlight, parseBoot, BLOCK_KINDS, type BlockKind, type VmacFix } from "./parse";
import { isOwner, parseOwnerEmails, powerChallenges, vmFingerprint, POWER_ACTIONS, powerActionLabel, powerActionReboots, type PowerAction } from "./policy";

type Ok<T = object> = ({ ok: true } & T) | { ok: false; error: string; needsRight?: boolean };

const enc = encodeURIComponent;

// ---------------------------------------------------------------------------
// Guards
// ---------------------------------------------------------------------------

async function requireOvhAdmin() {
  const user = await realUser();
  if (!user) throw new Error("UNAUTHORIZED");
  if (user.role !== "ADMIN" || !canAccess(user.role, "fleet")) throw new Error("FORBIDDEN");
  const { impersonating } = await import("../auth");
  if (await impersonating()) throw new Error("This action is disabled while impersonating a customer.");
  if (!ovhAdminConfigured()) throw new Error("OVH API is not configured.");
  return user;
}

async function requireOvhOwner() {
  const user = await requireOvhAdmin();
  const adminCount = await db.user.count({ where: { role: "ADMIN" } });
  const v = isOwner(user, parseOwnerEmails(process.env.NXEON_OWNER_EMAILS), adminCount);
  if (!v.ok) throw new Error(v.error);
  return user;
}

/** Turn a guard throw into an Ok error so the UI can show it. */
async function guarded<T>(fn: () => Promise<Ok<T>>): Promise<Ok<T>> {
  try {
    return await fn();
  } catch (e: any) {
    return { ok: false, error: String(e?.message ?? e).slice(0, 300) };
  }
}

function fromWrite<S, T extends object>(r: OvhWriteResult<S>, extra: (r: Extract<OvhWriteResult<S>, { ok: true }>) => T): Ok<T & { noop: boolean }> {
  if (!r.ok) return { ok: false, error: r.error, needsRight: r.needsRight };
  return { ok: true, noop: r.noop, ...extra(r) };
}

function revalidateIp(address: string, nodeId?: string) {
  revalidatePath(`/admin/ips/${address}`);
  revalidatePath("/admin/ips");
  if (nodeId) revalidatePath(`/admin/nodes/${nodeId}`);
}

async function ipTargetOrThrow(address: unknown) {
  const t = await resolveOvhIp(address);
  if (!t) throw new Error("Not an OVH IP this platform manages.");
  return t;
}

const gameState = (g: GameView) => ({ exists: g.exists, enabled: g.firewallModeEnabled, state: g.state, rules: g.rules.map((r) => `${r.id}:${r.protocol}:${r.portFrom}-${r.portTo}`) });
const netState = (n: NetView) => ({ exists: n.exists, enabled: n.enabled, state: n.state, rules: n.rules.map((r) => `${r.sequence}:${r.action}:${r.protocol}:${r.destinationPort ?? "-"}:${r.source ?? "any"}`) });

// ---------------------------------------------------------------------------
// Reads used by the client (settle polling, rights)
// ---------------------------------------------------------------------------

/** Lightweight state for polling until OVH settles (e.g. firewallModeDisablePending -> ok). */
export async function pollIpState(address: string): Promise<Ok<{ game: ReturnType<typeof gameState> | null; network: ReturnType<typeof netState> | null; settled: boolean }>> {
  return guarded(async () => {
    await requireOvhAdmin();
    const rl = checkRateLimit(`ovh-admin:poll:${address}`, { max: 60, windowMs: 5 * 60_000 });
    if (!rl.ok) return { ok: false, error: "Polling too fast." };
    const t = await ipTargetOrThrow(address);
    const g = await readGame(t.block, t.address).catch(() => null);
    const n = await readNetwork(t.block, t.address).catch(() => null);
    const settled = (!g || !g.exists || g.state === "ok") && (!n || !n.exists || n.state === "ok") && !(n?.rules ?? []).some((r) => r.state && r.state !== "ok") && !(g?.rules ?? []).some((r) => r.state && r.state !== "ok");
    return { ok: true, game: g ? gameState(g) : null, network: n ? netState(n) : null, settled };
  });
}

export async function loadOvhRights(): Promise<Ok<Awaited<ReturnType<typeof readRights>>>> {
  return guarded(async () => {
    await requireOvhAdmin();
    return { ok: true, ...(await readRights()) };
  });
}

