export async function setGameStrict(address: string, enabled: boolean, typedIp: string): Promise<Ok<{ before: unknown; after: unknown }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    if (typeof enabled !== "boolean") return { ok: false, error: "Invalid request." };
    const t = await ipTargetOrThrow(address);
    if (!typedConfirmationMatches(t.address, typedIp)) return { ok: false, error: `Type the IP (${t.address}) exactly to confirm.` };
    const path = `/ip/${enc(t.block)}/game/${enc(t.address)}`;
    const r = await ovhAdminWrite({
      actor: admin,
      action: "ovh.game.strict",
      target: t.address,
      method: "PUT",
      path,
      body: { firewallModeEnabled: enabled },
      read: () => readGame(t.block, t.address),
      isNoop: (g) => {
        if (!g.exists) throw new Error("OVH has no game firewall object for this IP.");
        return g.firewallModeEnabled === enabled && g.state === "ok";
      },
      idempotencyKey: `game-strict:${t.address}:${enabled}`,
      rateClass: "dangerous",
      note: `strict=${enabled}`,
    }).catch((e) => ({ ok: false as const, error: String(e?.message ?? e) }));
    revalidateIp(t.address, t.node.id);
    return fromWrite(r, (w) => ({ before: gameState(w.before), after: gameState(w.after) }));
  });
}

export async function addGameRule(address: string, protocol: string, ports: string): Promise<Ok<{ before: unknown; after: unknown }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    const t = await ipTargetOrThrow(address);
    const pr = parsePortRange(ports);
    if (!pr.ok) return { ok: false, error: pr.error };
    const current = await readGame(t.block, t.address);
    if (!current.exists) return { ok: false, error: "OVH has no game firewall object for this IP." };
    const proto = parseGameProtocol(protocol, current.supportedProtocols);
    if (!proto.ok) return { ok: false, error: proto.error };
    const same = (g: GameView) => g.rules.some((r) => r.protocol === proto.value && r.portFrom === pr.value.from && r.portTo === pr.value.to);
    if (!same(current) && current.maxRules !== null && current.rules.length >= current.maxRules) {
      return { ok: false, error: `This IP already has the maximum ${current.maxRules} game rules.` };
    }
    const overlap = current.rules.find((r) => r.portFrom !== null && r.portTo !== null && r.portFrom <= pr.value.to && pr.value.from <= r.portTo && !(r.protocol === proto.value && r.portFrom === pr.value.from && r.portTo === pr.value.to));
    if (overlap) return { ok: false, error: `Ports overlap existing rule ${overlap.protocol}:${overlap.portFrom}-${overlap.portTo}; OVH refuses overlapping game rules. Remove it first.` };
    const r = await ovhAdminWrite({
      actor: admin,
      action: "ovh.game.rule.add",
      target: t.address,
      method: "POST",
      path: `/ip/${enc(t.block)}/game/${enc(t.address)}/rule`,
      body: { protocol: proto.value, ports: { from: pr.value.from, to: pr.value.to } },
      read: () => readGame(t.block, t.address),
      isNoop: same,
      idempotencyKey: `game-rule-add:${t.address}:${proto.value}:${pr.value.from}-${pr.value.to}`,
    });
    revalidateIp(t.address, t.node.id);
    return fromWrite(r, (w) => ({ before: gameState(w.before), after: gameState(w.after) }));
  });
}

export async function removeGameRule(address: string, ruleId: string): Promise<Ok<{ before: unknown; after: unknown }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    const t = await ipTargetOrThrow(address);
    if (typeof ruleId !== "string" || !/^\d{1,12}$/.test(ruleId)) return { ok: false, error: "Invalid rule id." };
    const r = await ovhAdminWrite({
      actor: admin,
      action: "ovh.game.rule.remove",
      target: t.address,
      method: "DELETE",
      path: `/ip/${enc(t.block)}/game/${enc(t.address)}/rule/${ruleId}`,
      read: () => readGame(t.block, t.address),
      isNoop: (g) => !g.rules.some((x) => String(x.id) === ruleId),
      idempotencyKey: `game-rule-rm:${t.address}:${ruleId}`,
    });
    revalidateIp(t.address, t.node.id);
    return fromWrite(r, (w) => ({ before: gameState(w.before), after: gameState(w.after) }));
  });
}

