export async function syncNodeIpPool(nodeId: string): Promise<Ok<{ imported: number; total: number; before: number }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    const node = await resolveOvhNode(nodeId);
    if (!node) return { ok: false, error: "Not an OVH node." };
    const rl = checkRateLimit(`ovh-admin:sync:${node.id}`, { max: 6, windowMs: 10 * 60_000 });
    if (!rl.ok) return { ok: false, error: `Synced recently; try again in ${rl.retryAfterSec}s.` };
    const before = await db.dedicatedIp.count({ where: { nodeId: node.id } });
    const { syncDedicatedIpPool } = await import("../dedicated-ip");
    // Read-only toward OVH (GET /ip + /ip/{block} + vMAC lookups); writes only new FREE rows to our DB.
    const r = await syncDedicatedIpPool(node.id);
    await recordAudit(admin.id, "ovh.pool.sync", `node=${node.name} before=${before} imported=${r.imported} total=${r.total}`);
    revalidatePath(`/admin/nodes/${node.id}`);
    revalidatePath("/admin/ips");
    return { ok: true, imported: r.imported, total: r.total, before };
  });
}

export async function loadVmacDiagnosis(address: string): Promise<Ok<{ diagnosis: unknown; error: string | null }>> {
  return guarded(async () => {
    await requireOvhAdmin();
    const t = await ipTargetOrThrow(address);
    const serverId = t.pool?.server?.id;
    const p = await readVmacPanel(t, serverId ? () => readServerVmMacs(serverId) : null);
    return { ok: true, diagnosis: p.diagnosis, error: p.error };
  });
}

export async function applyVmacFix(address: string, fix: string, typedIp: string): Promise<Ok<{ message: string; before?: unknown; after?: unknown }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    const t = await ipTargetOrThrow(address);
    if (!["attach_to_vm_mac", "recreate", "detach_stale", "fix_db"].includes(fix)) return { ok: false, error: "Unknown fix." };
    if (!typedConfirmationMatches(t.address, typedIp)) return { ok: false, error: `Type the IP (${t.address}) exactly to confirm.` };
    if (!t.pool || !t.node.providerServerId) return { ok: false, error: "Only pooled IPs on an OVH node have a vMAC." };
    const serverId = t.pool.server?.id;
    // Re-diagnose NOW: the fix must still be one the current state offers (no stale-page fixes).
    const p = await readVmacPanel(t, serverId ? () => readServerVmMacs(serverId) : null);
    if (p.error) return { ok: false, error: p.error };
    const d = p.diagnosis;
    if (!d.fixes.some((f) => f.fix === (fix as VmacFix))) return { ok: false, error: `"${fix}" is not a valid fix for the current state (${d.status}). Reload the page.` };
    const svc = t.node.providerServerId;
    const s = enc(svc);
    const readMap = async () => Object.fromEntries(await readVmacMap(svc));
    const name = vmacName(t.pool.server?.hostname ?? t.pool.purposeLabel ?? `nxeon-${t.address}`);

    if (fix === "fix_db") {
      await db.dedicatedIp.update({ where: { id: t.pool.id }, data: { virtualMac: d.ovhMac } });
      await recordAudit(admin.id, "ovh.vmac.fix_db", `${t.address} virtualMac ${t.pool.virtualMac ?? "null"} -> ${d.ovhMac}`);
      revalidateIp(t.address, t.node.id);
      return { ok: true, message: `Pool row now records ${d.ovhMac}.` };
    }
    if (fix === "detach_stale") {
      const mac = normMac(d.ovhMac);
      if (!mac) return { ok: false, error: "No OVH binding to remove." };
      const r = await ovhAdminWrite({
        actor: admin, action: "ovh.vmac.detach", target: t.address, method: "DELETE",
        path: `/dedicated/server/${s}/virtualMac/${enc(mac)}/virtualAddress/${enc(t.address)}`,
        read: readMap, isNoop: (m) => !(m[mac] ?? []).includes(t.address), idempotencyKey: `vmac-detach:${t.address}:${mac}`, rateClass: "dangerous",
      });
      if (r.ok && !r.noop && t.pool.virtualMac?.toLowerCase() === mac && t.pool.status !== "ASSIGNED") await db.dedicatedIp.update({ where: { id: t.pool.id }, data: { virtualMac: null } });
      revalidateIp(t.address, t.node.id);
      return fromWrite(r, (w) => ({ message: "OVH removes the binding asynchronously (a task); re-check in a minute.", before: w.before, after: w.after }));
    }
    if (fix === "attach_to_vm_mac") {
      const mac = d.vmMacs.find((m) => (d.fixes.find((f) => f.fix === "attach_to_vm_mac")?.label ?? "").toLowerCase().includes(m));
      if (!mac) return { ok: false, error: "Could not determine the VM's vMAC." };
      const r = await ovhAdminWrite({
        actor: admin, action: "ovh.vmac.attach", target: t.address, method: "POST",
        path: `/dedicated/server/${s}/virtualMac/${enc(mac)}/virtualAddress`,
        body: { ipAddress: t.address, virtualMachineName: name },
        read: readMap, isNoop: (m) => (m[mac] ?? []).includes(t.address), idempotencyKey: `vmac-attach:${t.address}:${mac}`,
      });
      if (r.ok) await db.dedicatedIp.update({ where: { id: t.pool.id }, data: { virtualMac: mac } });
      revalidateIp(t.address, t.node.id);
      return fromWrite(r, (w) => ({ message: `Attached ${t.address} to ${mac} (OVH task; settles in about a minute).`, before: w.before, after: w.after }));
    }
    // recreate
    const r = await ovhAdminWrite({
      actor: admin, action: "ovh.vmac.create", target: t.address, method: "POST",
      path: `/dedicated/server/${s}/virtualMac`,
      body: { ipAddress: t.address, type: "ovh", virtualMachineName: name },
      read: readMap, isNoop: (m) => Object.values(m).some((a) => a.includes(t.address)), idempotencyKey: `vmac-create:${t.address}`, rateClass: "dangerous",
    });
    revalidateIp(t.address, t.node.id);
    return fromWrite(r, (w) => {
      const created = Object.entries(w.after).find(([, a]) => a.includes(t.address))?.[0] ?? null;
      return {
        message: created
          ? `OVH created vMAC ${created}. The VM must now use it: qm set ${t.pool!.server?.vmid ?? "<vmid>"} --net<N> virtio=${created},bridge=<bridge> (then restart networking in the guest). Use "Fix DB" afterwards if the pool row differs.`
          : "OVH accepted the request (task). Reload in a minute to see the new vMAC, then point the VM's NIC at it.",
        before: w.before,
        after: w.after,
      };
    });
  });
}

