export type PowerWarning = {
  token: string;
  expiresAt: string;
  nodeName: string;
  serviceName: string;
  action: PowerAction;
  actionLabel: string;
  reboots: boolean;
  vms: { hostname: string; name: string; status: string; vmid: number | null; ip: string | null; owner: string | null }[];
  internal: { address: string; label: string }[];
  currentBoot: string;
};

export async function preparePowerAction(nodeId: string, action: string): Promise<Ok<{ warning: PowerWarning }>> {
  return guarded(async () => {
    const owner = await requireOvhOwner();
    if (!(POWER_ACTIONS as string[]).includes(action)) return { ok: false, error: "Unknown action." };
    const node = await resolveOvhNode(nodeId);
    if (!node) return { ok: false, error: "Not an OVH node." };
    const a = action as PowerAction;
    const vms = await vmsOnNode(node.id, node.isPrimary);
    const internal = await internalOnNode(node.id);
    const server = parseServer(await adminOvhGet(`/dedicated/server/${enc(node.providerServerId)}`).catch(() => null));
    const boot = server?.bootId != null ? parseBoot(await adminOvhGet(`/dedicated/server/${enc(node.providerServerId)}/boot/${server.bootId}`).catch(() => null)) : null;
    const ch = powerChallenges().issue({ userId: owner.id, nodeId: node.id, nodeName: node.name, action: a, fingerprint: vmFingerprint(vms), vmCount: vms.length });
    await recordAudit(owner.id, "ovh.power.prepare", `node=${node.name} action=${a} vms=${vms.length}`);
    return {
      ok: true,
      warning: {
        token: ch.nonce,
        expiresAt: new Date(ch.expiresAt).toISOString(),
        nodeName: node.name,
        serviceName: node.providerServerId,
        action: a,
        actionLabel: powerActionLabel(a),
        reboots: powerActionReboots(a),
        vms: vms.map(({ id: _id, ...v }) => v),
        internal,
        currentBoot: boot ? `${boot.type ?? "?"} (${boot.description ?? boot.kernel ?? boot.id})` : "unknown",
      },
    };
  });
}

export async function executePowerAction(token: string, typedNodeName: string, ackVmCount: number): Promise<Ok<{ message: string; before: unknown; after: unknown }>> {
  return guarded(async () => {
    const owner = await requireOvhOwner();
    const redeemed = await powerChallenges().redeem({
      nonce: token,
      userId: owner.id,
      typedName: typedNodeName,
      ackVmCount,
      currentFingerprint: async (nodeId) => {
        const n = await resolveOvhNode(nodeId);
        return vmFingerprint(n ? await vmsOnNode(n.id, n.isPrimary) : []);
      },
    });
    if (!redeemed.ok) {
      await recordAudit(owner.id, "ovh.power.refused", redeemed.error);
      return redeemed;
    }
    const ch = redeemed.challenge;
    const node = await resolveOvhNode(ch.nodeId);
    if (!node) return { ok: false, error: "Node vanished." };
    const s = enc(node.providerServerId);
    const base = `/dedicated/server/${s}`;
    const readState = async () => {
      const srv = parseServer(await adminOvhGet(base));
      const ids: unknown = (await adminOvhGet(`${base}/task`).catch(() => [])) ?? [];
      const recent = (Array.isArray(ids) ? ids : []).map(Number).sort((x, y) => y - x).slice(0, 5);
      const tasks = [];
      for (const id of recent) {
        const tk = parseTask(await adminOvhGet(`${base}/task/${id}`).catch(() => null));
        if (tk) tasks.push(tk);
      }
      return { bootId: srv?.bootId ?? null, powerState: srv?.powerState ?? null, state: srv?.state ?? null, tasks };
    };
    const note = `typed=${ch.nodeName} vms=${ch.vmCount} fp=${ch.fingerprint}`;
    const steps: string[] = [];
    let before: unknown = null;
    let after: unknown = null;

    if (ch.action !== "reboot") {
      const wantType = ch.action.startsWith("rescue_on") ? "rescue" : "harddisk";
      const ids: unknown = await adminOvhGet(`${base}/boot?bootType=${wantType}`);
      const bootId = Array.isArray(ids) && ids.length ? Number(ids[0]) : null;
      if (!bootId) return { ok: false, error: `OVH offers no ${wantType} boot for this server.` };
      const r = await ovhAdminWrite({
        actor: owner, action: "ovh.power.netboot", target: node.name, method: "PUT", path: base, body: { bootId },
        read: readState, isNoop: (st) => st.bootId === bootId, rateClass: "dangerous", idempotencyKey: `netboot:${node.id}:${bootId}`, note: `${note} netboot=${wantType}`,
      });
      if (!r.ok) return { ok: false, error: r.error, needsRight: r.needsRight };
      before = r.before;
      after = r.after;
      steps.push(r.noop ? `netboot already ${wantType}` : `netboot set to ${wantType} (bootId ${bootId})`);
    }
    if (powerActionReboots(ch.action)) {
      const r = await ovhAdminWrite({
        actor: owner, action: "ovh.power.reboot", target: node.name, method: "POST", path: `${base}/reboot`,
        read: readState,
        // Idempotent: a hard reboot already queued/running is not queued twice.
        isNoop: (st) => st.tasks.some((tk) => tk.fn === "hardReboot" && taskInFlight(tk)),
        rateClass: "dangerous", idempotencyKey: `reboot:${node.id}`, note,
      });
      if (!r.ok) return { ok: false, error: r.error, needsRight: r.needsRight };
      before ??= r.before;
      after = r.after;
      steps.push(r.noop ? "a hard reboot was already in progress; not queued again" : "hard reboot queued at OVH");
    }
    revalidatePath(`/admin/nodes/${node.id}`);
    return { ok: true, message: `${node.name}: ${steps.join("; ")}.`, before, after };
  });
}

