"use server";

/**
 * OVH admin controls — server actions. Every export is a network-reachable
 * endpoint, so every one of them:
 *   1. authenticates INSIDE the function (requireOvhAdmin / requireOvhOwner:
 *      real ADMIN session, fleet area, not impersonating; owner-only for
 *      reboot/rescue);
 *   2. validates every argument server-side (lib/ovh-admin/validate.ts) and
 *      only acts on an address/node the platform owns (lib/ovh-admin/targets.ts);
 *   3. sends every OVH write through the ONE audited wrapper
 *      (lib/ovh-admin/write.ts: rights check, rate limit, double-submit guard,
 *      before/after read-back, no-op when already in the requested state,
 *      AuditLog before + after);
 *   4. requires a typed confirmation for anything that changes production
 *      traffic filtering, unblocks an IP, or touches a node's power/boot.
 */
import { revalidatePath } from "next/cache";
import { realUser } from "../auth";
import { canAccess } from "../rbac";
import { db } from "../db";
import { recordAudit } from "../audit";
import { checkRateLimit } from "../rate-limit";
import { ovhAdminWrite, type OvhWriteResult } from "./write";
import { readGame, readNetwork, readReverse, readMitigation, readBlocks, readVmacMap, readVmacPanel, readRights, type GameView, type NetView } from "./read";
import { resolveOvhIp, resolveOvhNode, vmsOnNode, internalOnNode, readServerVmMacs } from "./targets";
import { adminOvhGet, ovhAdminConfigured } from "./transport";
import {
  parseGameProtocol, parsePortRange, parseNetworkRule, networkRuleBody, parseReverseHostname, typedConfirmationMatches, cleanReason, normMac, vmacName,
} from "./validate";
import { parseServer, parseTask, taskInFlight, parseBoot, BLOCK_KINDS, type BlockKind, type VmacFix } from "./parse";
import { isOwner, parseOwnerEmails, powerChallenges, vmFingerprint, POWER_ACTIONS, powerActionLabel, powerActionReboots, type PowerAction } from "./policy";

type Ok<T = object> = ({ ok: true } & T) | { ok: false; error: string; needsRight?: boolean };

const enc = encodeURIComponent;

// ---------------------------------------------------------------------------
// Guards
// ---------------------------------------------------------------------------

async function requireOvhAdmin() {
  const user = await realUser();
  if (!user) throw new Error("UNAUTHORIZED");
  if (user.role !== "ADMIN" || !canAccess(user.role, "fleet")) throw new Error("FORBIDDEN");
  const { impersonating } = await import("../auth");
  if (await impersonating()) throw new Error("This action is disabled while impersonating a customer.");
  if (!ovhAdminConfigured()) throw new Error("OVH API is not configured.");
  return user;
}

async function requireOvhOwner() {
  const user = await requireOvhAdmin();
  const adminCount = await db.user.count({ where: { role: "ADMIN" } });
  const v = isOwner(user, parseOwnerEmails(process.env.NXEON_OWNER_EMAILS), adminCount);
  if (!v.ok) throw new Error(v.error);
  return user;
}

/** Turn a guard throw into an Ok error so the UI can show it. */
async function guarded<T>(fn: () => Promise<Ok<T>>): Promise<Ok<T>> {
  try {
    return await fn();
  } catch (e: any) {
    return { ok: false, error: String(e?.message ?? e).slice(0, 300) };
  }
}

function fromWrite<S, T extends object>(r: OvhWriteResult<S>, extra: (r: Extract<OvhWriteResult<S>, { ok: true }>) => T): Ok<T & { noop: boolean }> {
  if (!r.ok) return { ok: false, error: r.error, needsRight: r.needsRight };
  return { ok: true, noop: r.noop, ...extra(r) };
}

function revalidateIp(address: string, nodeId?: string) {
  revalidatePath(`/admin/ips/${address}`);
  revalidatePath("/admin/ips");
  if (nodeId) revalidatePath(`/admin/nodes/${nodeId}`);
}

async function ipTargetOrThrow(address: unknown) {
  const t = await resolveOvhIp(address);
  if (!t) throw new Error("Not an OVH IP this platform manages.");
  return t;
}

const gameState = (g: GameView) => ({ exists: g.exists, enabled: g.firewallModeEnabled, state: g.state, rules: g.rules.map((r) => `${r.id}:${r.protocol}:${r.portFrom}-${r.portTo}`) });
const netState = (n: NetView) => ({ exists: n.exists, enabled: n.enabled, state: n.state, rules: n.rules.map((r) => `${r.sequence}:${r.action}:${r.protocol}:${r.destinationPort ?? "-"}:${r.source ?? "any"}`) });

// ---------------------------------------------------------------------------
// Reads used by the client (settle polling, rights)
// ---------------------------------------------------------------------------

/** Lightweight state for polling until OVH settles (e.g. firewallModeDisablePending -> ok). */
export async function pollIpState(address: string): Promise<Ok<{ game: ReturnType<typeof gameState> | null; network: ReturnType<typeof netState> | null; settled: boolean }>> {
  return guarded(async () => {
    await requireOvhAdmin();
    const rl = checkRateLimit(`ovh-admin:poll:${address}`, { max: 60, windowMs: 5 * 60_000 });
    if (!rl.ok) return { ok: false, error: "Polling too fast." };
    const t = await ipTargetOrThrow(address);
    const g = await readGame(t.block, t.address).catch(() => null);
    const n = await readNetwork(t.block, t.address).catch(() => null);
    const settled = (!g || !g.exists || g.state === "ok") && (!n || !n.exists || n.state === "ok") && !(n?.rules ?? []).some((r) => r.state && r.state !== "ok") && !(g?.rules ?? []).some((r) => r.state && r.state !== "ok");
    return { ok: true, game: g ? gameState(g) : null, network: n ? netState(n) : null, settled };
  });
}

export async function loadOvhRights(): Promise<Ok<Awaited<ReturnType<typeof readRights>>>> {
  return guarded(async () => {
    await requireOvhAdmin();
    return { ok: true, ...(await readRights()) };
  });
}

// ---------------------------------------------------------------------------
// 1. Game firewall
// ---------------------------------------------------------------------------

export async function setGameStrict(address: string, enabled: boolean, typedIp: string): Promise<Ok<{ before: unknown; after: unknown }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    if (typeof enabled !== "boolean") return { ok: false, error: "Invalid request." };
    const t = await ipTargetOrThrow(address);
    if (!typedConfirmationMatches(t.address, typedIp)) return { ok: false, error: `Type the IP (${t.address}) exactly to confirm.` };
    const path = `/ip/${enc(t.block)}/game/${enc(t.address)}`;
    const r = await ovhAdminWrite({
      actor: admin,
      action: "ovh.game.strict",
      target: t.address,
      method: "PUT",
      path,
      body: { firewallModeEnabled: enabled },
      read: () => readGame(t.block, t.address),
      isNoop: (g) => {
        if (!g.exists) throw new Error("OVH has no game firewall object for this IP.");
        return g.firewallModeEnabled === enabled && g.state === "ok";
      },
      idempotencyKey: `game-strict:${t.address}:${enabled}`,
      rateClass: "dangerous",
      note: `strict=${enabled}`,
    }).catch((e) => ({ ok: false as const, error: String(e?.message ?? e) }));
    revalidateIp(t.address, t.node.id);
    return fromWrite(r, (w) => ({ before: gameState(w.before), after: gameState(w.after) }));
  });
}

export async function addGameRule(address: string, protocol: string, ports: string): Promise<Ok<{ before: unknown; after: unknown }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    const t = await ipTargetOrThrow(address);
    const pr = parsePortRange(ports);
    if (!pr.ok) return { ok: false, error: pr.error };
    const current = await readGame(t.block, t.address);
    if (!current.exists) return { ok: false, error: "OVH has no game firewall object for this IP." };
    const proto = parseGameProtocol(protocol, current.supportedProtocols);
    if (!proto.ok) return { ok: false, error: proto.error };
    const same = (g: GameView) => g.rules.some((r) => r.protocol === proto.value && r.portFrom === pr.value.from && r.portTo === pr.value.to);
    if (!same(current) && current.maxRules !== null && current.rules.length >= current.maxRules) {
      return { ok: false, error: `This IP already has the maximum ${current.maxRules} game rules.` };
    }
    const overlap = current.rules.find((r) => r.portFrom !== null && r.portTo !== null && r.portFrom <= pr.value.to && pr.value.from <= r.portTo && !(r.protocol === proto.value && r.portFrom === pr.value.from && r.portTo === pr.value.to));
    if (overlap) return { ok: false, error: `Ports overlap existing rule ${overlap.protocol}:${overlap.portFrom}-${overlap.portTo}; OVH refuses overlapping game rules. Remove it first.` };
    const r = await ovhAdminWrite({
      actor: admin,
      action: "ovh.game.rule.add",
      target: t.address,
      method: "POST",
      path: `/ip/${enc(t.block)}/game/${enc(t.address)}/rule`,
      body: { protocol: proto.value, ports: { from: pr.value.from, to: pr.value.to } },
      read: () => readGame(t.block, t.address),
      isNoop: same,
      idempotencyKey: `game-rule-add:${t.address}:${proto.value}:${pr.value.from}-${pr.value.to}`,
    });
    revalidateIp(t.address, t.node.id);
    return fromWrite(r, (w) => ({ before: gameState(w.before), after: gameState(w.after) }));
  });
}

export async function removeGameRule(address: string, ruleId: string): Promise<Ok<{ before: unknown; after: unknown }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    const t = await ipTargetOrThrow(address);
    if (typeof ruleId !== "string" || !/^\d{1,12}$/.test(ruleId)) return { ok: false, error: "Invalid rule id." };
    const r = await ovhAdminWrite({
      actor: admin,
      action: "ovh.game.rule.remove",
      target: t.address,
      method: "DELETE",
      path: `/ip/${enc(t.block)}/game/${enc(t.address)}/rule/${ruleId}`,
      read: () => readGame(t.block, t.address),
      isNoop: (g) => !g.rules.some((x) => String(x.id) === ruleId),
      idempotencyKey: `game-rule-rm:${t.address}:${ruleId}`,
    });
    revalidateIp(t.address, t.node.id);
    return fromWrite(r, (w) => ({ before: gameState(w.before), after: gameState(w.after) }));
  });
}

// ---------------------------------------------------------------------------
// 2. Network firewall
// ---------------------------------------------------------------------------

export async function addIpToNetworkFirewall(address: string): Promise<Ok<{ before: unknown; after: unknown }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    const t = await ipTargetOrThrow(address);
    const r = await ovhAdminWrite({
      actor: admin,
      action: "ovh.netfw.create",
      target: t.address,
      method: "POST",
      path: `/ip/${enc(t.block)}/firewall`,
      body: { ipOnFirewall: t.address },
      read: () => readNetwork(t.block, t.address),
      isNoop: (n) => n.exists,
      idempotencyKey: `netfw-create:${t.address}`,
      note: "creates the firewall object DISABLED; enabling is a separate confirmed step",
    });
    revalidateIp(t.address, t.node.id);
    return fromWrite(r, (w) => ({ before: netState(w.before), after: netState(w.after) }));
  });
}

export async function setNetworkFirewallEnabled(address: string, enabled: boolean, typedIp: string): Promise<Ok<{ before: unknown; after: unknown }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    if (typeof enabled !== "boolean") return { ok: false, error: "Invalid request." };
    const t = await ipTargetOrThrow(address);
    if (!typedConfirmationMatches(t.address, typedIp)) return { ok: false, error: `Type the IP (${t.address}) exactly to confirm.` };
    const r = await ovhAdminWrite({
      actor: admin,
      action: "ovh.netfw.enabled",
      target: t.address,
      method: "PUT",
      path: `/ip/${enc(t.block)}/firewall/${enc(t.address)}`,
      body: { enabled },
      read: () => readNetwork(t.block, t.address),
      isNoop: (n) => {
        if (!n.exists) throw new Error("This IP is not on the OVH network firewall yet; add it first.");
        return n.enabled === enabled && n.state === "ok";
      },
      idempotencyKey: `netfw-enabled:${t.address}:${enabled}`,
      rateClass: "dangerous",
      note: `enabled=${enabled}`,
    }).catch((e) => ({ ok: false as const, error: String(e?.message ?? e) }));
    revalidateIp(t.address, t.node.id);
    return fromWrite(r, (w) => ({ before: netState(w.before), after: netState(w.after) }));
  });
}

export async function addNetworkRule(
  address: string,
  input: { sequence: string; action: string; protocol: string; ports?: string; source?: string },
): Promise<Ok<{ before: unknown; after: unknown }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    const t = await ipTargetOrThrow(address);
    const v = parseNetworkRule(input ?? {});
    if (!v.ok) return { ok: false, error: v.error };
    const rule = v.value;
    const body = networkRuleBody(rule);
    const current = await readNetwork(t.block, t.address);
    if (!current.exists) return { ok: false, error: "This IP is not on the OVH network firewall yet; add it first." };
    const portStr = rule.destinationPort ? (rule.destinationPort.from === rule.destinationPort.to ? `eq ${rule.destinationPort.from}` : `range ${rule.destinationPort.from} ${rule.destinationPort.to}`) : null;
    const identical = (n: NetView) =>
      n.rules.some((r) => r.sequence === rule.sequence && r.action === rule.action && r.protocol === rule.protocol && (r.destinationPort ?? null) === portStr && ((r.source ?? "any") === (rule.source ?? "any") || (rule.source === null && r.source === "0.0.0.0/0")));
    const taken = current.rules.find((r) => r.sequence === rule.sequence);
    if (taken && !identical(current)) return { ok: false, error: `Sequence ${rule.sequence} is already used by another rule; remove it first or pick a free sequence.` };
    const r = await ovhAdminWrite({
      actor: admin,
      action: "ovh.netfw.rule.add",
      target: t.address,
      method: "POST",
      path: `/ip/${enc(t.block)}/firewall/${enc(t.address)}/rule`,
      body,
      read: () => readNetwork(t.block, t.address),
      isNoop: identical,
      idempotencyKey: `netfw-rule:${t.address}:${JSON.stringify(body)}`,
    });
    revalidateIp(t.address, t.node.id);
    return fromWrite(r, (w) => ({ before: netState(w.before), after: netState(w.after) }));
  });
}

export async function removeNetworkRule(address: string, sequence: string): Promise<Ok<{ before: unknown; after: unknown }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    const t = await ipTargetOrThrow(address);
    if (typeof sequence !== "string" || !/^\d{1,2}$/.test(sequence) || Number(sequence) > 19) return { ok: false, error: "Invalid sequence." };
    const r = await ovhAdminWrite({
      actor: admin,
      action: "ovh.netfw.rule.remove",
      target: t.address,
      method: "DELETE",
      path: `/ip/${enc(t.block)}/firewall/${enc(t.address)}/rule/${sequence}`,
      read: () => readNetwork(t.block, t.address),
      isNoop: (n) => !n.rules.some((x) => String(x.sequence) === sequence),
      idempotencyKey: `netfw-rule-rm:${t.address}:${sequence}`,
    });
    revalidateIp(t.address, t.node.id);
    return fromWrite(r, (w) => ({ before: netState(w.before), after: netState(w.after) }));
  });
}

// ---------------------------------------------------------------------------
// 3. Reverse DNS
// ---------------------------------------------------------------------------

export async function setReverseDns(address: string, hostname: string): Promise<Ok<{ before: string | null; after: string | null }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    const t = await ipTargetOrThrow(address);
    const h = parseReverseHostname(hostname);
    if (!h.ok) return { ok: false, error: h.error };
    const res = await auditedReverseWrite(admin.id, t.block, t.address, h.value);
    if (!res.ok) return res;
    if (t.pool) await db.dedicatedIp.update({ where: { id: t.pool.id }, data: { reverse: res.after ?? h.value } });
    revalidateIp(t.address, t.node.id);
    return res;
  });
}

/**
 * The audited OVH reverse write, shared with lib/dedicated-ip.ts's
 * setDedicatedReverse (via its `write` parameter) so the older IP-pool form
 * goes through the same wrapper too. NOT exported (a "use server" export would
 * be a network endpoint); see `setReverseDns` above.
 */
async function auditedReverseWrite(actorId: string, block: string, ip: string, reverse: string): Promise<Ok<{ before: string | null; after: string | null; noop: boolean }>> {
  const r = await ovhAdminWrite({
    actor: { id: actorId },
    action: "ovh.reverse.set",
    target: ip,
    method: "POST",
    path: `/ip/${enc(block)}/reverse`,
    body: { ipReverse: ip, reverse },
    read: () => readReverse(block, ip),
    isNoop: (cur) => (cur ?? "").toLowerCase() === reverse.toLowerCase(),
    idempotencyKey: `reverse:${ip}:${reverse}`,
  });
  return fromWrite(r, (w) => ({ before: w.before, after: w.after }));
}

// ---------------------------------------------------------------------------
// 4. IP pool sync + virtual MAC repair
// ---------------------------------------------------------------------------

export async function syncNodeIpPool(nodeId: string): Promise<Ok<{ imported: number; total: number; before: number }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    const node = await resolveOvhNode(nodeId);
    if (!node) return { ok: false, error: "Not an OVH node." };
    const rl = checkRateLimit(`ovh-admin:sync:${node.id}`, { max: 6, windowMs: 10 * 60_000 });
    if (!rl.ok) return { ok: false, error: `Synced recently; try again in ${rl.retryAfterSec}s.` };
    const before = await db.dedicatedIp.count({ where: { nodeId: node.id } });
    const { syncDedicatedIpPool } = await import("../dedicated-ip");
    // Read-only toward OVH (GET /ip + /ip/{block} + vMAC lookups); writes only new FREE rows to our DB.
    const r = await syncDedicatedIpPool(node.id);
    await recordAudit(admin.id, "ovh.pool.sync", `node=${node.name} before=${before} imported=${r.imported} total=${r.total}`);
    revalidatePath(`/admin/nodes/${node.id}`);
    revalidatePath("/admin/ips");
    return { ok: true, imported: r.imported, total: r.total, before };
  });
}

export async function loadVmacDiagnosis(address: string): Promise<Ok<{ diagnosis: unknown; error: string | null }>> {
  return guarded(async () => {
    await requireOvhAdmin();
    const t = await ipTargetOrThrow(address);
    const serverId = t.pool?.server?.id;
    const p = await readVmacPanel(t, serverId ? () => readServerVmMacs(serverId) : null);
    return { ok: true, diagnosis: p.diagnosis, error: p.error };
  });
}

export async function applyVmacFix(address: string, fix: string, typedIp: string): Promise<Ok<{ message: string; before?: unknown; after?: unknown }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    const t = await ipTargetOrThrow(address);
    if (!["attach_to_vm_mac", "recreate", "detach_stale", "fix_db"].includes(fix)) return { ok: false, error: "Unknown fix." };
    if (!typedConfirmationMatches(t.address, typedIp)) return { ok: false, error: `Type the IP (${t.address}) exactly to confirm.` };
    if (!t.pool || !t.node.providerServerId) return { ok: false, error: "Only pooled IPs on an OVH node have a vMAC." };
    const serverId = t.pool.server?.id;
    // Re-diagnose NOW: the fix must still be one the current state offers (no stale-page fixes).
    const p = await readVmacPanel(t, serverId ? () => readServerVmMacs(serverId) : null);
    if (p.error) return { ok: false, error: p.error };
    const d = p.diagnosis;
    if (!d.fixes.some((f) => f.fix === (fix as VmacFix))) return { ok: false, error: `"${fix}" is not a valid fix for the current state (${d.status}). Reload the page.` };
    const svc = t.node.providerServerId;
    const s = enc(svc);
    const readMap = async () => Object.fromEntries(await readVmacMap(svc));
    const name = vmacName(t.pool.server?.hostname ?? t.pool.purposeLabel ?? `nxeon-${t.address}`);

    if (fix === "fix_db") {
      await db.dedicatedIp.update({ where: { id: t.pool.id }, data: { virtualMac: d.ovhMac } });
      await recordAudit(admin.id, "ovh.vmac.fix_db", `${t.address} virtualMac ${t.pool.virtualMac ?? "null"} -> ${d.ovhMac}`);
      revalidateIp(t.address, t.node.id);
      return { ok: true, message: `Pool row now records ${d.ovhMac}.` };
    }
    if (fix === "detach_stale") {
      const mac = normMac(d.ovhMac);
      if (!mac) return { ok: false, error: "No OVH binding to remove." };
      const r = await ovhAdminWrite({
        actor: admin, action: "ovh.vmac.detach", target: t.address, method: "DELETE",
        path: `/dedicated/server/${s}/virtualMac/${enc(mac)}/virtualAddress/${enc(t.address)}`,
        read: readMap, isNoop: (m) => !(m[mac] ?? []).includes(t.address), idempotencyKey: `vmac-detach:${t.address}:${mac}`, rateClass: "dangerous",
      });
      if (r.ok && !r.noop && t.pool.virtualMac?.toLowerCase() === mac && t.pool.status !== "ASSIGNED") await db.dedicatedIp.update({ where: { id: t.pool.id }, data: { virtualMac: null } });
      revalidateIp(t.address, t.node.id);
      return fromWrite(r, (w) => ({ message: "OVH removes the binding asynchronously (a task); re-check in a minute.", before: w.before, after: w.after }));
    }
    if (fix === "attach_to_vm_mac") {
      const mac = d.vmMacs.find((m) => (d.fixes.find((f) => f.fix === "attach_to_vm_mac")?.label ?? "").toLowerCase().includes(m));
      if (!mac) return { ok: false, error: "Could not determine the VM's vMAC." };
      const r = await ovhAdminWrite({
        actor: admin, action: "ovh.vmac.attach", target: t.address, method: "POST",
        path: `/dedicated/server/${s}/virtualMac/${enc(mac)}/virtualAddress`,
        body: { ipAddress: t.address, virtualMachineName: name },
        read: readMap, isNoop: (m) => (m[mac] ?? []).includes(t.address), idempotencyKey: `vmac-attach:${t.address}:${mac}`,
      });
      if (r.ok) await db.dedicatedIp.update({ where: { id: t.pool.id }, data: { virtualMac: mac } });
      revalidateIp(t.address, t.node.id);
      return fromWrite(r, (w) => ({ message: `Attached ${t.address} to ${mac} (OVH task; settles in about a minute).`, before: w.before, after: w.after }));
    }
    // recreate
    const r = await ovhAdminWrite({
      actor: admin, action: "ovh.vmac.create", target: t.address, method: "POST",
      path: `/dedicated/server/${s}/virtualMac`,
      body: { ipAddress: t.address, type: "ovh", virtualMachineName: name },
      read: readMap, isNoop: (m) => Object.values(m).some((a) => a.includes(t.address)), idempotencyKey: `vmac-create:${t.address}`, rateClass: "dangerous",
    });
    revalidateIp(t.address, t.node.id);
    return fromWrite(r, (w) => {
      const created = Object.entries(w.after).find(([, a]) => a.includes(t.address))?.[0] ?? null;
      return {
        message: created
          ? `OVH created vMAC ${created}. The VM must now use it: qm set ${t.pool!.server?.vmid ?? "<vmid>"} --net<N> virtio=${created},bridge=<bridge> (then restart networking in the guest). Use "Fix DB" afterwards if the pool row differs.`
          : "OVH accepted the request (task). Reload in a minute to see the new vMAC, then point the VM's NIC at it.",
        before: w.before,
        after: w.after,
      };
    });
  });
}

// ---------------------------------------------------------------------------
// 5. Permanent mitigation
// ---------------------------------------------------------------------------

export async function setPermanentMitigation(address: string, on: boolean, typedIp: string): Promise<Ok<{ before: unknown; after: unknown }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    if (typeof on !== "boolean") return { ok: false, error: "Invalid request." };
    const t = await ipTargetOrThrow(address);
    if (!typedConfirmationMatches(t.address, typedIp)) return { ok: false, error: `Type the IP (${t.address}) exactly to confirm.` };
    const r = on
      ? await ovhAdminWrite({
          actor: admin, action: "ovh.mitigation.on", target: t.address, method: "POST",
          path: `/ip/${enc(t.block)}/mitigation`, body: { ipOnMitigation: t.address },
          read: () => readMitigation(t.block, t.address), isNoop: (m) => m.exists && m.permanent === true,
          idempotencyKey: `mitigation:${t.address}:on`,
        })
      : await ovhAdminWrite({
          actor: admin, action: "ovh.mitigation.off", target: t.address, method: "DELETE",
          path: `/ip/${enc(t.block)}/mitigation/${enc(t.address)}`,
          read: () => readMitigation(t.block, t.address), isNoop: (m) => !m.exists || m.permanent !== true,
          idempotencyKey: `mitigation:${t.address}:off`,
        });
    revalidateIp(t.address, t.node.id);
    return fromWrite(r, (w) => ({ before: w.before, after: w.after }));
  });
}

// ---------------------------------------------------------------------------
// 6. Unblock (antihack / spam / arp)
// ---------------------------------------------------------------------------

export async function unblockIp(address: string, kind: string, typedIp: string, reason: string): Promise<Ok<{ before: unknown; after: unknown }>> {
  return guarded(async () => {
    const admin = await requireOvhAdmin();
    const t = await ipTargetOrThrow(address);
    if (!(BLOCK_KINDS as string[]).includes(kind)) return { ok: false, error: "Unknown block type." };
    if (!typedConfirmationMatches(t.address, typedIp)) return { ok: false, error: `Type the IP (${t.address}) exactly to confirm.` };
    const why = cleanReason(reason);
    if (why.length < 10) return { ok: false, error: "Say what you checked before unblocking (at least 10 characters) - a blocked customer IP usually means a compromised VM, and OVH re-blocks repeat offenders for longer." };
    const k = kind as BlockKind;
    const read = async () => (await readBlocks(t.block)).filter((b) => b.kind === k && b.ip === t.address);
    const r = await ovhAdminWrite({
      actor: admin, action: `ovh.unblock.${k}`, target: t.address, method: "POST",
      path: `/ip/${enc(t.block)}/${k}/${enc(t.address)}/unblock`,
      read, isNoop: (bs) => !bs.some((b) => b.blocked),
      idempotencyKey: `unblock:${t.address}:${k}`, rateClass: "dangerous",
      note: `reason=${why}${t.pool?.server ? ` server=${t.pool.server.hostname}` : ""}`,
    });
    revalidateIp(t.address, t.node.id);
    return fromWrite(r, (w) => ({ before: w.before, after: w.after }));
  });
}

// ---------------------------------------------------------------------------
// 9. Reboot / rescue (owner only, challenge-guarded)
// ---------------------------------------------------------------------------

export type PowerWarning = {
  token: string;
  expiresAt: string;
  nodeName: string;
  serviceName: string;
  action: PowerAction;
  actionLabel: string;
  reboots: boolean;
  vms: { hostname: string; name: string; status: string; vmid: number | null; ip: string | null; owner: string | null }[];
  internal: { address: string; label: string }[];
  currentBoot: string;
};

export async function preparePowerAction(nodeId: string, action: string): Promise<Ok<{ warning: PowerWarning }>> {
  return guarded(async () => {
    const owner = await requireOvhOwner();
    if (!(POWER_ACTIONS as string[]).includes(action)) return { ok: false, error: "Unknown action." };
    const node = await resolveOvhNode(nodeId);
    if (!node) return { ok: false, error: "Not an OVH node." };
    const a = action as PowerAction;
    const vms = await vmsOnNode(node.id, node.isPrimary);
    const internal = await internalOnNode(node.id);
    const server = parseServer(await adminOvhGet(`/dedicated/server/${enc(node.providerServerId)}`).catch(() => null));
    const boot = server?.bootId != null ? parseBoot(await adminOvhGet(`/dedicated/server/${enc(node.providerServerId)}/boot/${server.bootId}`).catch(() => null)) : null;
    const ch = powerChallenges().issue({ userId: owner.id, nodeId: node.id, nodeName: node.name, action: a, fingerprint: vmFingerprint(vms), vmCount: vms.length });
    await recordAudit(owner.id, "ovh.power.prepare", `node=${node.name} action=${a} vms=${vms.length}`);
    return {
      ok: true,
      warning: {
        token: ch.nonce,
        expiresAt: new Date(ch.expiresAt).toISOString(),
        nodeName: node.name,
        serviceName: node.providerServerId,
        action: a,
        actionLabel: powerActionLabel(a),
        reboots: powerActionReboots(a),
        vms: vms.map(({ id: _id, ...v }) => v),
        internal,
        currentBoot: boot ? `${boot.type ?? "?"} (${boot.description ?? boot.kernel ?? boot.id})` : "unknown",
      },
    };
  });
}

export async function executePowerAction(token: string, typedNodeName: string, ackVmCount: number): Promise<Ok<{ message: string; before: unknown; after: unknown }>> {
  return guarded(async () => {
    const owner = await requireOvhOwner();
    const redeemed = await powerChallenges().redeem({
      nonce: token,
      userId: owner.id,
      typedName: typedNodeName,
      ackVmCount,
      currentFingerprint: async (nodeId) => {
        const n = await resolveOvhNode(nodeId);
        return vmFingerprint(n ? await vmsOnNode(n.id, n.isPrimary) : []);
      },
    });
    if (!redeemed.ok) {
      await recordAudit(owner.id, "ovh.power.refused", redeemed.error);
      return redeemed;
    }
    const ch = redeemed.challenge;
    const node = await resolveOvhNode(ch.nodeId);
    if (!node) return { ok: false, error: "Node vanished." };
    const s = enc(node.providerServerId);
    const base = `/dedicated/server/${s}`;
    const readState = async () => {
      const srv = parseServer(await adminOvhGet(base));
      const ids: unknown = (await adminOvhGet(`${base}/task`).catch(() => [])) ?? [];
      const recent = (Array.isArray(ids) ? ids : []).map(Number).sort((x, y) => y - x).slice(0, 5);
      const tasks = [];
      for (const id of recent) {
        const tk = parseTask(await adminOvhGet(`${base}/task/${id}`).catch(() => null));
        if (tk) tasks.push(tk);
      }
      return { bootId: srv?.bootId ?? null, powerState: srv?.powerState ?? null, state: srv?.state ?? null, tasks };
    };
    const note = `typed=${ch.nodeName} vms=${ch.vmCount} fp=${ch.fingerprint}`;
    const steps: string[] = [];
    let before: unknown = null;
    let after: unknown = null;

    if (ch.action !== "reboot") {
      const wantType = ch.action.startsWith("rescue_on") ? "rescue" : "harddisk";
      const ids: unknown = await adminOvhGet(`${base}/boot?bootType=${wantType}`);
      const bootId = Array.isArray(ids) && ids.length ? Number(ids[0]) : null;
      if (!bootId) return { ok: false, error: `OVH offers no ${wantType} boot for this server.` };
      const r = await ovhAdminWrite({
        actor: owner, action: "ovh.power.netboot", target: node.name, method: "PUT", path: base, body: { bootId },
        read: readState, isNoop: (st) => st.bootId === bootId, rateClass: "dangerous", idempotencyKey: `netboot:${node.id}:${bootId}`, note: `${note} netboot=${wantType}`,
      });
      if (!r.ok) return { ok: false, error: r.error, needsRight: r.needsRight };
      before = r.before;
      after = r.after;
      steps.push(r.noop ? `netboot already ${wantType}` : `netboot set to ${wantType} (bootId ${bootId})`);
    }
    if (powerActionReboots(ch.action)) {
      const r = await ovhAdminWrite({
        actor: owner, action: "ovh.power.reboot", target: node.name, method: "POST", path: `${base}/reboot`,
        read: readState,
        // Idempotent: a hard reboot already queued/running is not queued twice.
        isNoop: (st) => st.tasks.some((tk) => tk.fn === "hardReboot" && taskInFlight(tk)),
        rateClass: "dangerous", idempotencyKey: `reboot:${node.id}`, note,
      });
      if (!r.ok) return { ok: false, error: r.error, needsRight: r.needsRight };
      before ??= r.before;
      after = r.after;
      steps.push(r.noop ? "a hard reboot was already in progress; not queued again" : "hard reboot queued at OVH");
    }
    revalidatePath(`/admin/nodes/${node.id}`);
    return { ok: true, message: `${node.name}: ${steps.join("; ")}.`, before, after };
  });
}

