/**
 * Pure: per-node OVH account readings -> DesiredAlerts for the shared fleet-alert
 * machinery (lib/fleet-alert-plan.ts -> worker/fleet-alerts.ts). No I/O.
 * Used by worker/ovh-account-sweep.ts.
 *
 *   OVH-BLOCK:<kind>:<ip>   OVH antihack/spam/ARP-blocked one of our IPs.     CRITICAL
 *                           A blocked customer IP almost always means a
 *                           compromised VM; the alert names the server + owner.
 *   OVH-RENEW:<service>     a node's OVH service expires within N days with
 *                           auto-renew OFF (or delete-at-expiration on), or is
 *                           past due. WARN, CRITICAL inside 3 days / past due.
 *
 * Only a firm reading raises, keeps or resolves: a node with any unreadable IP
 * or an unreadable service is left out of `readNodeIds`.
 */
import type { DesiredAlert } from "../fleet-alert-plan";
import { BLOCK_REASON, renewalVerdict, type IpBlock, type ServiceFacts } from "./parse";

export const OVH_BLOCK_PREFIX = "OVH-BLOCK:";
export const OVH_RENEW_PREFIX = "OVH-RENEW:";
export const OVH_RENEWAL_ALERT_DAYS_SETTING = "ovh_renewal_alert_days";
export const OVH_ACCOUNT_SWEEP_SETTING = "ovh_account_sweep_enabled";

export type IpBlockReading = {
  ip: string;
  source: "node" | "pool";
  label: string | null;
  server: { hostname: string; owner: string | null; vmid: number | null } | null;
  blocks: IpBlock[] | null; // null = could not read
};

export type NodeAccountReading = {
  nodeId: string;
  nodeName: string;
  serviceName: string;
  ips: IpBlockReading[];
  service: ServiceFacts | null; // null = could not read
};

export function desiredOvhAccountAlerts(
  readings: readonly NodeAccountReading[],
  opts: { now: Date; renewalAlertDays: number },
): { desired: DesiredAlert[]; readNodeIds: Set<string> } {
  const desired: DesiredAlert[] = [];
  const readNodeIds = new Set<string>();
  for (const n of readings) {
    if (n.service && n.ips.every((i) => i.blocks !== null)) readNodeIds.add(n.nodeId);
    for (const i of n.ips) {
      for (const b of i.blocks ?? []) {
        if (!b.blocked) continue;
        const who = i.server
          ? `customer server ${i.server.hostname}${i.server.vmid ? ` (VM ${i.server.vmid})` : ""}${i.server.owner ? `, owner ${i.server.owner}` : ""}`
          : i.source === "node"
            ? `the NODE's own public IP - every VM NATed through ${n.nodeName} is affected`
            : i.label
              ? `internal: ${i.label}`
              : "no server assigned";
        desired.push({
          nodeId: n.nodeId,
          nodeName: n.nodeName,
          dimension: `${OVH_BLOCK_PREFIX}${b.kind}:${i.ip}`,
          severity: "CRITICAL",
          title: `OVH ${b.kind} block on ${i.ip} (${i.server?.hostname ?? n.nodeName})`,
          detail:
            `${n.nodeName}: OVH has ${b.kind === "spam" ? "spam-blocked" : "blocked"} ${i.ip} (${who}) since ${b.since ?? "?"}, state ${b.state ?? "?"}` +
            `${b.timeSec !== null ? `, OVH block time ${b.timeSec}s` : ""}. ${BLOCK_REASON[b.kind]} ` +
            `Investigate the VM (processes, outbound connections, recent logins) BEFORE unblocking; OVH re-blocks repeat offenders for longer. ` +
            `Details + unblock: /admin/ips/${i.ip}` +
            (b.logs ? ` OVH log: ${b.logs.slice(0, 400)}` : ""),
        });
      }
    }
    if (n.service) {
      const v = renewalVerdict(n.service, opts.now, opts.renewalAlertDays);
      if (v.alert) {
        desired.push({
          nodeId: n.nodeId,
          nodeName: n.nodeName,
          dimension: `${OVH_RENEW_PREFIX}${n.serviceName}`,
          severity: v.level === "FAIL" ? "CRITICAL" : "WARN",
          title: `OVH renewal: ${n.nodeName} ${v.summary}`,
          detail:
            `${n.nodeName} (${n.serviceName}) ${v.summary}. If it lapses OVH suspends then deletes the server and every customer VM on it. ` +
            `Turn auto-renew on or renew manually in the OVH manager (Bare Metal Cloud > ${n.serviceName} > Renewal).`,
        });
      }
    }
  }
  return { desired, readNodeIds };
}

