/**
 * OVH account sweep (hourly). READ-ONLY toward OVH (GET only).
 *
 * For every enabled OVH node, reads:
 *   - every IP's antihack / spam / ARP block state (node public IP + every DedicatedIp row)
 *   - the dedicated server's serviceInfos (expiration, auto-renew)
 * and raises debounced, auto-resolving admin alerts through the shared fleet-alert
 * machinery (lib/ovh-admin/alert-plan.ts; prefixes OVH-BLOCK: / OVH-RENEW:).
 * A blocked customer IP almost always means a compromised VM, so the alert names
 * the customer server and its owner.
 *
 * Default ON (it only reads). Off: Setting `ovh_account_sweep_enabled` = false.
 * Renewal window: Setting `ovh_renewal_alert_days` (default 14).
 * Failure-silent with a hard deadline, like the game-firewall sweep.
 */
import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { getSettingBool, getSettingInt } from "../lib/settings";
import { ovhConfigured } from "../lib/ovh";
import { planFleetAlerts, SWEEP_PREFIXES } from "../lib/fleet-alert-plan";
import { readBlocks } from "../lib/ovh-admin/read";
import { parseServiceInfos } from "../lib/ovh-admin/parse";
import { desiredOvhAccountAlerts, OVH_ACCOUNT_SWEEP_SETTING, OVH_RENEWAL_ALERT_DAYS_SETTING, type NodeAccountReading } from "../lib/ovh-admin/alert-plan";
import { ovh } from "../lib/ovh";
import { applyFleetAlerts, openFleetAlerts } from "./fleet-alerts";

export const OVH_ACCOUNT_SWEEP_DEADLINE_MS = 5 * 60_000;
const get = (path: string) => ovh("GET", path);

export async function ovhAccountSweep(): Promise<void> {
  if (SANDBOX || !ovhConfigured()) return;
  try {
    if (!(await getSettingBool(OVH_ACCOUNT_SWEEP_SETTING, true))) return;
    let timer: NodeJS.Timeout | undefined;
    const deadline = new Promise<"timeout">((res) => { timer = setTimeout(() => res("timeout"), OVH_ACCOUNT_SWEEP_DEADLINE_MS); });
    const r = await Promise.race([runSweep().then(() => "done" as const), deadline]);
    if (timer) clearTimeout(timer);
    if (r === "timeout") console.error("[ovh-account] sweep exceeded its deadline; skipped this round");
  } catch (e) {
    console.error("[ovh-account] sweep failed (ignored)", e instanceof Error ? e.message : e);
  }
}

async function runSweep(): Promise<void> {
  const nodes = await db.node.findMany({
    where: { enabled: true, provider: "OVH", providerServerId: { not: null } },
    select: {
      id: true, name: true, publicIp: true, providerServerId: true,
      dedicatedIps: { select: { address: true, ovhBlock: true, purposeLabel: true, server: { select: { hostname: true, vmid: true, user: { select: { email: true } } } } } },
    },
  });
  const readings: NodeAccountReading[] = [];
  for (const n of nodes) {
    const svc = n.providerServerId!;
    let service = null;
    try {
      service = parseServiceInfos(await get(`/dedicated/server/${encodeURIComponent(svc)}/serviceInfos`));
    } catch (e) {
      console.error(`[ovh-account] ${n.name}: serviceInfos unreadable (${e instanceof Error ? e.message : e})`);
    }
    const targets = [{ ip: n.publicIp, block: `${n.publicIp}/32`, source: "node" as const, label: "node public IP", server: null as NodeAccountReading["ips"][number]["server"] }];
    for (const d of n.dedicatedIps) {
      if (d.address === n.publicIp) continue;
      targets.push({
        ip: d.address, block: d.ovhBlock || `${d.address}/32`, source: "pool" as any, label: d.purposeLabel,
        server: d.server ? { hostname: d.server.hostname, vmid: d.server.vmid, owner: d.server.user?.email ?? null } : null,
      });
    }
    const ips: NodeAccountReading["ips"] = [];
    for (const t of targets) {
      let blocks = null;
      try {
        blocks = await readBlocks(t.block, get);
      } catch (e) {
        console.error(`[ovh-account] ${n.name} ${t.ip}: block state unreadable (${e instanceof Error ? e.message : e})`);
      }
      for (const b of blocks ?? []) if (b.blocked) console.error(`[ovh-account] ${n.name}: ${t.ip} is OVH-${b.kind}-BLOCKED since ${b.since}`);
      ips.push({ ip: t.ip, source: t.source, label: t.label, server: t.server, blocks });
    }
    readings.push({ nodeId: n.id, nodeName: n.name, serviceName: svc, ips, service });
  }
  const days = Math.max(1, Math.min(90, Math.round(await getSettingInt(OVH_RENEWAL_ALERT_DAYS_SETTING, 14))));
  const { desired, readNodeIds } = desiredOvhAccountAlerts(readings, { now: new Date(), renewalAlertDays: days });
  const ops = planFleetAlerts({
    desired,
    open: await openFleetAlerts(),
    prefixes: SWEEP_PREFIXES.ovhAccount,
    readNodeIds,
    nodeNames: new Map(nodes.map((n) => [n.id, n.name])),
    now: new Date(),
  });
  await applyFleetAlerts(ops);
}

