// Backstop for the first-month-free card/Stripe HOLD (lib/promo-redemption.ts)
// and the checkout-coupon HOLD (lib/coupon-redemption.ts): reap RESERVED
// redemptions whose payable window has lapsed. Cheap indexed deletes.
// Fleet private-IP audit (worker/ip-audit.ts): REPORT ONLY — duplicate IPs
// across VM configs and DB/VM drift, logged to ErrorLog. 2026-10-02: node-2
// had 10.20.1.101 on four VMs and nothing anywhere noticed.
add("fleet-ip-audit", 6 * h, fleetIpAuditSweep, 10 * m);
// Off-site backup freshness (worker/offsite-backup-sweep.ts): inert unless NXEON_OFFSITE_FRESHNESS=1.
add("offsite-backup-freshness", 1 * h, offsiteBackupSweep, 20 * m);
// OVH upstream firewalls (worker/ovh-game-firewall-sweep.ts): READ-ONLY (GET) check that no node/pooled IP is in
// game-firewall strict mode (2026-10-04: it silently dropped every UDP game on node-4) -> admin alert, auto-resolves.
// Default on; Setting ovh_game_firewall_check_enabled=false turns it off. Failure-silent.
add("ovh-game-firewall", 1 * h, ovhGameFirewallSweep, 6 * m);
add("promo-reservations", 2 * m, sweepExpiredReservations);
add("coupon-reservations", 2 * m, sweepExpiredCouponReservations);

// Weekly SEO audit + admin "run now" queue (self-throttled, see worker/seo-audit.ts). Fire-and-forget: a
// multi-minute audit must never hold a sweep slot.
add("seo-audit", m, async () => { void seoAuditTick(); });
// IndexNow sweep (seo-002): announces new/changed sitemap URLs to Bing & co. Default OFF (Setting indexnow_sweep_enabled).

