"use client";

/**
 * Client controls for one IP's OVH panel (/admin/ips/[address]). Every button
 * calls a server action in lib/ovh-admin/actions.ts, which re-validates,
 * re-authorises and re-reads OVH state itself; nothing here is the control.
 * After a write the panel shows OVH's before/after read-back and, for changes
 * OVH applies asynchronously, polls until OVH reports the state settled.
 */
import { useEffect, useRef, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import {
  setGameStrict, addGameRule, removeGameRule, addIpToNetworkFirewall, setNetworkFirewallEnabled, addNetworkRule, removeNetworkRule,
  setReverseDns, applyVmacFix, setPermanentMitigation, unblockIp, pollIpState,
} from "@/lib/ovh-admin/actions";

type AnyOk = { ok: true; noop?: boolean; before?: unknown; after?: unknown; message?: string } | { ok: false; error: string; needsRight?: boolean };

function ResultBox({ r }: { r: AnyOk | null }) {
  if (!r) return null;
  if (!r.ok) return <p className="mt-2 rounded-lg border border-red-500/30 bg-red-500/5 px-3 py-2 text-xs text-red-300">{r.error}</p>;
  return (
    <div className="mt-2 rounded-lg border border-emerald-500/30 bg-emerald-500/5 px-3 py-2 text-xs text-emerald-200">
      <div className="font-medium">{r.noop ? "Already in that state - nothing was sent to OVH." : r.message ?? "Done. OVH read back:"}</div>
      {"before" in r && r.before !== undefined && (
        <div className="mt-1 grid gap-1 font-mono text-[11px] text-slate-300 sm:grid-cols-2">
          <div><span className="text-slate-500">before </span>{short(r.before)}</div>
          <div><span className="text-slate-500">after </span>{short(r.after)}</div>
        </div>
      )}
    </div>
  );
}

function short(v: unknown): string {
  const s = JSON.stringify(v);
  return s && s.length > 400 ? s.slice(0, 400) + "..." : s ?? "null";
}

function useRun() {
  const [pending, start] = useTransition();
  const [result, setResult] = useState<AnyOk | null>(null);
  const router = useRouter();
  const run = (fn: () => Promise<AnyOk>, after?: () => void) =>
    start(async () => {
      const r = await fn();
      setResult(r);
      router.refresh();
      if (r.ok) after?.();
    });
  return { pending, result, run, setResult };
}

/** Polls OVH every 4 s (max 3 min) until game + network firewall states read `ok`. */
export function SettlePoller({ address, initiallyPending, onSettled }: { address: string; initiallyPending: boolean; onSettled?: () => void }) {
  const [active, setActive] = useState(initiallyPending);
  const [line, setLine] = useState<string>("");
  const started = useRef(0);
  const router = useRouter();
  useEffect(() => {
    const h = () => { setActive(true); started.current = Date.now(); };
    window.addEventListener(`ovh-settle:${address}`, h);
    return () => window.removeEventListener(`ovh-settle:${address}`, h);
  }, [address]);
  useEffect(() => {
    if (!active) return;
    if (!started.current) started.current = Date.now();
    let stop = false;
    const tick = async () => {
      if (stop) return;
      const r = await pollIpState(address);
      if (stop) return;
      if (!r.ok) { setLine(r.error); setActive(false); return; }
      setLine(`game: ${r.game ? `${r.game.enabled ? "STRICT" : "off"} / ${r.game.state}` : "-"} · network: ${r.network?.exists ? `${r.network.enabled ? "enabled" : "disabled"} / ${r.network.state}` : "-"}`);
      if (r.settled) { setActive(false); router.refresh(); onSettled?.(); return; }
      if (Date.now() - started.current > 180_000) { setLine((l) => `${l} - still pending after 3 min; reload later`); setActive(false); return; }
      setTimeout(tick, 4000);
    };
    void tick();
    return () => { stop = true; };
  }, [active, address, router, onSettled]);
  if (!active && !line) return null;
  return (
    <p className="mt-2 text-xs text-slate-400">
      {active ? <span className="mr-1 inline-block h-2 w-2 animate-pulse rounded-full bg-amber-400" /> : null}
      {active ? "Waiting for OVH to apply… " : "OVH: "}
      <span className="font-mono">{line}</span>
    </p>
  );
}

const settle = (address: string) => window.dispatchEvent(new Event(`ovh-settle:${address}`));

/** A typed-confirmation gate: the button stays disabled until the exact phrase is typed. */
function TypedConfirm({ phrase, label, danger, pending, onConfirm, extra }: { phrase: string; label: string; danger?: boolean; pending: boolean; onConfirm: () => void; extra?: React.ReactNode }) {
  const [open, setOpen] = useState(false);
  const [typed, setTyped] = useState("");
  if (!open) {
    return (
      <button type="button" className={danger ? "btn-danger text-xs" : "btn-secondary text-xs"} disabled={pending} onClick={() => setOpen(true)}>
        {label}
      </button>
    );
  }
  return (
    <div className="mt-2 w-full rounded-lg border border-white/10 bg-black/20 p-3">
      {extra}
      <label className="label">Type <span className="font-mono text-slate-200">{phrase}</span> to confirm</label>
      <div className="flex flex-wrap gap-2">
        <input className="input w-56 py-1 font-mono text-xs" value={typed} onChange={(e) => setTyped(e.target.value)} autoComplete="off" spellCheck={false} />
        <button type="button" className={danger ? "btn-danger text-xs" : "btn-primary text-xs"} disabled={pending || typed.trim() !== phrase} onClick={() => { onConfirm(); setTyped(""); setOpen(false); }}>
          {pending ? "Working…" : label}
        </button>
        <button type="button" className="text-xs text-slate-500 hover:text-slate-300" onClick={() => { setOpen(false); setTyped(""); }}>
          Cancel
        </button>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// 1. Game firewall
// ---------------------------------------------------------------------------

export function GameFirewallControls({
  address, exists, strict, state, rules, supportedProtocols, canWrite,
}: {
  address: string; exists: boolean; strict: boolean | null; state: string | null;
  rules: { id: string; label: string }[]; supportedProtocols: string[]; canWrite: boolean;
}) {
  const { pending, result, run } = useRun();
  const [proto, setProto] = useState(supportedProtocols.includes("other") ? "other" : supportedProtocols[0] ?? "other");
  const [ports, setPorts] = useState("");
  if (!exists) return <p className="text-sm text-slate-500">OVH has no game firewall object for this IP (not a game-eligible server), so nothing is enforced.</p>;
  return (
    <div>
      <div className="flex flex-wrap items-center gap-3">
        {canWrite && (
          <TypedConfirm
            phrase={address}
            danger={!strict}
            label={strict ? "Turn strict mode OFF" : "Turn strict mode ON"}
            pending={pending}
            extra={
              <p className="mb-2 text-xs text-amber-200">
                {strict
                  ? "OFF: OVH stops dropping UDP that no rule allows. Takes ~1 minute (firewallModeDisablePending -> ok)."
                  : `ON: OVH will DROP every UDP port not in the ${rules.length} rule(s) below, at its edge. Every UDP game on this IP that is not listed goes dark.`}
              </p>
            }
            onConfirm={() => run(() => setGameStrict(address, !strict, address), () => settle(address))}
          />
        )}
      </div>
      <SettlePoller address={address} initiallyPending={!!state && state !== "ok"} />
      <table className="table-shell mt-3">
        <thead><tr><th>Rule</th><th>Id</th><th /></tr></thead>
        <tbody>
          {rules.length === 0 && <tr><td colSpan={3} className="py-3 text-center text-xs text-slate-500">No allow rules.</td></tr>}
          {rules.map((r) => (
            <tr key={r.id}>
              <td className="font-mono text-xs">{r.label}</td>
              <td className="font-mono text-xs text-slate-500">{r.id}</td>
              <td className="text-right">
                {canWrite && (
                  <button className="text-xs text-red-400 hover:text-red-300" disabled={pending} onClick={() => run(() => removeGameRule(address, r.id), () => settle(address))}>
                    Remove
                  </button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      {canWrite && (
        <form
          className="mt-3 flex flex-wrap items-end gap-2"
          onSubmit={(e) => { e.preventDefault(); run(() => addGameRule(address, proto, ports), () => { setPorts(""); settle(address); }); }}
        >
          <div>
            <label className="label">Protocol</label>
            <select className="input py-1 text-xs" value={proto} onChange={(e) => setProto(e.target.value)}>
              {supportedProtocols.map((p) => <option key={p} value={p}>{p}</option>)}
            </select>
          </div>
          <div>
            <label className="label">Port or range</label>
            <input className="input w-36 py-1 font-mono text-xs" placeholder="27015-27030" value={ports} onChange={(e) => setPorts(e.target.value)} />
          </div>
          <button className="btn-secondary text-xs" disabled={pending || !ports.trim()}>Add allow rule</button>
        </form>
      )}
      <ResultBox r={result} />
    </div>
  );
}

// ---------------------------------------------------------------------------
// 2. Network firewall
// ---------------------------------------------------------------------------

export function NetworkFirewallControls({
  address, exists, enabled, rules, canWrite,
}: {
  address: string; exists: boolean; enabled: boolean | null;
  rules: { sequence: string; label: string }[]; canWrite: boolean;
}) {
  const { pending, result, run } = useRun();
  const [f, setF] = useState({ sequence: "", action: "permit", protocol: "tcp", ports: "", source: "" });
  const used = new Set(rules.map((r) => r.sequence));
  const freeSeq = Array.from({ length: 20 }, (_, i) => String(i)).find((s) => !used.has(s)) ?? "";
  if (!exists) {
    return (
      <div>
        <p className="text-sm text-slate-500">This IP is not on OVH&apos;s network firewall (nothing filtered).</p>
        {canWrite && (
          <button className="btn-secondary mt-2 text-xs" disabled={pending} onClick={() => run(() => addIpToNetworkFirewall(address))}>
            Add IP to network firewall (stays disabled)
          </button>
        )}
        <ResultBox r={result} />
      </div>
    );
  }
  return (
    <div>
      {canWrite && (
        <TypedConfirm
          phrase={address}
          danger={!enabled}
          label={enabled ? "Disable network firewall" : "Enable network firewall"}
          pending={pending}
          extra={
            <p className="mb-2 text-xs text-amber-200">
              {enabled
                ? "Disabling stops OVH filtering this IP with the rules below."
                : `Enabling applies the ${rules.length} rule(s) below at OVH's edge, top (0) to bottom (19). Anything a rule denies never reaches the VM - make sure SSH, game and web ports are permitted first.`}
            </p>
          }
          onConfirm={() => run(() => setNetworkFirewallEnabled(address, !enabled, address), () => settle(address))}
        />
      )}
      <SettlePoller address={address} initiallyPending={false} />
      <table className="table-shell mt-3">
        <thead><tr><th>Seq</th><th>Rule</th><th /></tr></thead>
        <tbody>
          {rules.length === 0 && <tr><td colSpan={3} className="py-3 text-center text-xs text-slate-500">No rules.</td></tr>}
          {rules.map((r) => (
            <tr key={r.sequence}>
              <td className="font-mono text-xs">{r.sequence}</td>
              <td className="font-mono text-xs">{r.label}</td>
              <td className="text-right">
                {canWrite && (
                  <button className="text-xs text-red-400 hover:text-red-300" disabled={pending} onClick={() => run(() => removeNetworkRule(address, r.sequence), () => settle(address))}>
                    Remove
                  </button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      {canWrite && (
        <form className="mt-3 flex flex-wrap items-end gap-2" onSubmit={(e) => { e.preventDefault(); run(() => addNetworkRule(address, { ...f, sequence: f.sequence || freeSeq }), () => settle(address)); }}>
          <div>
            <label className="label">Seq</label>
            <input className="input w-14 py-1 font-mono text-xs" placeholder={freeSeq} value={f.sequence} onChange={(e) => setF({ ...f, sequence: e.target.value })} />
          </div>
          <div>
            <label className="label">Action</label>
            <select className="input py-1 text-xs" value={f.action} onChange={(e) => setF({ ...f, action: e.target.value })}>
              <option value="permit">permit</option>
              <option value="deny">deny</option>
            </select>
          </div>
          <div>
            <label className="label">Protocol</label>
            <select className="input py-1 text-xs" value={f.protocol} onChange={(e) => setF({ ...f, protocol: e.target.value })}>
              {["tcp", "udp", "icmp", "ipv4", "gre", "esp", "ah"].map((p) => <option key={p}>{p}</option>)}
            </select>
          </div>
          <div>
            <label className="label">Dest. ports</label>
            <input className="input w-32 py-1 font-mono text-xs" placeholder="any / 22 / 27015-27030" value={f.ports} disabled={f.protocol !== "tcp" && f.protocol !== "udp"} onChange={(e) => setF({ ...f, ports: e.target.value })} />
          </div>
          <div>
            <label className="label">Source</label>
            <input className="input w-40 py-1 font-mono text-xs" placeholder="any / 203.0.113.0/24" value={f.source} onChange={(e) => setF({ ...f, source: e.target.value })} />
          </div>
          <button className="btn-secondary text-xs" disabled={pending}>Add rule</button>
        </form>
      )}
      <ResultBox r={result} />
    </div>
  );
}

// ---------------------------------------------------------------------------
// 3. Reverse DNS
// ---------------------------------------------------------------------------

export function ReverseDnsForm({ address, current, canWrite }: { address: string; current: string | null; canWrite: boolean }) {
  const { pending, result, run } = useRun();
  const [v, setV] = useState(current ?? "");
  return (
    <div>
      <p className="text-sm">Current PTR: <span className="font-mono text-xs">{current ?? "— (OVH default)"}</span></p>
      {canWrite && (
