// ---------------------------------------------------------------------------
// 5. Permanent mitigation
// ---------------------------------------------------------------------------

export function MitigationToggle({ address, permanent, canWrite }: { address: string; permanent: boolean; canWrite: boolean }) {
  const { pending, result, run } = useRun();
  if (!canWrite) return null;
  return (
    <div className="mt-2">
      <TypedConfirm
        phrase={address}
        label={permanent ? "Turn permanent mitigation OFF" : "Turn permanent mitigation ON"}
        pending={pending}
        extra={<p className="mb-2 text-xs text-slate-400">Permanent mitigation sends all traffic through OVH&apos;s scrubbing even with no attack; it can add latency and break some UDP games. Auto-mitigation stays on regardless.</p>}
        onConfirm={() => run(() => setPermanentMitigation(address, !permanent, address))}
      />
      <ResultBox r={result} />
