}

// ---------------------------------------------------------------------------
// 6. Unblock
// ---------------------------------------------------------------------------

export function UnblockForm({ address, kind, canWrite, serverHint }: { address: string; kind: string; canWrite: boolean; serverHint: string | null }) {
  const { pending, result, run } = useRun();
  const [reason, setReason] = useState("");
  if (!canWrite) return null;
  return (
    <div className="mt-2">
      <label className="label">What did you check? (recorded in the audit log)</label>
      <input className="input w-full py-1 text-xs" value={reason} onChange={(e) => setReason(e.target.value)} placeholder={`e.g. inspected ${serverHint ?? "the VM"}: removed miner, rotated nothing, outbound SSH stopped`} />
      <TypedConfirm
        phrase={address}
        danger
        label={`Request ${kind} unblock`}
        pending={pending || reason.trim().length < 10}
        extra={<p className="mb-2 text-xs text-amber-200">A blocked customer IP usually means a compromised VM. OVH re-blocks repeat offenders for longer; only unblock once the cause is gone.</p>}
        onConfirm={() => run(() => unblockIp(address, kind, address, reason))}
      />
