"use client";

/**
 * Node-level OVH controls: IP pool re-import and the owner-only reboot / rescue
 * controls. Reboot/rescue is a TWO-STEP server flow (preparePowerAction ->
 * executePowerAction): step 1 renders a fresh warning listing every customer VM
 * on the node and issues a single-use 5-minute token; step 2 needs that token,
 * the node name typed exactly and the affected-VM count. A stale page, a
 * reused token or a VM list that changed in between is refused server-side.
 */
import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { syncNodeIpPool, preparePowerAction, executePowerAction, type PowerWarning } from "@/lib/ovh-admin/actions";

export function SyncNodePoolButton({ nodeId }: { nodeId: string }) {
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);
  const router = useRouter();
  return (
    <div>
      <button
        className="btn-secondary text-xs"
        disabled={pending}
        onClick={() =>
          start(async () => {
            const r = await syncNodeIpPool(nodeId);
            setMsg(r.ok ? `Pool: ${r.before} -> ${r.total} IP(s) (${r.imported} imported).` : r.error);
            router.refresh();
          })
        }
      >
        {pending ? "Re-importing…" : "Re-import IPs from OVH"}
      </button>
      {msg && <p className="mt-1 text-xs text-slate-400">{msg}</p>}
    </div>
  );
}

const ACTIONS: { key: string; label: string }[] = [
  { key: "reboot", label: "Hard reboot" },
  { key: "rescue_on_reboot", label: "Boot into rescue" },
  { key: "rescue_off_reboot", label: "Boot back to disk" },
  { key: "rescue_on", label: "Netboot -> rescue only" },
  { key: "rescue_off", label: "Netboot -> disk only" },
];

export function PowerControls({ nodeId, canReboot, canNetboot, isOwner, ownerReason }: { nodeId: string; canReboot: boolean; canNetboot: boolean; isOwner: boolean; ownerReason: string | null }) {
  const [pending, start] = useTransition();
  const [warning, setWarning] = useState<PowerWarning | null>(null);
  const [typed, setTyped] = useState("");
  const [ack, setAck] = useState("");
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const router = useRouter();

  if (!isOwner) return <p className="text-xs text-slate-500">Reboot / rescue are owner-only. {ownerReason}</p>;

  const prepare = (action: string) =>
    start(async () => {
      setMsg(null);
      setTyped("");
      setAck("");
      const r = await preparePowerAction(nodeId, action);
      if (r.ok) setWarning(r.warning);
      else setMsg({ ok: false, text: r.error });
    });

  const execute = () =>
    start(async () => {
      if (!warning) return;
      const r = await executePowerAction(warning.token, typed, Number(ack));
      setWarning(null);
      setMsg(r.ok ? { ok: true, text: r.message } : { ok: false, text: r.error });
      router.refresh();
    });

  return (
    <div>
      {!warning && (
        <div className="flex flex-wrap gap-2">
          {ACTIONS.map((a) => {
            const needs = a.key === "reboot" ? canReboot : a.key.endsWith("_reboot") ? canReboot && canNetboot : canNetboot;
            return (
              <button key={a.key} className="btn-danger text-xs" disabled={pending || !needs} title={needs ? "" : "Missing OVH API right"} onClick={() => prepare(a.key)}>
                {a.label}…
              </button>
            );
          })}
        </div>
      )}
      {warning && (
        <div className="rounded-lg border border-red-500/40 bg-red-500/5 p-4">
          <div className="text-sm font-semibold text-red-300">{warning.actionLabel}: {warning.nodeName}</div>
          <p className="mt-1 text-xs text-slate-300">
            OVH service <span className="font-mono">{warning.serviceName}</span>, currently booting from {warning.currentBoot}.{" "}
            {warning.reboots
              ? "This power-cycles the whole physical server: EVERY VM below goes down hard (no clean shutdown) and is unreachable until the node is back (several minutes; longer in rescue, where VMs do not run at all)."
              : "This only changes what the server boots next time; nothing goes down now. The next reboot (by anyone) will use it."}
          </p>
          <div className="mt-3 max-h-64 overflow-y-auto rounded border border-white/10">
            <table className="table-shell">
              <thead><tr><th>VM</th><th>Owner</th><th>IP</th><th>Status</th></tr></thead>
              <tbody>
                {warning.vms.length === 0 && <tr><td colSpan={4} className="py-3 text-center text-xs text-slate-500">No customer VMs on this node.</td></tr>}
                {warning.vms.map((v) => (
                  <tr key={`${v.vmid}-${v.hostname}`}>
                    <td className="text-xs"><span className="font-medium">{v.hostname}</span> <span className="text-slate-500">VM {v.vmid ?? "?"}</span></td>
                    <td className="text-xs text-slate-400">{v.owner ?? "—"}</td>
                    <td className="font-mono text-xs">{v.ip ?? "—"}</td>
                    <td className="text-xs">{v.status.toLowerCase()}</td>
                  </tr>
                ))}
                {warning.internal.map((i) => (
                  <tr key={i.address}>
                    <td className="text-xs"><span className="font-medium">{i.label}</span> <span className="text-slate-500">internal</span></td>
                    <td className="text-xs text-slate-400">Nxeon</td>
                    <td className="font-mono text-xs">{i.address}</td>
                    <td className="text-xs">—</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="mt-3 grid gap-3 sm:grid-cols-2">
            <div>
              <label className="label">Type the node name <span className="font-mono text-slate-200">{warning.nodeName}</span></label>
              <input className="input w-full py-1 font-mono text-xs" value={typed} onChange={(e) => setTyped(e.target.value)} autoComplete="off" spellCheck={false} />
            </div>
            <div>
              <label className="label">How many customer VMs are affected?</label>
              <input className="input w-full py-1 font-mono text-xs" inputMode="numeric" value={ack} onChange={(e) => setAck(e.target.value)} autoComplete="off" />
            </div>
          </div>
          <p className="mt-2 text-[11px] text-slate-500">This confirmation is single-use and expires at {new Date(warning.expiresAt).toLocaleTimeString()}. If any VM is added or removed before you confirm, it is refused.</p>
          <div className="mt-3 flex gap-2">
            <button className="btn-danger text-xs" disabled={pending || typed.trim() !== warning.nodeName || ack.trim() === ""} onClick={execute}>
              {pending ? "Sending…" : `Confirm: ${warning.actionLabel}`}
            </button>
            <button className="btn-secondary text-xs" disabled={pending} onClick={() => setWarning(null)}>Cancel</button>
          </div>
        </div>
      )}
      {msg && <p className={`mt-2 text-xs ${msg.ok ? "text-emerald-300" : "text-red-300"}`}>{msg.text}</p>}
    </div>
  );
}

