        {!rights.rulesRead && <LevelBadge level="WARN">could not read the key&apos;s access rules</LevelBadge>}
        <span className="ml-auto text-xs text-slate-500">read {new Date(p.readAt).toLocaleTimeString()}</span>
      </div>
      <NeedsRight missing={r.read.missing} />

      <div className="grid gap-4 xl:grid-cols-3">
        <OvhSection title="Server" sub="GET /dedicated/server/{name}">
          <ReadError error={p.errors.server} />
          {p.server && (
            <div className="space-y-1.5">
              <Fact k="State" v={<LevelBadge level={p.server.state === "ok" ? "PASS" : "WARN"}>{p.server.state ?? "?"}</LevelBadge>} />
              <Fact k="Power" v={p.server.powerState} />
              <Fact k="Boot" v={<LevelBadge level={p.bootMode === "disk" ? "PASS" : p.bootMode === "rescue" ? "FAIL" : "WARN"}>{p.bootMode === "rescue" ? "RESCUE netboot" : p.bootMode}</LevelBadge>} />
              <Fact k="Datacenter" v={`${p.server.datacenter ?? "?"} · ${p.server.region ?? "?"}`} />
              <Fact k="Range" v={p.server.commercialRange} />
              <Fact k="OVH monitoring" v={p.server.monitoring ? "on" : "off"} />
              <Fact k="Support level" v={p.server.supportLevel} />
            </div>
          )}
        </OvhSection>

        <OvhSection title="Service & renewal" sub="GET .../serviceInfos">
          <ReadError error={p.errors.service} />
          {p.service && p.renewal && (
            <div className="space-y-1.5">
              <Fact k="Expires" v={<>{p.service.expiration} <span className="text-slate-500">({p.renewal.daysLeft ?? "?"} d)</span></>} />
              <Fact k="Auto-renew" v={<LevelBadge level={p.service.autoRenew ? "PASS" : "FAIL"}>{p.service.autoRenew ? "on" : "OFF"}</LevelBadge>} />
              <Fact k="Delete at expiration" v={p.service.deleteAtExpiration ? "YES" : "no"} />
              <Fact k="Period" v={p.service.renewPeriodMonths ? `${p.service.renewPeriodMonths} month(s)` : null} />
              <Fact k="Engagement" v={p.service.engagedUpTo ?? "none"} />
              <Fact k="Created" v={p.service.creation} />
              <p className="pt-1 text-xs"><LevelBadge level={p.renewal.level} /> <span className="text-slate-400">{p.renewal.summary}</span></p>
              <p className="text-[11px] text-slate-500">An admin alert fires {days} days before expiry when auto-renew is off (Setting {OVH_RENEWAL_ALERT_DAYS_SETTING}).</p>
            </div>
          )}
        </OvhSection>

        <OvhSection title="Traffic" sub="GET .../specifications/network">
          <ReadError error={p.errors.traffic} />
          {p.traffic && (
            <div className="space-y-1.5">
              {p.traffic.unmetered ? (
                <Fact k="Quota" v="unmetered (no quota)" />
              ) : (
                <>
                  <Fact k="Out (used / quota)" v={`${fmtTB(p.traffic.outUsed)} / ${fmtTB(p.traffic.outQuota)}`} />
                  <Fact k="In (used / quota)" v={`${fmtTB(p.traffic.inUsed)} / ${fmtTB(p.traffic.inQuota)}`} />
                  <Fact k="Quota resets" v={p.traffic.resetDate} />
                </>
              )}
              <Fact k="Throttled" v={p.traffic.throttled ? "YES" : "no"} />
              <Fact k="Bandwidth" v={`${p.traffic.bandwidthMbps.ovhToInternet ?? "?"} Mbps out · ${p.traffic.bandwidthMbps.internetToOvh ?? "?"} in (${p.traffic.bandwidthMbps.type ?? "?"})`} />
              <Fact k="vMAC quota" v={p.traffic.vmacQuota} />
              {p.trafficVerdict && <p className="pt-1 text-xs"><LevelBadge level={p.trafficVerdict.level} /> <span className="text-slate-400">{p.trafficVerdict.summary}</span></p>}
            </div>
          )}
        </OvhSection>
      </div>

      <OvhSection title="IPs routed to this node" sub="GET /ip/{block}: type, zone, routing. A zone mismatch means the IP cannot work here (2026-08-26 lesson)." right={<SyncNodePoolButton nodeId={node.id} />}>
        <div className="overflow-x-auto">
          <table className="table-shell">
            <thead><tr><th>IP</th><th>Use</th><th>Type</th><th>Campus / region</th><th>Routed to</th><th>Zone check</th></tr></thead>
            <tbody>
              {p.ips.map((i) => (
                <tr key={i.address}>
                  <td className="font-mono text-xs"><Link href={`/admin/ips/${i.address}`} className="hover:text-brand-300">{i.address}</Link></td>
                  <td className="text-xs text-slate-400">{i.source === "node" ? "node public IP" : `${(i.poolStatus ?? "").toLowerCase()}${i.label ? ` · ${i.label}` : ""}`}</td>
                  <td className="text-xs">{i.facts?.type ?? "—"}</td>
                  <td className="text-xs">{i.facts ? `${i.facts.campus ?? "?"} · ${i.facts.regions.join(", ")}` : "—"}</td>
                  <td className="font-mono text-[11px] text-slate-400">{i.facts?.routedTo ?? "—"}</td>
                  <td className="text-xs">{i.error ? <span className="text-red-300">{i.error}</span> : i.zone ? <span title={i.zone.summary}><LevelBadge level={i.zone.level}>{i.zone.level === "PASS" ? "ok" : i.zone.summary}</LevelBadge></span> : "—"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </OvhSection>

      <div className="grid gap-4 xl:grid-cols-2">
        <OvhSection title="Recent OVH tasks" sub="GET .../task">
          <ReadError error={p.errors.tasks} />
          <table className="table-shell">
            <thead><tr><th>Task</th><th>Function</th><th>Status</th><th>Started</th></tr></thead>
            <tbody>
              {(p.tasks ?? []).length === 0 && <tr><td colSpan={4} className="py-3 text-center text-xs text-slate-500">None.</td></tr>}
              {(p.tasks ?? []).map((t) => (
                <tr key={t.id}>
                  <td className="font-mono text-xs">{t.id}</td>
                  <td className="text-xs">{t.fn}</td>
                  <td className="text-xs"><LevelBadge level={t.status === "done" ? "PASS" : t.status === "ovhError" || t.status === "customerError" ? "FAIL" : "WARN"}>{t.status}</LevelBadge></td>
                  <td className="text-xs text-slate-400">{t.start?.slice(0, 16).replace("T", " ")}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </OvhSection>
        <OvhSection title="Interventions" sub="GET .../intervention (OVH datacenter work on this server)">
          <ReadError error={p.errors.interventions} />
          <table className="table-shell">
            <thead><tr><th>Id</th><th>Type</th><th>Date</th></tr></thead>
            <tbody>
              {(p.interventions ?? []).length === 0 && <tr><td colSpan={3} className="py-3 text-center text-xs text-slate-500">None.</td></tr>}
              {(p.interventions ?? []).map((i) => (
                <tr key={i.id}><td className="font-mono text-xs">{i.id}</td><td className="text-xs">{i.type}</td><td className="text-xs text-slate-400">{i.date?.slice(0, 16).replace("T", " ")}</td></tr>
              ))}
            </tbody>
          </table>
        </OvhSection>
      </div>

      <OvhSection title="Reboot & rescue (owner only)" sub="Most dangerous controls on this page: they take every VM on the node down. Two-step, typed confirmation, single-use token, refused if the VM list changed.">
        <ReadError error={p.errors.boots} />
        <p className="mb-2 text-xs text-slate-400">
          Boot options: {(p.boots ?? []).map((b) => `${b.type} #${b.id}${b.description ? ` (${b.description})` : ""}`).join(" · ") || "—"}
        </p>
        <NeedsRight missing={[...r.reboot.missing, ...r.netboot.missing]} />
        <PowerControls nodeId={node.id} canReboot={r.reboot.allowed} canNetboot={r.netboot.allowed && p.rescueBootId !== null} isOwner={owner.ok} ownerReason={owner.ok ? null : owner.error} />
      </OvhSection>
    </div>
  );
}

