import Link from "next/link";
import { notFound } from "next/navigation";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge } from "@/components/ui/primitives";
import { REGION_LABELS } from "@/lib/node-regions";
import { resolveOvhIp, readServerVmMacs } from "@/lib/ovh-admin/targets";
import { readIpPanel, readRights, readVmacPanel } from "@/lib/ovh-admin/read";
import { ovhAdminConfigured, OVH_ADMIN_STUB } from "@/lib/ovh-admin/transport";
import { describeGameRule } from "@/lib/ovh-game-firewall";
import { BLOCK_REASON } from "@/lib/ovh-admin/parse";
import { LevelBadge, OvhSection, NeedsRight, ReadError, Fact } from "@/components/admin/ovh/OvhBits";
import {
  GameFirewallControls, NetworkFirewallControls, ReverseDnsForm, VmacRepair, MitigationToggle, UnblockForm,
} from "@/components/admin/ovh/IpOvhControls";

export const dynamic = "force-dynamic";

/** OVH detail panel for one IP the platform owns (pool row or an OVH node's public IP). */
export default async function AdminIpDetail({ params }: { params: Promise<{ address: string }> }) {
  const admin = await requireArea("fleet");
  const { address } = await params;
  const target = await resolveOvhIp(decodeURIComponent(address));
  if (!target) notFound();
  if (!ovhAdminConfigured()) {
    return (
      <div className="space-y-6">
        <PageHeader title={target.address} sub="OVH API is not configured." />
      </div>
    );
  }
  const canAdmin = admin.role === "ADMIN";
  const serverId = target.pool?.server?.id;
  const [rv, p, vm] = await Promise.all([
    readRights(),
    readIpPanel(target),
    readVmacPanel(target, serverId ? () => readServerVmMacs(serverId) : null),
  ]);
  const r = rv.rights;
  const can = (k: keyof typeof r) => canAdmin && r[k].allowed;
  const blocked = (p.blocks ?? []).filter((b) => b.blocked);

  return (
    <div className="space-y-6">
      <PageHeader
        title={target.address}
        sub={`OVH ${target.source === "node" ? "node public IP" : "pooled IP"} · ${target.node.name} · ${REGION_LABELS[target.node.region] ?? target.node.region} · block ${target.block}`}
      >
        <Link href="/admin/ips" className="btn-secondary">Back to IP pool</Link>
        <Link href={`/admin/nodes/${target.node.id}#ovh`} className="btn-secondary">Node OVH panel</Link>
      </PageHeader>

      <div className="flex flex-wrap items-center gap-2">
        {OVH_ADMIN_STUB && <LevelBadge level="WARN">STUB DATA (dev)</LevelBadge>}
        {target.pool ? <Badge tone="brand">{target.pool.status.toLowerCase()}</Badge> : <Badge tone="slate">node IP</Badge>}
        {target.pool?.purpose === "INTERNAL" && <Badge tone="amber">internal · {target.pool.purposeLabel}</Badge>}
        {target.pool?.server && (
          <Link href={`/admin/servers/${target.pool.server.id}`} className="text-sm hover:text-brand-300">
            {target.pool.server.hostname} <span className="text-slate-500">({target.pool.server.userEmail})</span>
          </Link>
        )}
        {blocked.length > 0 && <LevelBadge level="FAIL">BLOCKED BY OVH ({blocked.map((b) => b.kind).join(", ")})</LevelBadge>}
        {p.mitigation?.auto && <LevelBadge level="FAIL">UNDER ATTACK (auto-mitigation)</LevelBadge>}
        {p.game?.firewallModeEnabled && <LevelBadge level="FAIL">game firewall STRICT</LevelBadge>}
        {p.zone && p.zone.level !== "PASS" && <LevelBadge level={p.zone.level}>zone mismatch</LevelBadge>}
        <span className="ml-auto text-xs text-slate-500">read {new Date(p.readAt).toLocaleTimeString()}</span>
      </div>
      {!canAdmin && <p className="text-xs text-slate-500">Read-only: changes need an ADMIN account.</p>}
      <NeedsRight missing={r.read.missing} />

      {blocked.length > 0 && (
        <OvhSection title="OVH block" sub="GET /ip/{block}/antihack | spam | arp">
          {blocked.map((b) => (
            <div key={b.kind} className="mb-3 rounded-lg border border-red-500/40 bg-red-500/5 p-3">
              <div className="text-sm font-semibold text-red-300">{b.kind} block · state {b.state} · since {b.since ?? "?"}{b.timeSec !== null ? ` · ${b.timeSec}s` : ""}</div>
              <p className="mt-1 text-xs text-slate-300">{BLOCK_REASON[b.kind]}</p>
              {b.logs && <pre className="mt-2 max-h-40 overflow-auto whitespace-pre-wrap rounded bg-black/30 p-2 text-[11px] text-slate-300">{b.logs}</pre>}
              <NeedsRight missing={r.unblock.missing} />
              <UnblockForm address={target.address} kind={b.kind} canWrite={can("unblock")} serverHint={target.pool?.server?.hostname ?? null} />
            </div>
          ))}
        </OvhSection>
      )}

      <div className="grid gap-4 xl:grid-cols-2">
        <OvhSection title="IP facts" sub="GET /ip/{block}">
          <ReadError error={p.errors.facts} />
          {p.facts && (
            <div className="space-y-1.5">
              <Fact k="Type" v={p.facts.type} />
              <Fact k="Routed to" v={p.facts.routedTo} mono />
              <Fact k="Campus" v={p.facts.campus} />
              <Fact k="Regions" v={p.facts.regions.join(", ")} />
              <Fact k="Country" v={p.facts.country} />
              <Fact k="Block" v={p.facts.block} mono />
              <Fact k="RIR" v={p.facts.rir} />
              <Fact k="Description" v={p.facts.description} />
              {p.zone && <p className="pt-1 text-xs"><LevelBadge level={p.zone.level} /> <span className="text-slate-400">{p.zone.summary}</span></p>}
            </div>
          )}
        </OvhSection>

        <OvhSection title="DDoS mitigation" sub="GET /ip/{block}/mitigation. OVH's API no longer exposes attack history or traffic stats; 'auto' = an attack is being scrubbed now.">
          <ReadError error={p.errors.mitigation} />
          {p.mitigation && (
            <div className="space-y-1.5">
              <Fact k="Permanent mitigation" v={p.mitigation.permanent ? "ON" : "off"} />
              <Fact k="Auto-mitigation active" v={p.mitigation.auto ? "YES (attack in progress)" : "no"} />
              <Fact k="State" v={p.mitigation.state ?? "—"} />
              <p className="pt-1 text-xs"><LevelBadge level={p.mitigation.verdict.level} /> <span className="text-slate-400">{p.mitigation.verdict.summary}</span></p>
              <NeedsRight missing={r.mitigation.missing} />
              <MitigationToggle address={target.address} permanent={!!p.mitigation.permanent} canWrite={can("mitigation")} />
            </div>
          )}
        </OvhSection>
      </div>

      <OvhSection
        title="Game firewall"
        sub="GET /ip/{block}/game/{ip}. STRICT mode drops every UDP port not allowed below, at OVH's edge (2026-10-04 node-4 outage)."
        right={p.game && <LevelBadge level={p.game.verdict.level}>{p.game.exists ? (p.game.firewallModeEnabled ? "STRICT" : "off") : "none"} · {p.game.state ?? "-"}</LevelBadge>}
      >
        <ReadError error={p.errors.game} />
        {p.game && (
          <>
            <p className="mb-2 text-xs text-slate-400">{p.game.verdict.summary}{p.game.maxRules ? ` (max ${p.game.maxRules} rules)` : ""}</p>
            <NeedsRight missing={r.gameFirewall.missing} />
            <GameFirewallControls
              address={target.address}
              exists={p.game.exists}
              strict={p.game.firewallModeEnabled}
              state={p.game.state}
              rules={p.game.rules.map((x) => ({ id: String(x.id), label: `${describeGameRule(x)}${x.state && x.state !== "ok" ? ` [${x.state}]` : ""}` }))}
              supportedProtocols={p.game.supportedProtocols}
              canWrite={can("gameFirewall")}
            />
          </>
        )}
      </OvhSection>

      <OvhSection
        title="Network firewall"
        sub="GET /ip/{block}/firewall. Up to 20 ordered permit/deny rules applied at OVH's edge when enabled."
        right={p.network && <LevelBadge level={p.network.verdict.level}>{p.network.exists ? (p.network.enabled ? "ENABLED" : "disabled") : "not added"}</LevelBadge>}
      >
        <ReadError error={p.errors.network} />
        {p.network && (
          <>
            <NeedsRight missing={r.networkFirewall.missing} />
            <NetworkFirewallControls
              address={target.address}
              exists={p.network.exists}
              enabled={p.network.enabled}
              rules={p.network.rules.map((x) => ({ sequence: String(x.sequence ?? x.id), label: `${x.action} ${x.protocol}${x.destinationPort ? ` port ${x.destinationPort}` : ""} from ${x.source ?? "any"}${x.state && x.state !== "ok" ? ` [${x.state}]` : ""}` }))}
              canWrite={can("networkFirewall")}
            />
          </>
        )}
      </OvhSection>

      <div className="grid gap-4 xl:grid-cols-2">
        <OvhSection title="Reverse DNS" sub="GET/POST /ip/{block}/reverse">
          <ReadError error={p.errors.reverse} />
          <NeedsRight missing={r.reverseDns.missing} />
          <ReverseDnsForm address={target.address} current={p.reverse} canWrite={can("reverseDns")} />
        </OvhSection>

        <OvhSection title="Virtual MAC" sub="OVH only forwards an additional IP's traffic from its registered vMAC; it must match the VM's NIC.">
          <ReadError error={vm.error} />
          <div className="space-y-1.5">
            <Fact k="Pool row vMAC" v={target.pool?.virtualMac ?? "—"} mono />
            <Fact k="OVH vMAC for this IP" v={vm.diagnosis.ovhMac ?? "—"} mono />
            <Fact k="VM NIC MAC(s)" v={vm.diagnosis.vmMacs.join(", ") || "—"} mono />
          </div>
          <p className="mt-2 text-xs">
            <LevelBadge level={vm.diagnosis.status === "ok" || vm.diagnosis.status === "not_applicable" ? "PASS" : vm.diagnosis.status === "unknown_vm" ? "WARN" : "FAIL"}>{vm.diagnosis.status}</LevelBadge>{" "}
            <span className="text-slate-400">{vm.diagnosis.explanation}</span>
          </p>
          <NeedsRight missing={vm.diagnosis.fixes.some((f) => f.fix !== "fix_db") ? r.virtualMac.missing : []} />
          <VmacRepair address={target.address} fixes={vm.diagnosis.fixes} canWrite={canAdmin && (r.virtualMac.allowed || vm.diagnosis.fixes.every((f) => f.fix === "fix_db"))} />
        </OvhSection>
      </div>
    </div>
  );
}

