  if (!ovhAdminConfigured()) {
    return (
      <div className="space-y-6">
        <PageHeader title={target.address} sub="OVH API is not configured." />
      </div>
    );
  }
  const canAdmin = admin.role === "ADMIN";
  const serverId = target.pool?.server?.id;
  const [rv, p, vm] = await Promise.all([
    readRights(),
    readIpPanel(target),
    readVmacPanel(target, serverId ? () => readServerVmMacs(serverId) : null),
  ]);
  const r = rv.rights;
  const can = (k: keyof typeof r) => canAdmin && r[k].allowed;
  const blocked = (p.blocks ?? []).filter((b) => b.blocked);

  return (
