      <PageHeader
        title={target.address}
        sub={`OVH ${target.source === "node" ? "node public IP" : "pooled IP"} · ${target.node.name} · ${REGION_LABELS[target.node.region] ?? target.node.region} · block ${target.block}`}
      >
        <Link href="/admin/ips" className="btn-secondary">Back to IP pool</Link>
        <Link href={`/admin/nodes/${target.node.id}#ovh`} className="btn-secondary">Node OVH panel</Link>
      </PageHeader>

      <div className="flex flex-wrap items-center gap-2">
