      <div className="grid gap-4 xl:grid-cols-2">
        <OvhSection title="IP facts" sub="GET /ip/{block}">
          <ReadError error={p.errors.facts} />
          {p.facts && (
            <div className="space-y-1.5">
              <Fact k="Type" v={p.facts.type} />
              <Fact k="Routed to" v={p.facts.routedTo} mono />
