              <Fact k="RIR" v={p.facts.rir} />
              <Fact k="Description" v={p.facts.description} />
              {p.zone && <p className="pt-1 text-xs"><LevelBadge level={p.zone.level} /> <span className="text-slate-400">{p.zone.summary}</span></p>}
            </div>
          )}
        </OvhSection>

        <OvhSection title="DDoS mitigation" sub="GET /ip/{block}/mitigation. OVH's API no longer exposes attack history or traffic stats; 'auto' = an attack is being scrubbed now.">
          <ReadError error={p.errors.mitigation} />
          {p.mitigation && (
            <div className="space-y-1.5">
              <Fact k="Permanent mitigation" v={p.mitigation.permanent ? "ON" : "off"} />
              <Fact k="Auto-mitigation active" v={p.mitigation.auto ? "YES (attack in progress)" : "no"} />
              <Fact k="State" v={p.mitigation.state ?? "—"} />
              <p className="pt-1 text-xs"><LevelBadge level={p.mitigation.verdict.level} /> <span className="text-slate-400">{p.mitigation.verdict.summary}</span></p>
              <NeedsRight missing={r.mitigation.missing} />
              <MitigationToggle address={target.address} permanent={!!p.mitigation.permanent} canWrite={can("mitigation")} />
            </div>
          )}
        </OvhSection>
      </div>

      <OvhSection
        title="Game firewall"
        sub="GET /ip/{block}/game/{ip}. STRICT mode drops every UDP port not allowed below, at OVH's edge (2026-10-04 node-4 outage)."
        right={p.game && <LevelBadge level={p.game.verdict.level}>{p.game.exists ? (p.game.firewallModeEnabled ? "STRICT" : "off") : "none"} · {p.game.state ?? "-"}</LevelBadge>}
      >
        <ReadError error={p.errors.game} />
        {p.game && (
          <>
            <p className="mb-2 text-xs text-slate-400">{p.game.verdict.summary}{p.game.maxRules ? ` (max ${p.game.maxRules} rules)` : ""}</p>
            <NeedsRight missing={r.gameFirewall.missing} />
            <GameFirewallControls
              address={target.address}
              exists={p.game.exists}
              strict={p.game.firewallModeEnabled}
              state={p.game.state}
              rules={p.game.rules.map((x) => ({ id: String(x.id), label: `${describeGameRule(x)}${x.state && x.state !== "ok" ? ` [${x.state}]` : ""}` }))}
              supportedProtocols={p.game.supportedProtocols}
              canWrite={can("gameFirewall")}
            />
          </>
        )}
      </OvhSection>

      <OvhSection
        title="Network firewall"
        sub="GET /ip/{block}/firewall. Up to 20 ordered permit/deny rules applied at OVH's edge when enabled."
        right={p.network && <LevelBadge level={p.network.verdict.level}>{p.network.exists ? (p.network.enabled ? "ENABLED" : "disabled") : "not added"}</LevelBadge>}
      >
        <ReadError error={p.errors.network} />
        {p.network && (
          <>
            <NeedsRight missing={r.networkFirewall.missing} />
            <NetworkFirewallControls
              address={target.address}
              exists={p.network.exists}
              enabled={p.network.enabled}
              rules={p.network.rules.map((x) => ({ sequence: String(x.sequence ?? x.id), label: `${x.action} ${x.protocol}${x.destinationPort ? ` port ${x.destinationPort}` : ""} from ${x.source ?? "any"}${x.state && x.state !== "ok" ? ` [${x.state}]` : ""}` }))}
              canWrite={can("networkFirewall")}
            />
          </>
        )}
      </OvhSection>

      <div className="grid gap-4 xl:grid-cols-2">
        <OvhSection title="Reverse DNS" sub="GET/POST /ip/{block}/reverse">
          <ReadError error={p.errors.reverse} />
          <NeedsRight missing={r.reverseDns.missing} />
          <ReverseDnsForm address={target.address} current={p.reverse} canWrite={can("reverseDns")} />
        </OvhSection>

        <OvhSection title="Virtual MAC" sub="OVH only forwards an additional IP's traffic from its registered vMAC; it must match the VM's NIC.">
          <ReadError error={vm.error} />
          <div className="space-y-1.5">
            <Fact k="Pool row vMAC" v={target.pool?.virtualMac ?? "—"} mono />
            <Fact k="OVH vMAC for this IP" v={vm.diagnosis.ovhMac ?? "—"} mono />
            <Fact k="VM NIC MAC(s)" v={vm.diagnosis.vmMacs.join(", ") || "—"} mono />
          </div>
          <p className="mt-2 text-xs">
            <LevelBadge level={vm.diagnosis.status === "ok" || vm.diagnosis.status === "not_applicable" ? "PASS" : vm.diagnosis.status === "unknown_vm" ? "WARN" : "FAIL"}>{vm.diagnosis.status}</LevelBadge>{" "}
            <span className="text-slate-400">{vm.diagnosis.explanation}</span>
          </p>
          <NeedsRight missing={vm.diagnosis.fixes.some((f) => f.fix !== "fix_db") ? r.virtualMac.missing : []} />
          <VmacRepair address={target.address} fixes={vm.diagnosis.fixes} canWrite={canAdmin && (r.virtualMac.allowed || vm.diagnosis.fixes.every((f) => f.fix === "fix_db"))} />
        </OvhSection>
      </div>
    </div>
  );
}

