input.content:
/**
 * OVH admin controls (lib/ovh-admin/**). Pure parsers/verdicts against sanitised
 * read-only recordings (test/fixtures/ovh-admin.json), validation, rights,
 * the audited write wrapper with fake deps (no network, no DB), the owner /
 * reboot-challenge policy, the alert plan, and source-level guards:
 * every OVH write goes through ONE audited wrapper, every action authenticates,
 * confirmations precede the write.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync } from "node:fs";
import {
  parsePort, parsePortRange, parseSourceCidr, parseGameProtocol, parseNetworkRule, networkRuleBody, parseReverseHostname,
  typedConfirmationMatches, normMac, vmacName, isIpv4,
} from "../lib/ovh-admin/validate.ts";
import {
  rulesAllow, featureRights, needsRightMessage, requiredRuleFor, isOverBroad, parseCredentialRules, rightsErrorFor, FEATURE_RIGHTS, exampleFor,
} from "../lib/ovh-admin/rights.ts";
import {
  parseIpFacts, zoneVerdict, parseMitigation, mitigationSummary, parseBlock, parseServiceInfos, renewalVerdict, daysUntil, parseNetworkSpec,
  trafficVerdict, parseTask, taskInFlight, parseIntervention, parseBoot, parseServer, bootMode, diagnoseVmac, macsFromPveConfig,
} from "../lib/ovh-admin/parse.ts";
import { ovhAdminWrite, RATE, type WriteDeps } from "../lib/ovh-admin/write.ts";
import { isOwner, parseOwnerEmails, ChallengeStore, vmFingerprint, CHALLENGE_TTL_MS, powerActionReboots } from "../lib/ovh-admin/policy.ts";
import { desiredOvhAccountAlerts } from "../lib/ovh-admin/alert-plan.ts";
import { planFleetAlerts, SWEEP_PREFIXES, FLEET_ALERT_PREFIXES } from "../lib/fleet-alert-plan.ts";
import { OvhHttpError } from "../lib/ovh.ts";

const FX = JSON.parse(readFileSync(new URL("./fixtures/ovh-admin.json", import.meta.url), "utf8"));
const SD = FX.schemaDerived;
const NOW = new Date("2026-10-06T12:00:00Z");
const src = (rel: string) => readFileSync(new URL(`../${rel}`, import.meta.url), "utf8");

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

test("ports and port ranges", () => {
  assert.deepEqual(parsePort("25565"), { ok: true, value: 25565 });
  for (const bad of ["0", "65536", "-1", "1.5", "", "abc", "123456"]) assert.equal(parsePort(bad).ok, false, bad);
  assert.deepEqual(parsePortRange("27015-27030"), { ok: true, value: { from: 27015, to: 27030 } });
  assert.deepEqual(parsePortRange(" 7777 "), { ok: true, value: { from: 7777, to: 7777 } });
  assert.deepEqual(parsePortRange("27015 - 27030"), { ok: true, value: { from: 27015, to: 27030 } });
  for (const bad of ["30-20", "1-2-3", "0-10", "10-70000", "", "a-b"]) assert.equal(parsePortRange(bad).ok, false, bad);
});

test("CIDR sources: bare IP becomes /32, host bits refused, /0 and 'any' mean any", () => {
  assert.deepEqual(parseSourceCidr("203.0.113.5"), { ok: true, value: "203.0.113.5/32" });
  assert.deepEqual(parseSourceCidr("203.0.113.0/24"), { ok: true, value: "203.0.113.0/24" });
  assert.deepEqual(parseSourceCidr(""), { ok: true, value: null });
  assert.deepEqual(parseSourceCidr("any"), { ok: true, value: null });
  assert.deepEqual(parseSourceCidr("0.0.0.0/0"), { ok: true, value: null });
  const hb = parseSourceCidr("203.0.113.5/24");
  assert.equal(hb.ok, false);
  assert.match((hb as any).error, /did you mean 203\.0\.113\.0\/24/);
  for (const bad of ["256.1.1.1", "1.2.3", "1.2.3.4/33", "1.2.3.4/x", "1.2.3.4/24/1", "::1"]) assert.equal(parseSourceCidr(bad).ok, false, bad);
  assert.equal(isIpv4("01.2.3.4"), false);
});

test("reverse hostnames: FQDN, LDH labels, trailing dot added, lower-cased", () => {
  assert.deepEqual(parseReverseHostname("Mail.Example.COM"), { ok: true, value: "mail.example.com." });
  assert.deepEqual(parseReverseHostname("mail.example.com."), { ok: true, value: "mail.example.com." });
  for (const bad of ["localhost", "-a.example.com", "a-.example.com", "a..example.com", "a.example.123", "a_b.example.com", "", "a".repeat(64) + ".com", `${"a.".repeat(127)}com`]) {
    assert.equal(parseReverseHostname(bad).ok, false, bad);
  }
});

test("game protocol: global enum + the IP's own supportedProtocols", () => {
  const supported = FX.gameOff.supportedProtocols;
  assert.equal(parseGameProtocol("other", supported).ok, true);
  assert.equal(parseGameProtocol("valheim").ok, true); // in the global enum
  const r = parseGameProtocol("valheim", supported); // ...but not supported on this recorded IP
  assert.equal(r.ok, false);
  assert.match((r as any).error, /does not support/);
  assert.equal(parseGameProtocol("nope").ok, false);
});

test("network rule validation and the exact OVH body", () => {
  const r = parseNetworkRule({ sequence: "3", action: "permit", protocol: "udp", ports: "27015-27030", source: "203.0.113.0/24" });
  assert.equal(r.ok, true);
