function fakeDeps(over: Partial<WriteDeps> = {}) {
  const sent: any[] = [];
  const audits: string[] = [];
  const hits = new Map<string, number>();
  const once = new Set<string>();
  const deps: WriteDeps = {
    send: async (m, p, b) => { sent.push([m, p, b]); return { taskId: 1 }; },
    rules: async () => parseCredentialRules(FX.currentCredentialWildcard),
    audit: async (_u, a, d) => { audits.push(`${a} ${d}`); },
    rateLimit: (k, o) => { const n = (hits.get(k) ?? 0) + 1; hits.set(k, n); return { ok: n <= o.max, retryAfterSec: 9 }; },
    claimOnce: (k) => { if (once.has(k)) return false; once.add(k); return true; },
    sandbox: false,
    ...over,
  };
  return { deps, sent, audits };
}

const req = (state: { v: boolean }, over: any = {}) => ({
  actor: { id: "admin1" },
  action: "ovh.game.strict",
  target: "203.0.113.21",
  method: "PUT" as const,
  path: "/ip/203.0.113.21%2F32/game/203.0.113.21",
  body: { firewallModeEnabled: false },
  read: async () => ({ enabled: state.v }),
  isNoop: (s: { enabled: boolean }) => s.enabled === false,
  ...over,
});

test("wrapper: sends once, audits request + ok, returns before/after read back from OVH", async () => {
  const state = { v: true };
  const { deps, sent, audits } = fakeDeps({ send: async (m, p, b) => { sent.push([m, p, b]); state.v = false; return null; } });
  const r = await ovhAdminWrite(req(state), deps);
  assert.equal(r.ok, true);
  assert.deepEqual([(r as any).noop, (r as any).before, (r as any).after], [false, { enabled: true }, { enabled: false }]);
  assert.equal(sent.length, 1);
  assert.deepEqual(audits.map((a) => a.split(" ")[0]), ["ovh.game.strict.request", "ovh.game.strict.ok"]);
  assert.match(audits[0], /before=\{"enabled":true\}/);
});

test("wrapper is idempotent: already in the requested state => nothing sent, a .noop audit row", async () => {
  const { deps, sent, audits } = fakeDeps();
  const r = await ovhAdminWrite(req({ v: false }), deps);
  assert.equal((r as any).noop, true);
  assert.equal(sent.length, 0);
  assert.deepEqual(audits.map((a) => a.split(" ")[0]), ["ovh.game.strict.noop"]);
});

test("wrapper refuses before sending: sandbox, missing right, rate limit, double submit, unreadable state", async () => {
  {
    const { deps, sent } = fakeDeps({ sandbox: true });
    assert.equal((await ovhAdminWrite(req({ v: true }), deps)).ok, false);
    assert.equal(sent.length, 0);
  }
  {
    const { deps, sent } = fakeDeps({ rules: async () => parseCredentialRules(SD.scopedCredential) });
    const r = await ovhAdminWrite(req({ v: true }, { method: "POST", path: "/dedicated/server/ns1/reboot", action: "ovh.power.reboot" }), deps);
    assert.equal(r.ok, false);
    assert.equal((r as any).needsRight, true);
    assert.match((r as any).error, /POST \/dedicated\/server\/\*\/reboot/);
    assert.equal(sent.length, 0);
  }
  {
    const { deps, sent } = fakeDeps();
    let last: any;
    for (let i = 0; i < RATE.dangerous.max + 1; i++) last = await ovhAdminWrite(req({ v: true }, { rateClass: "dangerous", target: `t${i}` }), deps);
    assert.equal(last.ok, false);
    assert.match(last.error, /Too many/);
    assert.equal(sent.length, RATE.dangerous.max);
  }
  {
    const { deps, sent } = fakeDeps();
    const a = await ovhAdminWrite(req({ v: true }, { idempotencyKey: "k1" }), deps);
    const b = await ovhAdminWrite(req({ v: true }, { idempotencyKey: "k1" }), deps);
    assert.equal(a.ok, true);
    assert.equal(b.ok, false);
    assert.match((b as any).error, /just submitted/);
    assert.equal(sent.length, 1);
  }
  {
    const { deps, sent, audits } = fakeDeps();
    const r = await ovhAdminWrite(req({ v: true }, { read: async () => { throw new OvhHttpError("OVH GET x -> 503: down", 503); } }), deps);
    assert.equal(r.ok, false);
    assert.match((r as any).error, /nothing was changed/);
    assert.equal(sent.length, 0);
    assert.equal(audits.length, 0);
  }
});

