test("challenge: single-use, 5-minute, bound to admin, exact name, VM count and an unchanged VM list", async () => {
  let t = 1_000_000;
  const store = new ChallengeStore(() => t);
  const vms = [{ id: "a", status: "RUNNING" }, { id: "b", status: "STOPPED" }];
  const fp = vmFingerprint(vms);
  assert.equal(fp, vmFingerprint([...vms].reverse()), "order-independent");
  const issue = () => store.issue({ userId: "u1", nodeId: "n1", nodeName: "node-4", action: "reboot", fingerprint: fp, vmCount: 2 });
  const good = { userId: "u1", typedName: "node-4", ackVmCount: 2, currentFingerprint: () => fp };

  const c1 = issue();
  assert.equal((await store.redeem({ ...good, nonce: c1.nonce })).ok, true);
  assert.equal((await store.redeem({ ...good, nonce: c1.nonce })).ok, false, "reuse refused");

  const bad = async (over: any) => { const c = issue(); return store.redeem({ ...good, nonce: c.nonce, ...over }); };
  assert.match(((await bad({ typedName: "Node-4" })) as any).error, /does not match/);
  assert.match(((await bad({ ackVmCount: 1 })) as any).error, /number of affected/);
  assert.match(((await bad({ userId: "u2" })) as any).error, /another admin/);
  assert.match(((await bad({ currentFingerprint: () => vmFingerprint([...vms, { id: "c", status: "RUNNING" }]) })) as any).error, /stale page/);
  assert.match(((await bad({ currentFingerprint: () => vmFingerprint([{ id: "a", status: "STOPPED" }, vms[1]]) })) as any).error, /stale page/);
  assert.match(((await store.redeem({ ...good, nonce: "zz" })) as any).error, /malformed/);

  const c2 = issue();
  t += CHALLENGE_TTL_MS + 1;
  assert.match(((await store.redeem({ ...good, nonce: c2.nonce })) as any).error, /expired/);

  // A wrong attempt burns the token: the correct retry with the same nonce is refused.
  t = 2_000_000;
  const c3 = issue();
  await store.redeem({ ...good, nonce: c3.nonce, typedName: "nope" });
  assert.equal((await store.redeem({ ...good, nonce: c3.nonce })).ok, false);
  assert.equal(powerActionReboots("rescue_on"), false);
  assert.equal(powerActionReboots("rescue_on_reboot"), true);
});

