  for (const [k, file] of [["ipAudit", "worker/ip-audit.ts"], ["offsiteBackup", "worker/offsite-backup-sweep.ts"], ["ovhFirewall", "worker/ovh-game-firewall-sweep.ts"], ["ovhAccount", "worker/ovh-account-sweep.ts"]]) {
    assert.match(src(file), new RegExp(`prefixes: SWEEP_PREFIXES\\.${k}`), `${file} must pass its own prefixes`);
