});

// ---------------------------------------------------------------------------
// Source-level guards
// ---------------------------------------------------------------------------

function walk(dir: string, out: string[] = []): string[] {
  const base = new URL(`../${dir}`, import.meta.url);
  for (const e of readdirSync(base)) {
    const rel = `${dir}/${e}`;
    if (e === "node_modules" || e.startsWith(".")) continue;
    const st = statSync(new URL(`../${rel}`, import.meta.url));
    if (st.isDirectory()) walk(rel, out);
    else if (/\.(ts|tsx|mjs|js)$/.test(e)) out.push(rel);
  }
  return out;
}

/**
 * Pre-existing OVH write sites that pre-date the admin controls. They are the
 * provisioning / release / VM-move / one-off-script paths run by the worker or
 * by hand, not admin controls. Listed so a NEW write site anywhere else fails.
 */
const LEGACY_WRITE_SITES: Record<string, string> = {
  "lib/ovh.ts": "the client itself + ovhApi.createVirtualMac/setReverse definitions",
  "lib/dedicated-ip.ts": "provisioning: allocateDedicatedIp creates the vMAC; releaseDedicatedIp deletes it; setDedicatedReverse default path",
  "lib/vm-move/ovh-ip-move.ts": "worker VM move between nodes (IP move + vMAC)",
  "worker/admin-ops.ts": "worker ADMIN_OPS job: IP release removes the vMAC",
  "scripts/set-mail-ptr.ts": "one-off operator script for the mail relay PTR",
  "lib/ovh-admin/transport.ts": "rawOvhSend: the transport the audited wrapper uses",
};

test("HAZARD: every OVH write from the admin controls goes through ONE audited wrapper", () => {
  const files = [...walk("lib"), ...walk("app"), ...walk("components"), ...walk("worker"), ...walk("scripts")];
  const WRITE = /\bovh\(\s*(["'`](POST|PUT|DELETE)["'`]|method\b)|\bovhApi\.(createVirtualMac|setReverse)\(|\brawOvhSend\(/;
  const offenders: string[] = [];
  for (const f of files) {
    const s = src(f);
    if (!WRITE.test(s)) continue;
    if (f === "lib/ovh-admin/write.ts") continue; // THE wrapper
    if (f in LEGACY_WRITE_SITES) continue;
    offenders.push(f);
  }
  assert.deepEqual(offenders, [], "New OVH write call sites must go through lib/ovh-admin/write.ts ovhAdminWrite");
  // rawOvhSend is imported only by the wrapper.
  const importers = files.filter((f) => /\brawOvhSend\b/.test(src(f)) && f !== "lib/ovh-admin/transport.ts");
  assert.deepEqual(importers, ["lib/ovh-admin/write.ts"]);
  // Nothing in lib/ovh-admin except write.ts/transport.ts may import the raw client's ovh().
  for (const f of walk("lib/ovh-admin")) {
    if (f.endsWith("/write.ts") || f.endsWith("/transport.ts")) continue;
    assert.doesNotMatch(src(f), /import\s*\{[^}]*\bovh\b[^}]*\}\s*from\s*["']\.\.\/ovh["']/, `${f} imports the raw ovh() client`);
  }
  // The sweeps and the readers stay GET-only.
  for (const f of ["worker/ovh-account-sweep.ts", "lib/ovh-admin/read.ts", "lib/ovh-game-firewall.ts"]) {
    assert.doesNotMatch(src(f), /["'`](POST|PUT|DELETE)["'`]/, `${f} must stay GET-only`);
  }
  // The audited reverse path is what the old IP-pool form uses now.
  assert.match(src("lib/actions-ovh.ts"), /setDedicatedReverse\(address, parsed\.value, async[\s\S]*auditedReverseWrite/);
});

test("HAZARD: every lib/ovh-admin/actions.ts export authenticates; power actions are owner-only", () => {
  const a = src("lib/ovh-admin/actions.ts");
  assert.match(a.split("\n")[0], /^"use server";/);
  const exports = [...a.matchAll(/^export async function (\w+)[\s\S]*?^}/gm)];
  assert.ok(exports.length >= 15, `found ${exports.length}`);
  for (const m of exports) {
    const [body, name] = [m[0], m[1]];
    assert.match(body, /await requireOvh(Admin|Owner)\(\)/, `${name} must authenticate inside the function`);
    if (/Power/.test(name)) assert.match(body, /await requireOvhOwner\(\)/, `${name} must be owner-only`);
  }
  // The guards themselves: real session, ADMIN role, fleet area, not impersonating.
  const guard = a.slice(a.indexOf("async function requireOvhAdmin"), a.indexOf("async function requireOvhOwner"));
  assert.match(guard, /realUser\(\)/);
  assert.match(guard, /user\.role !== "ADMIN"/);
  assert.match(guard, /canAccess\(user\.role, "fleet"\)/);
  assert.match(guard, /impersonating\(\)/);
  const owner = a.slice(a.indexOf("async function requireOvhOwner"), a.indexOf("/** Turn a guard throw"));
  assert.match(owner, /isOwner\(/);
});

test("HAZARD: dangerous actions check the typed confirmation BEFORE the write", () => {
  const a = src("lib/ovh-admin/actions.ts");
  for (const name of ["setGameStrict", "setNetworkFirewallEnabled", "applyVmacFix", "setPermanentMitigation", "unblockIp"]) {
    const start = a.indexOf(`export async function ${name}(`);
    const body = a.slice(start, a.indexOf("\nexport async function", start + 10));
    const c = body.indexOf("typedConfirmationMatches(");
    const w = body.search(/ovhAdminWrite\(|readVmacPanel\(/);
    assert.ok(c > 0 && w > c, `${name}: typed confirmation must precede the OVH write`);
  }
  const ex = a.slice(a.indexOf("export async function executePowerAction("));
  assert.ok(ex.indexOf("powerChallenges().redeem(") < ex.indexOf("ovhAdminWrite("), "power: challenge redeemed before any write");
  // The stub can never serve production.
  assert.match(src("lib/ovh-admin/transport.ts"), /NXEON_OVH_ADMIN_STUB === "1" && process\.env\.NODE_ENV !== "production"/);
});

