test("network rule validation and the exact OVH body", () => {
  const r = parseNetworkRule({ sequence: "3", action: "permit", protocol: "udp", ports: "27015-27030", source: "203.0.113.0/24" });
  assert.equal(r.ok, true);
  assert.deepEqual(networkRuleBody((r as any).value), { sequence: 3, action: "permit", protocol: "udp", destinationPortRange: { from: 27015, to: 27030 }, source: "203.0.113.0/24" });
  const one = parseNetworkRule({ sequence: 0, action: "deny", protocol: "tcp", ports: "22" });
  assert.deepEqual(networkRuleBody((one as any).value), { sequence: 0, action: "deny", protocol: "tcp", destinationPort: 22 });
  assert.equal(parseNetworkRule({ sequence: "20", action: "permit", protocol: "tcp" }).ok, false);
  assert.equal(parseNetworkRule({ sequence: "1", action: "allow", protocol: "tcp" }).ok, false);
  assert.equal(parseNetworkRule({ sequence: "1", action: "permit", protocol: "icmp", ports: "80" }).ok, false);
  assert.equal(parseNetworkRule({ sequence: "1", action: "permit", protocol: "sctp" }).ok, false);
});

test("typed confirmations are exact and case-sensitive", () => {
  assert.equal(typedConfirmationMatches("node-4", " node-4 "), true);
  for (const bad of ["Node-4", "node-", "node-44", "", null, undefined, 4]) assert.equal(typedConfirmationMatches("node-4", bad), false, String(bad));
  assert.equal(typedConfirmationMatches("", ""), false);
  assert.equal(normMac("02-00-00-AA-BB-CC"), "02:00:00:aa:bb:cc");
  assert.equal(normMac("02:00:00:aa:bb"), null);
  assert.equal(vmacName("web 01_x!"), "web01x");
});

