  assert.equal(fr.reboot.allowed, false);
  assert.deepEqual(fr.reboot.missing, [{ method: "POST", path: "/dedicated/server/*/reboot" }]);
  assert.equal(fr.unblock.allowed, false);
  assert.equal(isOverBroad(rules), false);
  // Encoded IP block paths match either form of rule.
  assert.equal(rulesAllow(rules, "PUT", "/ip/203.0.113.21%2F32/game/203.0.113.21"), true);
