test("needs-right messages name the template rule; a 403 maps to it", () => {
  assert.deepEqual(requiredRuleFor("POST", "/dedicated/server/ns1/reboot"), { method: "POST", path: "/dedicated/server/*/reboot" });
  assert.match(needsRightMessage("PUT", "/ip/1.2.3.4%2F32/game/1.2.3.4"), /PUT \/ip\/\*\/game\/\*/);
  assert.match(rightsErrorFor(new OvhHttpError("OVH POST /x -> 403: This call has not been granted", 403), "POST", "/ip/a/spam/b/unblock"), /Needs OVH API right POST \/ip\/\*\/spam\/\*\/unblock/);
  assert.match(rightsErrorFor(new Error("OVH PUT /x -> 500: boom"), "PUT", "/x"), /500/);
