test("every write path the actions module sends is covered by a FEATURE_RIGHTS rule", () => {
  const a = src("lib/ovh-admin/actions.ts");
  const writes = [...a.matchAll(/method: "(POST|PUT|DELETE)",[\s\S]{0,200}?path: `([^`]+)`/g)].map((m) => ({ method: m[1] as any, path: m[2].replace(/\$\{[^}]+\}/g, "x1") }));
  assert.ok(writes.length >= 12, `found ${writes.length} write sites`);
  const all = Object.values(FEATURE_RIGHTS).flatMap((f) => f.rules);
  for (const w of writes) assert.ok(rulesAllow(all, w.method, w.path), `${w.method} ${w.path} has no FEATURE_RIGHTS rule`);
  // and the reverse helper
  assert.ok(rulesAllow(all, "POST", "/ip/x1/reverse"));
  for (const f of Object.values(FEATURE_RIGHTS)) for (const r of f.rules) assert.ok(rulesAllow([r], r.method, exampleFor(r.path)));
});

