// The audited write wrapper
// ---------------------------------------------------------------------------

function fakeDeps(over: Partial<WriteDeps> = {}) {
  const sent: any[] = [];
  const audits: string[] = [];
  const hits = new Map<string, number>();
  const once = new Set<string>();
  const deps: WriteDeps = {
    send: async (m, p, b) => { sent.push([m, p, b]); return { taskId: 1 }; },
    rules: async () => parseCredentialRules(FX.currentCredentialWildcard),
    audit: async (_u, a, d) => { audits.push(`${a} ${d}`); },
    rateLimit: (k, o) => { const n = (hits.get(k) ?? 0) + 1; hits.set(k, n); return { ok: n <= o.max, retryAfterSec: 9 }; },
    claimOnce: (k) => { if (once.has(k)) return false; once.add(k); return true; },
    sandbox: false,
    ...over,
  };
  return { deps, sent, audits };
}

const req = (state: { v: boolean }, over: any = {}) => ({
  actor: { id: "admin1" },
  action: "ovh.game.strict",
  target: "203.0.113.21",
  method: "PUT" as const,
  path: "/ip/203.0.113.21%2F32/game/203.0.113.21",
  body: { firewallModeEnabled: false },
  read: async () => ({ enabled: state.v }),
  isNoop: (s: { enabled: boolean }) => s.enabled === false,
  ...over,
});

test("wrapper: sends once, audits request + ok, returns before/after read back from OVH", async () => {
  const state = { v: true };
  const { deps, sent, audits } = fakeDeps({ send: async (m, p, b) => { sent.push([m, p, b]); state.v = false; return null; } });
  const r = await ovhAdminWrite(req(state), deps);
  assert.equal(r.ok, true);
  assert.deepEqual([(r as any).noop, (r as any).before, (r as any).after], [false, { enabled: true }, { enabled: false }]);
  assert.equal(sent.length, 1);
  assert.deepEqual(audits.map((a) => a.split(" ")[0]), ["ovh.game.strict.request", "ovh.game.strict.ok"]);
  assert.match(audits[0], /before=\{"enabled":true\}/);
});

test("wrapper is idempotent: already in the requested state => nothing sent, a .noop audit row", async () => {
  const { deps, sent, audits } = fakeDeps();
  const r = await ovhAdminWrite(req({ v: false }), deps);
  assert.equal((r as any).noop, true);
  assert.equal(sent.length, 0);
  assert.deepEqual(audits.map((a) => a.split(" ")[0]), ["ovh.game.strict.noop"]);
});

test("wrapper refuses before sending: sandbox, missing right, rate limit, double submit, unreadable state", async () => {
  {
    const { deps, sent } = fakeDeps({ sandbox: true });
    assert.equal((await ovhAdminWrite(req({ v: true }), deps)).ok, false);
    assert.equal(sent.length, 0);
  }
  {
    const { deps, sent } = fakeDeps({ rules: async () => parseCredentialRules(SD.scopedCredential) });
    const r = await ovhAdminWrite(req({ v: true }, { method: "POST", path: "/dedicated/server/ns1/reboot", action: "ovh.power.reboot" }), deps);
    assert.equal(r.ok, false);
    assert.equal((r as any).needsRight, true);
    assert.match((r as any).error, /POST \/dedicated\/server\/\*\/reboot/);
    assert.equal(sent.length, 0);
  }
  {
    const { deps, sent } = fakeDeps();
    let last: any;
    for (let i = 0; i < RATE.dangerous.max + 1; i++) last = await ovhAdminWrite(req({ v: true }, { rateClass: "dangerous", target: `t${i}` }), deps);
    assert.equal(last.ok, false);
    assert.match(last.error, /Too many/);
    assert.equal(sent.length, RATE.dangerous.max);
  }
  {
    const { deps, sent } = fakeDeps();
    const a = await ovhAdminWrite(req({ v: true }, { idempotencyKey: "k1" }), deps);
    const b = await ovhAdminWrite(req({ v: true }, { idempotencyKey: "k1" }), deps);
    assert.equal(a.ok, true);
    assert.equal(b.ok, false);
    assert.match((b as any).error, /just submitted/);
    assert.equal(sent.length, 1);
  }
  {
    const { deps, sent, audits } = fakeDeps();
    const r = await ovhAdminWrite(req({ v: true }, { read: async () => { throw new OvhHttpError("OVH GET x -> 503: down", 503); } }), deps);
    assert.equal(r.ok, false);
    assert.match((r as any).error, /nothing was changed/);
    assert.equal(sent.length, 0);
    assert.equal(audits.length, 0);
  }
});

test("wrapper: an OVH 403 on send becomes 'needs OVH API right', audited as .error", async () => {
  const { deps, audits } = fakeDeps({ send: async () => { throw new OvhHttpError("OVH PUT x -> 403: This call has not been granted", 403); } });
  const r = await ovhAdminWrite(req({ v: true }), deps);
  assert.equal(r.ok, false);
  assert.equal((r as any).needsRight, true);
  assert.deepEqual(audits.map((a) => a.split(" ")[0]), ["ovh.game.strict.request", "ovh.game.strict.error"]);
});

// ---------------------------------------------------------------------------
// Owner policy + reboot/rescue challenge
// ---------------------------------------------------------------------------

test("owner: explicit list wins; sole ADMIN is owner only while alone; non-admins never", () => {
  const admin = { role: "ADMIN", email: "Boss@Example.com" };
  assert.deepEqual(parseOwnerEmails(" boss@example.com, x ,y@z.io"), ["boss@example.com", "y@z.io"]);
  assert.equal(isOwner(admin, ["boss@example.com"], 3).ok, true);
  assert.equal(isOwner(admin, ["other@example.com"], 1).ok, false);
  assert.equal(isOwner(admin, [], 1).ok, true);
  const two = isOwner(admin, [], 2);
  assert.equal(two.ok, false);
  assert.match((two as any).error, /NXEON_OWNER_EMAILS/);
  for (const role of ["SUPPORT", "BILLING", "EMPLOYEE", "CUSTOMER"]) assert.equal(isOwner({ role, email: "boss@example.com" }, ["boss@example.com"], 1).ok, false, role);
});

test("challenge: single-use, 5-minute, bound to admin, exact name, VM count and an unchanged VM list", async () => {
  let t = 1_000_000;
  const store = new ChallengeStore(() => t);
  const vms = [{ id: "a", status: "RUNNING" }, { id: "b", status: "STOPPED" }];
  const fp = vmFingerprint(vms);
  assert.equal(fp, vmFingerprint([...vms].reverse()), "order-independent");
  const issue = () => store.issue({ userId: "u1", nodeId: "n1", nodeName: "node-4", action: "reboot", fingerprint: fp, vmCount: 2 });
  const good = { userId: "u1", typedName: "node-4", ackVmCount: 2, currentFingerprint: () => fp };

  const c1 = issue();
  assert.equal((await store.redeem({ ...good, nonce: c1.nonce })).ok, true);
  assert.equal((await store.redeem({ ...good, nonce: c1.nonce })).ok, false, "reuse refused");

  const bad = async (over: any) => { const c = issue(); return store.redeem({ ...good, nonce: c.nonce, ...over }); };
  assert.match(((await bad({ typedName: "Node-4" })) as any).error, /does not match/);
  assert.match(((await bad({ ackVmCount: 1 })) as any).error, /number of affected/);
  assert.match(((await bad({ userId: "u2" })) as any).error, /another admin/);
  assert.match(((await bad({ currentFingerprint: () => vmFingerprint([...vms, { id: "c", status: "RUNNING" }]) })) as any).error, /stale page/);
  assert.match(((await bad({ currentFingerprint: () => vmFingerprint([{ id: "a", status: "STOPPED" }, vms[1]]) })) as any).error, /stale page/);
  assert.match(((await store.redeem({ ...good, nonce: "zz" })) as any).error, /malformed/);

  const c2 = issue();
  t += CHALLENGE_TTL_MS + 1;
  assert.match(((await store.redeem({ ...good, nonce: c2.nonce })) as any).error, /expired/);

  // A wrong attempt burns the token: the correct retry with the same nonce is refused.
  t = 2_000_000;
  const c3 = issue();
  await store.redeem({ ...good, nonce: c3.nonce, typedName: "nope" });
  assert.equal((await store.redeem({ ...good, nonce: c3.nonce })).ok, false);
  assert.equal(powerActionReboots("rescue_on"), false);
  assert.equal(powerActionReboots("rescue_on_reboot"), true);
});

// ---------------------------------------------------------------------------
// Alert plan
// ---------------------------------------------------------------------------

test("a blocked customer IP raises CRITICAL naming the server + owner; renewal alert; unreadable nodes never resolve", () => {
  const blocked = parseBlock("antihack", SD.antihackBlocked)!;
  const svcOff = { ...parseServiceInfos(FX.serviceInfosAuto)!, autoRenew: false };
  const { desired, readNodeIds } = desiredOvhAccountAlerts(
    [
      {
        nodeId: "n4", nodeName: "node-4", serviceName: "ns000004", service: svcOff,
        ips: [
          { ip: "203.0.113.21", source: "node", label: "node public IP", server: null, blocks: [] },
          { ip: "198.51.100.117", source: "pool", label: null, server: { hostname: "web-01-pvm4", owner: "c@example.com", vmid: 133 }, blocks: [blocked] },
        ],
      },
      { nodeId: "n5", nodeName: "node-5", serviceName: "ns000005", service: null, ips: [{ ip: "192.0.2.10", source: "node", label: null, server: null, blocks: null }] },
    ],
    { now: NOW, renewalAlertDays: 14 },
  );
  const block = desired.find((d) => d.dimension === "OVH-BLOCK:antihack:198.51.100.117")!;
  assert.equal(block.severity, "CRITICAL");
  assert.match(block.title, /web-01-pvm4/);
  assert.match(block.detail, /customer server web-01-pvm4 \(VM 133\), owner c@example\.com/);
  assert.match(block.detail, /compromised VM/);
  assert.match(block.detail, /\/admin\/ips\/198\.51\.100\.117/);
  const renew = desired.find((d) => d.dimension === "OVH-RENEW:ns000004")!;
  assert.equal(renew.severity, "WARN");
  assert.match(renew.title, /auto-renew is OFF/);
  assert.deepEqual([...readNodeIds], ["n4"]);
  assert.ok(FLEET_ALERT_PREFIXES.includes("OVH-BLOCK:" as any) && FLEET_ALERT_PREFIXES.includes("OVH-RENEW:" as any));
});

test("REGRESSION: a sweep no longer resolves another sweep's open alerts (OVH-GAME-FW flapped 4x on 2026-10-06)", () => {
  const open = [
    { id: "a1", nodeId: "p", dimension: "OVH-GAME-FW:198.51.100.200", severity: "CRITICAL", lastNotifiedAt: NOW },
    { id: "a2", nodeId: "p", dimension: "IP-CLASH:10.20.0.5", severity: "CRITICAL", lastNotifiedAt: NOW },
  ];
  const names = new Map([["p", "primary"]]);
  // ip-audit reads node p, finds no clash: it may resolve its own IP-CLASH, never the OVH alert.
  const ipAudit = planFleetAlerts({ desired: [], open, readNodeIds: new Set(["p"]), nodeNames: names, now: NOW, prefixes: SWEEP_PREFIXES.ipAudit });
  assert.deepEqual(ipAudit.map((o) => (o as any).id), ["a2"]);
  const ovh = planFleetAlerts({ desired: [], open, readNodeIds: new Set(["p"]), nodeNames: names, now: NOW, prefixes: SWEEP_PREFIXES.ovhAccount });
  assert.deepEqual(ovh, []);
  for (const [k, file] of [["ipAudit", "worker/ip-audit.ts"], ["offsiteBackup", "worker/offsite-backup-sweep.ts"], ["ovhFirewall", "worker/ovh-game-firewall-sweep.ts"], ["ovhAccount", "worker/ovh-account-sweep.ts"]]) {
    assert.match(src(file), new RegExp(`prefixes: SWEEP_PREFIXES\\.${k}`), `${file} must pass its own prefixes`);
  }
});

// ---------------------------------------------------------------------------
// Source-level guards
// ---------------------------------------------------------------------------

function walk(dir: string, out: string[] = []): string[] {
  const base = new URL(`../${dir}`, import.meta.url);
  for (const e of readdirSync(base)) {
    const rel = `${dir}/${e}`;
    if (e === "node_modules" || e.startsWith(".")) continue;
    const st = statSync(new URL(`../${rel}`, import.meta.url));
    if (st.isDirectory()) walk(rel, out);
    else if (/\.(ts|tsx|mjs|js)$/.test(e)) out.push(rel);
  }
  return out;
}

/**
 * Pre-existing OVH write sites that pre-date the admin controls. They are the
 * provisioning / release / VM-move / one-off-script paths run by the worker or
 * by hand, not admin controls. Listed so a NEW write site anywhere else fails.
 */
const LEGACY_WRITE_SITES: Record<string, string> = {
  "lib/ovh.ts": "the client itself + ovhApi.createVirtualMac/setReverse definitions",
  "lib/dedicated-ip.ts": "provisioning: allocateDedicatedIp creates the vMAC; releaseDedicatedIp deletes it; setDedicatedReverse default path",
  "lib/vm-move/ovh-ip-move.ts": "worker VM move between nodes (IP move + vMAC)",
  "worker/admin-ops.ts": "worker ADMIN_OPS job: IP release removes the vMAC",
  "scripts/set-mail-ptr.ts": "one-off operator script for the mail relay PTR",
  "lib/ovh-admin/transport.ts": "rawOvhSend: the transport the audited wrapper uses",
};

test("HAZARD: every OVH write from the admin controls goes through ONE audited wrapper", () => {
  const files = [...walk("lib"), ...walk("app"), ...walk("components"), ...walk("worker"), ...walk("scripts")];
  const WRITE = /\bovh\(\s*(["'`](POST|PUT|DELETE)["'`]|method\b)|\bovhApi\.(createVirtualMac|setReverse)\(|\brawOvhSend\(/;
  const offenders: string[] = [];
  for (const f of files) {
    const s = src(f);
    if (!WRITE.test(s)) continue;
    if (f === "lib/ovh-admin/write.ts") continue; // THE wrapper
    if (f in LEGACY_WRITE_SITES) continue;
    offenders.push(f);
  }
  assert.deepEqual(offenders, [], "New OVH write call sites must go through lib/ovh-admin/write.ts ovhAdminWrite");
  // rawOvhSend is imported only by the wrapper.
  const importers = files.filter((f) => /\brawOvhSend\b/.test(src(f)) && f !== "lib/ovh-admin/transport.ts");
  assert.deepEqual(importers, ["lib/ovh-admin/write.ts"]);
  // Nothing in lib/ovh-admin except write.ts/transport.ts may import the raw client's ovh().
  for (const f of walk("lib/ovh-admin")) {
    if (f.endsWith("/write.ts") || f.endsWith("/transport.ts")) continue;
    assert.doesNotMatch(src(f), /import\s*\{[^}]*\bovh\b[^}]*\}\s*from\s*["']\.\.\/ovh["']/, `${f} imports the raw ovh() client`);
  }
  // The sweeps and the readers stay GET-only.
  for (const f of ["worker/ovh-account-sweep.ts", "lib/ovh-admin/read.ts", "lib/ovh-game-firewall.ts"]) {
    assert.doesNotMatch(src(f), /["'`](POST|PUT|DELETE)["'`]/, `${f} must stay GET-only`);
  }
  // The audited reverse path is what the old IP-pool form uses now.
  assert.match(src("lib/actions-ovh.ts"), /setDedicatedReverse\(address, parsed\.value, async[\s\S]*auditedReverseWrite/);
});

test("HAZARD: every lib/ovh-admin/actions.ts export authenticates; power actions are owner-only", () => {
  const a = src("lib/ovh-admin/actions.ts");
  assert.match(a.split("\n")[0], /^"use server";/);
  const exports = [...a.matchAll(/^export async function (\w+)[\s\S]*?^}/gm)];
  assert.ok(exports.length >= 15, `found ${exports.length}`);
  for (const m of exports) {
    const [body, name] = [m[0], m[1]];
    assert.match(body, /await requireOvh(Admin|Owner)\(\)/, `${name} must authenticate inside the function`);
    if (/Power/.test(name)) assert.match(body, /await requireOvhOwner\(\)/, `${name} must be owner-only`);
  }
  // The guards themselves: real session, ADMIN role, fleet area, not impersonating.
  const guard = a.slice(a.indexOf("async function requireOvhAdmin"), a.indexOf("async function requireOvhOwner"));
  assert.match(guard, /realUser\(\)/);
  assert.match(guard, /user\.role !== "ADMIN"/);
  assert.match(guard, /canAccess\(user\.role, "fleet"\)/);
  assert.match(guard, /impersonating\(\)/);
  const owner = a.slice(a.indexOf("async function requireOvhOwner"), a.indexOf("/** Turn a guard throw"));
  assert.match(owner, /isOwner\(/);
});

test("HAZARD: dangerous actions check the typed confirmation BEFORE the write", () => {
  const a = src("lib/ovh-admin/actions.ts");
  for (const name of ["setGameStrict", "setNetworkFirewallEnabled", "applyVmacFix", "setPermanentMitigation", "unblockIp"]) {
    const start = a.indexOf(`export async function ${name}(`);
    const body = a.slice(start, a.indexOf("\nexport async function", start + 10));
    const c = body.indexOf("typedConfirmationMatches(");
    const w = body.search(/ovhAdminWrite\(|readVmacPanel\(/);
    assert.ok(c > 0 && w > c, `${name}: typed confirmation must precede the OVH write`);
  }
  const ex = a.slice(a.indexOf("export async function executePowerAction("));
  assert.ok(ex.indexOf("powerChallenges().redeem(") < ex.indexOf("ovhAdminWrite("), "power: challenge redeemed before any write");
  // The stub can never serve production.
  assert.match(src("lib/ovh-admin/transport.ts"), /NXEON_OVH_ADMIN_STUB === "1" && process\.env\.NODE_ENV !== "production"/);
});

