input.command:
cat > /root/agent-notes/ovh-admin/shots/shoot.mjs <<'EOF'
import { chromium } from "/tank/nxeon-wt-ovhadmin/node_modules/playwright/index.mjs";
const [base, token, node1, node2] = process.argv.slice(2);
const out = "/root/agent-notes/ovh-admin";
const b = await chromium.launch();
const ctx = await b.newContext({ viewport: { width: 1440, height: 1000 } });
await ctx.addCookies([{ name: "nxeon_session", value: token, domain: "127.0.0.1", path: "/" }]);
const p = await ctx.newPage();
const go = async (u) => { await p.goto(base + u, { waitUntil: "networkidle", timeout: 240000 }); await p.waitForTimeout(800); };
await go(`/admin/nodes/${node1}`);
await p.locator("#ovh").scrollIntoViewIfNeeded();
await p.locator("#ovh").screenshot({ path: `${out}/node-ovh-panel.png` });
// power: prepare a reboot warning (does not execute)
await p.getByRole("button", { name: "Hard reboot…" }).click();
await p.getByText("Type the node name").waitFor({ timeout: 60000 });
await p.waitForTimeout(500);
await p.locator("#ovh").screenshot({ path: `${out}/node-reboot-warning.png` });
await go(`/admin/nodes/${node2}`);
await p.locator("#ovh").screenshot({ path: `${out}/node-ovh-panel-bhs-autorenew-off.png` });
await go(`/admin/ips/203.0.113.22`);
await p.screenshot({ path: `${out}/ip-blocked-netfw-vmac-missing.png`, fullPage: true });
await go(`/admin/ips/203.0.113.21`);
await p.screenshot({ path: `${out}/ip-game-strict.png`, fullPage: true });
// strict OFF via typed confirmation, then capture the settle polling
await p.getByRole("button", { name: "Turn strict mode OFF" }).click();
await p.locator("input.font-mono").first().fill("203.0.113.21");
await p.getByRole("button", { name: "Turn strict mode OFF" }).last().click();
await p.getByText("Waiting for OVH to apply").waitFor({ timeout: 60000 }).catch(() => {});
await p.waitForTimeout(1500);
await p.screenshot({ path: `${out}/ip-game-strict-off-pending.png`, fullPage: true });
await p.getByText(/OVH: game: off \/ ok/).waitFor({ timeout: 90000 }).catch(() => {});
await p.waitForTimeout(1500);
await p.screenshot({ path: `${out}/ip-game-strict-off-settled.png`, fullPage: true });
await go(`/admin/ips/192.0.2.30`);
await p.screenshot({ path: `${out}/ip-wrong-zone.png`, fullPage: true });
await go(`/admin/ips/203.0.113.23`);
await p.screenshot({ path: `${out}/ip-under-attack.png`, fullPage: true });
const m = await ctx.newPage(); await m.setViewportSize({ width: 390, height: 844 });
await m.goto(base + `/admin/ips/203.0.113.22`, { waitUntil: "networkidle", timeout: 240000 });
await m.screenshot({ path: `${out}/ip-blocked-390.png`, fullPage: true });
await b.close();
console.log("shots done");
EOF
echo ok

